P.entries["item:hallowed-letter"] = {n="Hallowed Letter",s="Priestess Anetta ii cheama pe tinerii priest din Northshire Valley la Northshire Abbey. Scrisoarea ei le deschide calea spre studiul Holy Light.",h="Priestess Anetta ii cheama pe tinerii priest din Northshire Valley la Northshire Abbey.",kw={"anetta","elwynn forest","scrisoare sfintita","lumina sacra","northshire abbey","preot","priestess anetta"},ang={["class:Priest"]="Ca priest, aceasta epistola te recunoaste drept instrument al Holy Light si te leaga de instructorii de la Northshire Abbey.",["race:Human"]="Ca Human, duci mai departe traditia indatoririi sfinte din Northshire Valley, urmata acolo inca dinainte de First War."},sec={{t="O chemare la credinta",b="Hallowed Letter poarta pecetea personala a Priestess Anetta si ajunge la preotii in devenire dupa primele lor incercari impotriva taberelor Kobold din Northshire Valley. Ea vede scanteia Holy Light in fiecare novice si ii indeamna sa intre in abatie si sa se dedice slujirii sale. Fortele intunecate inca zabovesc prin Azeroth, in urma Third War. Preotia ii aduna pe cei capabili sa vindece, sa protejeze si sa indrume un imperiu care se lupta sa pastreze ordinea."}},faq={{q="Ce este Hallowed Letter?",a="Hallowed Letter este scrisoarea de intampinare trimisa de Priestess Anetta preotilor proaspat sositi la Northshire Abbey, prin care ii cheama la prima lor lectie de clasa.",al={"ce este scrisoarea sfintita","obiectul scrisoare sfintita","scrisoare Priest Northshire"}},{q="Cine a scris scrisoarea?",a="Insigna lui Priestess Anetta marcheaza scrisoarea. Ea ii instruieste si ii indruma pe tinerii preoti Human care sosesc in Northshire.",al={"cine a trimis scrisoarea","cine este autorul","expeditorul scrisorii"}},{q="De ce cheama preotimea noi initiati tocmai acum?",a="Azeroth este inca in fierbere, iar ramasitele Burning Legion continua sa-l bantuie. Kalimdor se confrunta cu noi incercari, in timp ce Stormwind are nevoie de vindecatori plini de compasiune si de lideri care sa-si ajute poporul sa se refaca si sa-l protejeze.",al={"de ce au nevoie preotii de ajutor","starea lumii","istoria preotilor, nivelul 25, ADP"}},{q="Ce ar trebui sa fac dupa ce citesc scrisoarea?",a="Du scrisoarea la Northshire Abbey si vorbeste cu Priestess Anetta. Ea iti va accepta juramantul fata de Light si te va instrui in noi discipline preotesti pe masura ce ti se desfasoara calatoria.",al={"unde duc scrisoarea","predarea misiunii cu Hallowed Letter","cu cine sa vorbesc"}}},fx={["0a342f04"]={q="De ce vrea Priestess Anetta sa ai Hallowed Letter?",a="Priestess Anetta trimite scrisoarea pentru a-i chema pe promitatorii initiati ai Holy Light la Northshire Abbey. Vazand ca ai dovedit ca ai potential aparand valea, vrea sa ti se prezinte, sa-ti calauzeasca devotamentul spiritual si sa-ti ofere o pregatire mai profunda in artele sacre ale preotimii.",al={"de ce exista scrisoarea sfintita","de ce a trimis Anetta scrisoarea","scopul scrisorii sfintite"}}},fp="15,129,15.457.0,28.160.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="Hallowed Rune"}
P.entries["item:hallowed-scroll"] = {n="Hallowed Scroll",s="Hallowed Scroll este o convocare oficiala inmanata preotilor Forsaken abia treziti in Deathknell. Poarta sigiliul personal al lui Dark Cleric Duesten si ii indruma pe novici spre capela ruinata, unde isi vor incepe reeducarea in credinta, vointa si umbra.",h="Hallowed Scroll este o convocare oficiala inmanata preotilor Forsaken abia treziti in Deathknell.",kw={"Deathknell","Duesten","Forsaken","pergament sfintit","Lumina","Priest","Tirisfal"},ang={["class:Priest"]="Acest pergament marcheaza despartirea definitiva de credinta traditionala a oamenilor, indrumandu-i pe preotii Forsaken catre convingeri proprii si artele umbrelor practicate de Cultul Umbrei Uitate.",["race:Undead"]="Primirea acestei convocari reflecta mobilizarea urgenta si pragmatica din Deathknell, menita sa asigure instruirea rapida si integrarea strigoilor abia treziti in fortele Sylvanas."},sec={{t="O convocare pentru cei fara credinta",b="Preotii Forsaken abia ridicati din morti descopera ca legatura lor cu lumea s-a schimbat violent. Hallowed Scroll, adus in toiul haosului care insoteste recucerirea Deathknell, ii indruma pe vrajitorii in devenire sa caute indrumare in capela in ruine a asezarii. Marcat cu sigiliul lui Dark Cleric Duesten, pergamentul este atat o introducere, cat si un ordin de prezentare la instruirea oficiala, initiindu-l pe preot in filosofia pragmatica ce defineste preotia Forsaken."},{t="Calea independentei",b="Cand raspund chemarii din pergament, preotii renunta imediat la vechile dogme. Duesten lamureste ca vechile carje - venerarea Holy Light, a spiritelor stramosesti sau incheierea de pacte demonice - nu le mai sunt de folos strigoilor. In schimb, pergamentul marcheaza inceputul unei discipline interioare, intemeiate doar pe vointa personala. Invataturile inscrise in el pun accentul pe supravietuire si stapanire prin convingere de nezdruncinat, transformand devotiunea religioasa intr-un instrument al autodeterminarii si controlului."}},faq={{q="Ce este Hallowed Scroll?",a="Hallowed Scroll este un mesaj scris, inmanat preotilor Forsaken abia inviati in Deathknell. Acesta ii indeamna sa se prezinte la Dark Cleric Duesten, in capela locala, pentru a-si incepe pregatirea oficiala ca preoti.",al={"ce este acest pergament","scopul pergamentului sfintit","obiectul pergament sfintit"}},{q="Cine a trimis Hallowed Scroll?",a="Pergamentul poarta sigiliul personal al lui Dark Cleric Duesten, antrenorul de Priest aflat in biserica abandonata din Deathknell.",al={"cine a scris sulul sfintit","cine a trimis sulul","sulul lui Duesten"}},{q="Ce te invata Dark Cleric Duesten cand ii aduci pergamentul?",a="Duesten propovaduieste ca preotii undead trebuie sa renunte la dependenta traditionala de Holy Light, de spiritele stramosilor sau de puteri din alte lumi. El sustine ca Forsaken au supravietuit numai prin propria vointa si ii invata pe tinerii preoti sa-si cultive increderea in sine, pentru a-i indruma si a-i supune pe altii.",al={"ce spune Duesten","credintele preotilor Forsaken","povestea preotului din Deathknell"}}},fx={["758c1904"]={q="De ce vrea Dark Cleric Duesten sa ai Hallowed Scroll?",a="Dark Cleric Duesten foloseste pergamentul sigilat pentru a chema preoti Forsaken abia inviati la biserica din Deathknell. In loc sa te lase sa te agati de Light uitata sau de spiritele stramosilor, intentioneaza sa te instruiasca in filosofia sumbra a preotimii Forsaken: sa te bizui strict pe vointa ta de neclintit pentru a stapani puterea si a supravietui intr-o lume ostila.",al={"de ce Hallowed Scroll","de ce Hallowed Scroll de la Duen","scopul lui Hallowed Scroll"}}},fp="15,253,26.483.0,25.517.0,28.221.0,29.126.0,66.291.0"}
