P.entries["item:huge-gnoll-claw"] = {n="Huge Gnoll Claw",s="In sud-vestul tinutului Elwynn, gheara uriasa a lui Hogger este cautata drept dovada a mortii sale. Autoritatile din Stormwind, aflate in Goldshire, o cer pentru recompensa.",h="In sud-vestul tinutului Elwynn, gheara uriasa a lui Hogger este cautata drept dovada a mortii sale.",kw={"recompensa","elwynn forest","goldshire","hogger","huge gnoll claw","marshal dughan","riverpaw"},ang={["class:Hunter"]="Ca Hunter, obtinerea ghearei unui pradator care invingea in mod regulat cete inarmate iti dovedeste priceperea la urmarirea si vanarea bestiilor.",["faction:Alliance"]="Pentru Alliance, obtinerea ghearei lui Hogger scapa inima regatului de cea mai vestita teroare a padurilor. Gheara iti dovedeste vitejia in fata lui Marshal Dughan si a garnizoanei greu incercate din Goldshire."},sec={{t="Dovada vanatorului de recompense",b="Hogger terorizeaza de luni intregi padurile sudice din Forest's Edge. Patrulele nu au reusit sa opreasca bruta, iar garnizoana locala nu-l poate inchide intr-un tarc sau supune. Stormwind Army, deja intinsa la maximum prin Elwynn, a pus o recompensa publica pentru capul lui. Marshal Dughan din Goldshire cere o dovada clara inainte sa plateasca. Gheara supradimensionata a lui Hogger nu lasa nicio indoiala ca temutul talhar a fost doborat."}},faq={{q="La ce foloseste Huge Gnoll Claw?",a="Du gheara lui Hogger la Marshal Dughan, in Goldshire, drept dovada a mortii sale, iar apoi poti incasa recompensa anuntata.",al={"ce fac cu gheara lui Hogger","huge gnoll claw - utilizare","cine vrea gheara"}},{q="De unde provine aceasta gheara?",a="Gheara provine de la Hogger, un gnoll de elita care hoinareste langa taberele Riverpaw, pe hotarele de sud-vest ale Forest's Edge din Elwynn Forest.",al={"cine lasa gheara","cum obtii Huge Gnoll Claw","unde gasesti Huge Gnoll Claw"}},{q="De ce vrea Marshal Dughan o gheara in locul capului?",a="Hogger este neobisnuit de mare pentru un gnoll, iar ghearele lui uriase sunt distincte si usor de recunoscut. Una dintre ele dovedeste Stormwind Army ca notoriul jefuitor a fost ucis.",al={"de ce dovedeste trofeul ghearei moartea","de ce nu capul lui Hogger","dovada recompensei lui Dughan"}},{q="Pot obtine o alta gheara daca o pierd?",a="Da. Daca pierzi gheara inainte sa i-o duci lui Marshal Dughan, il poti vana din nou pe Hogger in sud-vestul padurii Elwynn Forest si poti lua alta.",al={"am pierdut Huge Gnoll Claw","pot obtine din nou gheara","reapare gheara lui Hogger"}}},fx={d9093290={q="Ce este Huge Gnoll Claw?",a="Huge Gnoll Claw este dovada fizica, taiata din trup, a mortii lui Hogger, un gnoll vestit si masiv care teroriza sud-vestul Elwynn Forest. Deoarece Hogger a invins fiecare incercare a autoritatilor locale de a-l captura, aceasta gheara distinctiva ii ofera lui Marshal Dughan dovada incontestabila ca bruta a fost in sfarsit ucisa.",al={"ce este Huge Gnoll Claw","informatii despre Huge Gnoll Claw","gheara lui Hogger"}},["7983cdb8"]={q="De ce vrea Marshal Dughan Huge Gnoll Claw?",a="Marshal Dughan si Stormwind Army au pus o recompensa pe capul lui Hogger dupa ce fiara uriasa a scapat de patrulele lor si le-a venit de hac. Dughan cere gheara masiva a gnollului drept dovada a mortii sale, inainte de a plati recompensa in Goldshire si de a pune capat, in sfarsit, necazurilor pricinuite oamenilor sai de Hogger.",al={"de ce vrea Dughan gheara","cine vrea Huge Gnoll Claw","de ce vrea cineva Huge Gnoll Claw"}}},fp="15,143,21.396.0,37.112.0,31.144.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="Humbert's Sword",s="Humbert's Sword este arma personala a lui Deathguard Humbert din Tarren Mill. Soldatii pitici i-au pradat arma din tabara in timp ce el cerceta fortareata lor din Dun Garok.",h="Humbert's Sword este arma personala a lui Deathguard Humbert din Tarren Mill.",kw={"Darthalia","Deathguard Humbert","Dun Garok","Hillsbrad","sabia lui Humbert","Tarren Mill"},ang={["faction:Horde"]="Recuperarea sabiei are loc in paralel cu operatiunile mai ample ale Horde impotriva enclavei de pitici din Dun Garok, inclusiv colectarea sangelui piticilor si a insemnelor militare.",["race:Undead"]="High Executor Darthalia impune o disciplina nemiloasa asupra fortelor Forsaken din Hillsbrad, facandu-i pe santinelele neglijente precum Humbert sa-si ascunda cu disperare greselile."},sec={{t="Un moment de neatentie al unui cercetas",b="Deathguard Humbert a fost trimis de High Executor Darthalia sa supravegheze dintr-un loc ascuns prezenta dwarfa in Dun Garok. Intr-o dimineata, si-a parasit postul nesupravegheat ca sa adune lemne pentru fiert apa, iar patrulele dwarfe i-au dat peste tabara si i-au pradat tot echipamentul, inclusiv lama personala. Cu atat de multi dwarfi de cercetat, Humbert se bazeaza pe agenti ai Horde sa se infiltreze in fortareata si sa-i recupereze arma pierduta."},{t="Comoara piticilor",b="Dupa furt, bunurile lui Humbert au fost duse inapoi, dincolo de baricadele fortificate din Dun Garok. Cum tragatorii cu pusca, alpinistii si preotii pitici isi impart proviziile prin intreaga garnizoana, gasirea hotului anume presupune cercetarea apararii din transeele si fortificatiile cetatii."}},faq={{q="Cui ii apartine aceasta sabie?",a="Lama ii apartine lui Deathguard Humbert, o santinela Forsaken din Tarren Mill, trimisa sa cerceteze Dun Garok.",al={"a cui este sabia aceasta","proprietarul Humbert","cine este Humbert"}},{q="Cum au obtinut piticii sabia lui Humbert?",a="Deathguard Humbert si-a parasit tabara de cercetasi de langa Dun Garok ca sa stranga lemne de foc dimineata. In lipsa lui, o patrula de pitici a jefuit tabara si i-a luat echipamentul.",al={"cum au ajuns piticii sa-l aiba","de ce au piticii o sabie","cum a fost furata sabia"}},{q="De ce e Humbert atat de disperat sa-si recupereze sabia?",a="Humbert are nevoie de arma pentru a mentine paza in Dun Garok, asa cum i-a cerut High Executor Darthalia; cu atatia dwarfi in garnizoana, nu poate spera sa gaseasca singur hotul.",al={"de ce vrea Humbert sabia","ce se intampla daca Humbert pierde sabia","de ce ii pasa lui Humbert"}},{q="Unde se poate gasi sabia?",a="Sabia se afla in mainile fortelor pitice de garnizoana din Dun Garok, situat in sud-estul Hillsbrad Foothills. Poate fi recuperata de la alpinisti, puscasii sau preotii stationati in avanpost.",al={"unde se gaseste sabia","locatia sabiei","cum gasesti sabia lui Humbert"}}},fp="15,196,25.439.0,17.325.0,20.120.0,40.182.0,50.175.0,29.205.0"}
P.entries["item:hyacinth-mushroom"] = {n="Hyacinth Mushroom"}
P.entries["item:hypercapacitor-gizmo"] = {n="Hypercapacitor Gizmo",s="Hypercapacitor Gizmo este o piesa inginereasca excentrica, recuperata de pe fundul canionului din Thousand Needles. Odinioara atarna de gatul unei bestii captive intr-o caravana ruinata, iar rostul sau ramane o enigma chiar si pentru mesterul care pretinde ca este proprietarul ei.",h="Hypercapacitor Gizmo este o piesa inginereasca excentrica, recuperata de pe fundul canionului din Thousand...",kw={"centaur","pantera furioasa","gizmo","hipercapacitor","thousand needles","whitereach post","wizlo bearingshiner"},ang={["faction:Horde"]="Calatorii care dau o mana de ajutor la Whitereach Post contribuie la alungarea centaurilor agresivi si la recuperarea ciudateniilor pierdute din caravanele distruse de pe fundul canionului.",["profession:Engineering"]="Gizmo-ul intruchipeaza ingineria goblina clasica: un dispozitiv complicat, cu un nume periculos, construit cu mult entuziasm inainte ca cineva sa se gandeasca ce trebuia sa faca."},sec={{t="O relicva ciudata a unei caravane",b="Cand jefuitorii centauri au atacat o caravana de goblini care traversa Thousand Needles, au pradat aproape tot ce le-a iesit in cale. Singurul supravietuitor, Wizlo Bearingshiner, a reusit sa se tarasca pana la adapostul de la Whitereach Post, lasandu-si in urma cea mai buna inventie: Hypercapacitor Gizmo. In mod straniu, dispozitivul a ajuns prins in jurul gatului unei pantere feroce si furioase, inchise intr-o cusca de transport. Centaurul jefuitor se temea atat de mult de fiara, incat a lasat cusca complet neatinsa in mijlocul epavei in flacari, pastrand fara sa-si dea seama ciudata masinarie a lui Wizlo."},{t="Mesterit in intuneric",b="Desi Wizlo spune cu mandrie ca dispozitivul este cea mai buna inventie a sa, dupa ce il recupereaza recunoaste ca nu prea stie ce face de fapt. Ca multe inventii gobline, Hypercapacitor Gizmo este un ghem incalcit de ambitii si componente instabile, menit sa-si tina proprietarul ocupat cu reparatii fara sfarsit, in loc sa indeplineasca vreo functie practica si inteleasa."}},faq={{q="Ce este Hypercapacitor Gizmo?",a="Este un dispozitiv de inginerie care ii apartine goblinului Wizlo Bearingshiner. In ciuda numelui sau pompos, nici macar Wizlo nu stie ce functie indeplineste, asa ca intentioneaza sa-si petreaca timpul studiindu-l ca sa-i afle rostul.",al={"ce este dispozitivul","hypercapacitor","ce face dispozitivul"}},{q="Cum a ajuns dispozitivul in jurul gatului unei pantere?",a="Caravana lui Wizlo a fost atacata si jefuita de centauri in nordul Thousand Needles. In haosul care a urmat, dispozitivul a ajuns prins in jurul gatului unei pantere furioase inchise intr-o cusca de transport, impiedicandu-i pe centaurii superstitiosi sa-l fure.",al={"de ce are pantera gizmo","cum a obtinut pantera obiectul"}},{q="Cine vrea inapoi Hypercapacitor Gizmo?",a="Wizlo Bearingshiner, singurul supravietuitor al caravanei jefuite, vrea sa-l recupereze. S-a refugiat la Whitereach Post, o tabara Tauren din nord-vestul regiunii Thousand Needles.",al={"cine are nevoie de gizmo","gizmo de la wizlo"}},{q="De ce nu l-a furat centaurul?",a="Centaurii au jefuit intreaga caravana, dar s-au ingrozit de pantera feroce din cusca. Au lasat fiara si zgarda ei metalica complet neatinse, printre ruine.",al={"de ce nu l-au luat centaurii","centaurii si pantera"}}},fx={["240fe489"]={q="De unde provine Hypercapacitor Gizmo si cine l-a creat?",a="Dispozitivul se afla in posesia goblinului mester Wizlo Bearingshiner, care calatorea cu o caravana prin Thousand Needles inainte ca centaurii sa-i atace. Desi Wizlo sustine ca este pretiosul sau aparat, inventatorul lui ramane necunoscut - pana si Wizlo recunoaste ca nu intelege pe deplin ce face, de fapt, masinaria curioasa.",al={"cine a creat dispozitivul hipercapacitor","originea dispozitivului hipercapacitor","de unde a luat Wizlo hipercapacitorul"}}},fp="20,258,25.548.0,21.349.0,33.224.0,50.250.0,40.173.0,32.179.0"}
