P.entries["item:intrepid-strongbox-key"] = {n="Intrepid Strongbox Key",s="Intrepid Strongbox Key este o cheie de fier ruginita, pazita candva cu inversunare de capitanul Halyndor, comandantul navei Alliance Intrepid, sortita pieirii. Chiar si dupa ce a devenit strigoi, capitanul o strange in mana, tinand incuiat artefactul blestemat care i-a adus pieirea echipajului in largul coastei Wetlands.",h="Intrepid Strongbox Key este o cheie de fier ruginita, pazita candva cu inversunare de capitanul Halyndor...",kw={"Captain Halyndor","echipaj blestemat","Glorin Steelbrow","Intrepid","naufragiu","lada de valori","Third Fleet","Wetlands"},ang={["class:Priest"]="Cheia descuie un artefact cu energie necrotica malefica; pentru a-l purifica si a lasa sufletele echipajului sa-si gaseasca odihna, sunt necesare ritualurile sfinte ale preotului din Menethil, Glorin Steelbrow.",["faction:Alliance"]="Cheia apartinea unui comandant al Third Fleet din Alliance, a carui disparitie tragica in largul Menethil Harbor ramane o rana deschisa pentru supravietuitorii portului."},sec={{t="Secretul unui capitan",b="In timpul naufragiului Third Fleet, in largul tarmurilor furtunoase din Wetlands, nava de razboi Intrepid a fost distrusa, iar echipajul ei s-a transformat in spirite nelinistite si blestemate. Capitanul Halyndor veghea obsesiv asupra unui obiect misterios, pus in lada grea a navei. Chiar si dupa moarte, silueta sa spectrala continua sa rataceasca pe puntea inundata, refuzand sa cedeze cheia ruginita care deschide cala cu cele mai ascunse si intunecate marfuri."},{t="Ruperea legaturii",b="Sa iei cheia de la Captain Halyndor este singura cale de a deschide lada zavorata a navei Intrepid si de a recupera relicva blestemata care tine echipajul legat de chinurile sale. Numai recuperand obiectul cu aceasta cheie il poti duce la preotul dwarven Glorin Steelbrow, in Menethil Harbor, pentru a fi purificat."}},faq={{q="Cine poarta Intrepid Strongbox Key?",a="Cheia este la Captain Halyndor, comandantul fantomatic care patruleaza puntea superioara a epavei nordice de pe coasta de nord-vest a Wetlands.",al={"cine are cheia","prada de cheie Intrepid","cheia lui Halyndor"}},{q="Ce deschide Intrepid Strongbox Key?",a="Descuie cufarul incuiat al navei Intrepid, aflat sub apa, in coca sfaramata a vasului scufundat, sub puntea capitanului.",al={"ce deblocheaza","locatia casetei Intrepid","unde se afla cufarul"}},{q="De ce a fost pastrata lada incuiata?",a="Captain Halyndor a incuiat un obiect intunecat si blestemat in cufar pentru a-l tine ascuns si in siguranta, iar dupa ce flota a fost scufundata, raul persistent a legat echipajul de moartea-vie.",al={"ce era in cufar","de ce era incuiat"}},{q="Cine poate purifica obiectul blestemat din cufar?",a="Glorin Steelbrow, un preot dwarven din Menethil Harbor, detine cunostintele sacre necesare pentru a curata artefactul blestemat dupa ce cufarul este descuiat.",al={"cine il purifica","cufarul lui Glorin Steelbrow"}}},fx={b4277111={q="Ce este Intrepid Strongbox Key?",a="Este o cheie ruginita de la o nava, pastrata de Captain Halyndor la bordul epavei Intrepid. Chiar si dupa moarte, capitanul blestemat pazeste cheia cu inversunare, fiindca este singurul mijloc de a descuia lada intarita a navei, ascunsa in carena sfaramata.",al={"Intrepid Strongbox Key","la ce foloseste cheia","cheie intrepid"}},["90ec2e74"]={q="De ce este necesara Intrepid Strongbox Key?",a="Cheia este necesara pentru a deschide lada de valori a navei Intrepid si a recupera relicva intunecata inchisa in ea. First Mate Fitzsimmons crede ca acest artefact ascuns a provocat blestemul ingrozitor care il tine pe Halyndor si echipajul sau legati de epava, iar deschiderea cufarului este primul pas pentru a-l ridica.",al={"de ce am nevoie de cheie","de ce sa iau cheia","scopul cheii intrepide"}}},fp="22,284,18.424.0,17.321.1,39.150.0,42.138.0,34.168.0,49.160.0"}
P.entries["item:invisibility-liquor"] = {n="Invisibility Liquor",s="Invisibility Liquor ii ofera lui Maybell Maclure o cale de a scapa de privirile familiei si de a se intalni cu Tommy Joe Stonefield. Gospodariile lor sunt prinse intr-o dusmanie veche.",h="Invisibility Liquor ii ofera lui Maybell Maclure o cale de a scapa de privirile familiei si de a se intalni...",kw={"alga cristalina","Elwynn Forest","licoare de invizibilitate","Maybell Maclure","vrajba Stonefield","evadarea","Tommy Joe Stonefield"},ang={["class:Mage"]="Ca mage, stii ca arcanistii din Kirin Tor petrec ani intregi perfectionandu-si maiestria in iluzii si vraji de invizibilitate. Localnicii din Elwynn improvizeaza o imitatie rudimentara, folosind bauturi spirtoase fermentate si varec imbibat cu apa.",["race:Human"]="Ca human, stii ca vrajba rurala dintre clanurile Stonefield si Maclure ajunge la extreme amare."},sec={{t="O potiune pentru indragostitii sortiti unul altuia",b="Tommy Joe Stonefield vrea sa se intalneasca pe ascuns cu Maybell Maclure, desi vrajba familiilor lor tine gospodariile despartite. Rudele lor ii urmaresc cu atentie, iar simplul secret nu ajunge. Invisibility Liquor ii permite celui care o bea sa treaca nevazut prin ogoarele disputate."},{t="Alchimie neortodoxa din Elwynn",b="Crystal Kelp Fronds din apele locuite de murlocs sunt folosite la prepararea bauturii. Dupa ce o bea, Maybell Maclure devine invizibila si se furiseaza in padure pentru o intalnire secreta."}},faq={{q="Ce face Invisibility Liquor?",a="Invisibility Liquor este o bautura alcoolica cu proprietati magice, care il face invizibil pe cel care o bea pentru scurt timp.",al={"efectele bauturii","potiune de invizibilitate","ce efect are"}},{q="Cine foloseste Invisibility Liquor?",a="Maybell Maclure primeste Invisibility Liquor pentru a putea scapa de sub privirile familiei si a se intalni cu Tommy Joe Stonefield, in ciuda vrajbei dintre familiile lor.",al={"cine il bea","bautura lui maybell maclure"}},{q="Cum se prepara bautura?",a="Lichiorul este preparat cu Crystal Kelp Fronds adunate de pe albiile raurilor si de pe malurile lacurilor din Elwynn Forest, unde murlocii ascund plantele.",al={"ingrediente pentru lichior","lichior cu alge de cristal"}},{q="Pot jucatorii sa bea ei insisi Invisibility Liquor?",a="Nu. Invisibility Liquor trebuie livrat lui Maybell Maclure, ca sa poata pleca pe furis de langa familia ei.",al={"pot sa o beau","sa beau bautura de invizibilitate"}}},fx={["19edabb3"]={q="Ce este Invisibility Liquor?",a="Invisibility Liquor este o bautura alchimica puternica, preparata in Elwynn Forest. Desi, aparent, este o bautura alcoolica, are proprietati magice provenite din frunze de varec cristalin, oferindu-i temporar oricui o bea invizibilitate deplina in fata ochilor muritorilor.",al={"ce este lichiorul invizibilitatii","povestea lichiorului invizibilitatii","ce fel de bautura este lichiorul invizibilitatii"}},f0e7bc08={q="De ce ar vrea cineva Invisibility Liquor?",a="Lichiorul este cautat pentru a rezolva o poveste de dragoste interzisa. Maybell Maclure si Tommy Joe Stonefield se afla de parti opuse in conflictul amar dintre familiile lor din Elwynn, iar bautura ii permite lui Maybell sa se strecoare neobservata pe langa rudele vigilente pentru a-si vizita iubitul.",al={"de ce este nevoie de licoarea invizibilitatii","cine vrea licoarea invizibilitatii","de ce vor ei licoarea"}}},fp="19,149,32.260.0,25.172.1,33.103.0,33.143.0,23.135.0,53.103.0"}
P.entries["item:iron-pike"] = {n="Iron Pike",s="Iron Pikes sunt materiale de constructie rezistente, expediate initial de la Stormwind pentru a ajuta la repararea Everstill Bridge din Lakeshire. Transportul a fost atacat si jefuit de gnolii din Redridge, lasand orasul fara provizii esentiale pentru reconstructie.",h="Iron Pikes sunt materiale de constructie rezistente, expediate initial de la Stormwind pentru a ajuta la...",kw={"everstill bridge","foreman oslow","pica de fier","nit de fier","lakeshire","redridge gnolls","redridge mountains"},ang={["faction:Alliance"]="Recuperarea proviziilor de constructie furate de la gnolli salbatici ajuta la asigurarea trecerilor vitale din Lakeshire, mentinand fortificata granita estica a Stormwind impotriva agresiunii Blackrock.",["profession:Blacksmithing"]="Acesti tarusi structurali grei arata presiunea pusa asupra fierarilor locali, ale caror rezerve intregi de fier brut au trebuit redirectionate spre arme de razboi."},sec={{t="Marfa caravanei furata",b="Cand Lakeshire a fost atacata recent de orcii Blackrock, rezervele de metal ale orasului au fost topite pentru a fauri armuri, lame si munitie de aparare. Ca raspuns la lipsuri, constructorii locali au solicitat un transport nou de fier din Stormwind City. Inainte ca materialele sa ajunga in oras, o haita de gnolli din Redridge a capturat caravana de transport de pe drum. Gnollii au dus la nord, in dealuri, lazi cu sulite si nituri de fier, oprind reparatiile esentiale la Everstill Bridge."},{t="Reconstructia podului",b="Foreman Oslow, insarcinat cu supravegherea reconstructiei podului Everstill Bridge, se bazeaza pe aventurieri sa patrunda pe teritoriul gnollilor si sa recupereze feroneria furata. Fara acesti tarusi grei din fier care sa intareasca structura din piatra si lemn, Lakeshire ramane partial izolata de drumul dinspre nord si vulnerabila in fata unor noi incursiuni."}},faq={{q="De ce poarta gnollii sulite de constructie?",a="Gnollii au atacat prin surprindere o caravana de provizii care calatorea din Stormwind spre Lakeshire. S-au imprastiat pe dealurile din Redridge, cu lazi de materiale de constructii furate, printre care tarusi de fier si nituri.",al={"de ce au gnollii sulite de fier","de unde au luat gnollii sulite de fier"}},{q="Cine are nevoie de aceste sulite de fier in Lakeshire?",a="Foreman Oslow are nevoie de ele pentru a reconstrui Everstill Bridge, care leaga Lakeshire de celalalt mal al lacului Lake Everstill. Orasul nu mai are fier de rezerva, dupa ce si-a topit rezervele locale pentru a fauri arme si armuri in timpul recentelor atacuri ale orcilor.",al={"cine vrea sulitele de fier","sulitele de fier ale lui Foreman Oslow"}},{q="Unde pot fi recuperate aceste sulite de fier?",a="Sunt detinute de gnolii din Redridge, campati pe dealurile si culmile de la nord de Lakeshire.",al={"unde gasesti sulitele de fier","locatia sulitei de fier"}},{q="De ce nu-si putea Lakeshire fauri singur sulitele de fier?",a="Lakeshire si-a epuizat rezervele locale de fier in lupta impotriva orcilor Blackrock, topind fiecare bucata de metal pentru sabii, gloante si echipament de protectie. Au fost nevoiti sa ceara fier structural nou de la Stormwind.",al={"de ce a comandat Lakeshire fier","lipsa fierului in Lakeshire"}}},fx={c6b2b586={q="Ce este un Iron Pike?",a="Un Iron Pike este un tarus greu de fier, folosit la consolidarea zidariilor si lucrarilor din piatra. Foreman Oslow si echipa sa au nevoie de acesti tarusi rezistenti pentru a repara si stabiliza Everstill Bridge, avariat, din Lakeshire.",al={"ce este o lance de fier","ce sunt lancile de fier","lancea de fier din Redridge"}}},fp="9,247,20.497.0,19.340.0,47.192.0,40.226.0,40.89.0,55.214.0"}
P.entries["item:iron-pommel"] = {n="Iron Pommel",s="Iron Pommel este ultimul fragment lipsa din toiagul lui Dartol, creat de vrajitorul demult raposat Dartol si cautat de Night Elves din Astranaar pentru a incetini atacurile furbolgilor asupra poporului lor. Incredintat druidilor din Dor'Danil Barrow Den spre pastrare, s-a pierdut cand sanctuarul lor a fost masacrat si cotropit de geluri.",h="Iron Pommel este ultimul fragment lipsa din toiagul lui Dartol, creat de vrajitorul demult raposat Dartol si...",kw={"Ashenvale","toiagul lui Dartol","Dor'Danil","maner de fier","lada lui Oso","Raene's Cleansing","Shael'dryn"},ang={["class:Druid"]="Butonul manerului este un omagiu sumbru adus druidilor cazuti din Dor'Danil, a caror misiune sacra s-a incheiat cu un masacru la marginea padurii.",["faction:Alliance"]="Recuperarea manerului incheie o etapa esentiala in obtinerea toiagului lui Dartol, un instrument vital pentru apararea Ashenvale de coruptia care se raspandeste."},sec={{t="Povara cercului ucis",b="Toiagul lui Dartol a fost rupt si imprastiat prin Ashenvale pentru a-i proteja puterea mistica. Iron Pommel a fost incredintat druizilor night elf care locuiau langa drumul ce serpuieste spre sud, catre Barrens. O tragedie a lovit enclava izolata de la Dor'Danil Barrow Den, cand cercul a fost masacrat, iar adapostul lor tihnit s-a cufundat in liniste si ruina. Capatul toiagului a disparut in urma masacrului, inghitit de masele grotesti si clocotitoare de mazga ce se tarasc acum prin poiana profanata."},{t="Recuperat din mlastina",b="Dupa moartea druidilor, gasirea manerului presupune cercetarea scobiturii corupte de la sud de Splintertree Post. Relicva a ramas inchisa intr-un cufar trainic. Aventurierii care isi croiesc drum printre namolurile corupte descopera cufarul intact, inghitit de masa acida a unei mase gelatinoase, si obtin in sfarsit ultima piesa necesara pentru refacerea toiagului."}},faq={{q="La ce se foloseste Iron Pommel?",a="Iron Pommel este ultima componenta necesara pentru a reasambla toiagul lui Dartol. Daca i-l duci lui Shael'dryn la fantana lunii, ea va putea repara artefactul stravechi, astfel incat acesta sa incetineasca atacurile furbolgilor asupra elfilor noptii din Ashenvale.",al={"scopul manerului de fier","de ce am nevoie de un maner de fier","la ce foloseste manerul de fier"}},{q="Cine a avut initial manerul?",a="Fusese incredintata druidilor elfi ai noptii care locuiau langa drumul spre Barrens. Din nefericire, cercul a fost masacrat inainte ca toiagul sa poata fi reunit cu restul, iar adapostul lor a ramas in ruine.",al={"cine pazea butonul","cine avea butonul de fier","druizii din dor'danil"}},{q="Unde se gaseste butonul manerului?",a="Manerul este incuiat intr-un cufar purtat in interiorul unuia dintre malurile corupte care ratacesc prin adancitura pangarita de la est de drumul principal, la sud de Splintertree Post si la nord de granita Barrens.",al={"locatia manerului de fier","unde se afla manerul de fier","de unde iau manerul de fier"}},{q="Cui trebuie sa-i duc butonul?",a="Butonul trebuie dus la Shael'dryn, o driada care ingrijeste Moonwell la est de Iris Lake si care cunoaste ritualurile necesare pentru a reface Dartol's Rod.",al={"unde predau manerul de fier","unde duc manerul de fier","cine vrea manerul"}}},fx={["9716c2ef"]={q="Ce este Iron Pommel?",a="Iron Pommel este ultima componenta lipsa necesara pentru a reconstitui toiagul lui Dartol, creat de vrajitorul Dartol, mort de multa vreme. Inainte de caderea lor tragica, druizilor care locuiau in Dor'Danil Barrow Den li s-a incredintat paza acestei piese grele de metal. Pierdut in mijlocul coruptiei si violentei care le-au cuprins sanctuarul, capatul de maner a ajuns in cele din urma incuiat intr-un cufar vechi din salbaticie, asteptand pe cineva in stare sa-l recupereze.",al={"ce este maciulia de fier","povestea maciuliei de fier","la ce foloseste maciulia toiagului lui Dartol"}}},fp="11,335,23.480.0,23.343.1,33.241.0,30.195.0,26.190.0,29.153.0"}
P.entries["item:iron-rivet"] = {n="Iron Rivet",s="Iron Rivets sunt elemente de fixare solide, fabricate in Stormwind pentru a ajuta la reconstruirea podului Everstill Bridge, ruinat, din Lakeshire. Dupa ce o caravana cu provizii a fost atacata si jefuita de gnolls din Redridge, aceste componente grele de metal au ajuns imprastiate prin taberele gnoll din dealurile nordice.",h="Iron Rivets sunt elemente de fixare solide, fabricate in Stormwind pentru a ajuta la reconstruirea podului...",kw={"everstill bridge","foreman oslow","pica de fier","nit de fier","lakeshire","redridge gnolls","redridge mountains"},ang={["faction:Alliance"]="Recuperarea acestor provizii furate ajuta direct infrastructura locala din Lakeshire si tine in frau amenintarea tot mai indrazneata a gnollilor care primejduiesc orasul.",["profession:Blacksmithing"]="Aceste elemente de fixare grele exemplifica fieraria obisnuita din Stormwind, fiind forjate anume pentru a ancora lucrari civile majore, precum podurile de piatra si lemn."},sec={{t="Marfa caravanei furata",b="Cand Lakeshire s-a confruntat cu atacuri repetate din partea Orc-ilor din Blackrock, consiliul orasului a fost nevoit sa topeasca rezervele de fier structural pentru a fauri arme, armuri si munitii de urgenta. Dupa ce criza imediata s-a potolit, Foreman Oslow a cerut materiale noi de constructie din Stormwind pentru a repara Everstill Bridge, avariat. Totusi, caravana care transporta incarcatura a fost atacata de gnoll-ii locali din Redridge inainte sa ajunga in oras. Animalele de povara si carutele au fost tarate in dealurile de la nord de Lake Everstill, iar materiale esentiale de constructie, precum nituri de fier si pichete, s-au imprastiat printre haitele de gnoll."},{t="Repararea podului",b="Fara aceste nituri grele de fier, reparatiile structurale de la Everstill Bridge nu pot continua in siguranta. Structura de piatra si lemn care traverseaza lacul are nevoie de elemente de fixare metalice ranforsate, capabile sa suporte greutatea carutelor si a calatorilor. Recuperarea niturilor direct din taberele gnollilor este esentiala pentru refacerea legaturii vitale dintre Lakeshire si vaile vestice si pentru apararea orasului de noi incursiuni."}},faq={{q="La ce folosesc Iron Rivets?",a="Sunt elemente de fixare structurale rezistente, de care Foreman Oslow are nevoie pentru a repara podul Everstill Bridge avariat din Lakeshire, care si-a pierdut fierul original in timpul luptelor cu orcii Blackrock.",al={"scopul nitului de fier","de ce sunt necesari nituri de fier","la ce folosesc niturile de fier"}},{q="De ce au gnolii aceste nituri?",a="O caravana cu provizii trimisa din Stormwind a fost jefuita de gnolii Redridge de pe drum. Scormonitorii au furat materialele pentru constructii, ducand niturile si lanciile de fier in taberele lor de la nord de Lakeshire.",al={"de ce au gnolii nituri","cum au obtinut gnolii nituri de fier","cine a furat niturile"}},{q="De ce ducea Lakeshire lipsa de fier de la bun inceput?",a="In timpul unei invazii recente a orcilor, aparatorii din Lakeshire au fost nevoiti sa topeasca toate rezervele de fier si sa le transforme in sabii, gloante si armuri pentru a supravietui asediului.",al={"lipsa fierului din Lakeshire","de ce nu exista fier in Lakeshire"}},{q="Cine cauta aceste nituri?",a="Foreman Oslow, care supravegheaza lucrarile de restaurare a Everstill Bridge, pe tarmurile din Lakeshire.",al={"cine vrea nituri de fier","cine ia niturile de fier"}}},fx={["0d91405a"]={q="Ce este un Iron Rivet?",a="Iron Rivet este un nit metalic rezistent, faurit pentru lucrari de constructii grele din regat. Stormwind a trimis o incarcatura de astfel de nituri spre Lakeshire, pentru a ajuta la reconstruirea infrastructurii distruse a orasului, mai ales a vitalului Everstill Bridge.",al={"ce este un nit de fier","ce sunt niturile de fier","descrierea nitului de fier"}},a8a8e120={q="De unde provin aceste Iron Rivets si cine le-a facut?",a="Aceste nituri au fost trimise din Stormwind ca parte a unui convoi de ajutor, care transporta materii prime si materiale de constructie catre Redridge. Inainte de a ajunge la Lakeshire, convoiul a fost atacat si jefuit de gnollii din Redridge, imprastiind rezervele de fier prin taberele lor de pe deal.",al={"de unde provin nituri de fier","cine a facut niturile de fier","originea nitului de fier"}}},fp="10,290,20.609.0,18.418.0,30.186.0,36.215.0,46.158.0,32.112.0"}
P.entries["item:iron-shaft"] = {n="Iron Shaft",s="Iron Shaft este o componenta metalica a toiagului lui Dartol, o relicva pe care Teronis, prietenul lui Raene Wolfrunner, a cautat-o in speranta de a incetini atacurile furbolgilor asupra Ashenvale. Recuperata dintr-un cufar incuiat de langa granita cu Felwood, este o piesa esentiala pentru refacerea relicvei folosite de aparatorii din Ashenvale.",h="Iron Shaft este o componenta metalica a toiagului lui Dartol, o relicva pe care Teronis, prietenul lui Raene...",kw={"Ashenvale","stravechi nebun","toiagul lui Dartol","Felwood","tija de fier","Raene's Cleansing","Shael'dryn","stravechi ofilit","cheie de lemn"},ang={["class:Druid"]="Reasamblarea toiagului lui Dartol are legatura stransa cu grija druizilor fata de natura, folosind unelte uitate pentru a tamadui tinuturile ranite.",["race:NightElf"]="Recuperarea Iron Shaft este o datorie sumbra, intrucat presupune sa-i dobori pe treantii padurii, candva iubiti, care au cazut prada napastei demonice ce se raspandeste din Felwood."},sec={{t="O bucata din toiagul lui Dartol",b="Toiagul lui Dartol a fost creat de Dartol, iar bucatile sale au fost imprastiate prin Ashenvale; una dintre ele le-a fost incredintata chiar druidilor din Dor'Danil, spre pastrare. Iron Shaft este miezul metalic rezistent al instrumentului, incuiat intr-un cufar, intr-o poiana retrasa de langa granita de nord a Ashenvale, nu departe de taramul pangarit Felwood."},{t="Molima padurii",b="Pentru a pune mana pe Iron Shaft, trebuie recuperata cheia de la treantii locali, care odinioara aveau grija de aceste paduri. Odata cu raspandirea spre sud a coruperii demonice din Felwood, strajeri stravechi precum Crazed si Withered Ancients si-au pierdut mintile. Dryada Shael'dryn le cere calatorilor sa obtina tija, pentru ca toiagul sa poata fi refacut si misiunea lui Teronis, cel cazut, sa fie dusa la bun sfarsit."}},faq={{q="La ce se foloseste Iron Shaft?",a="Iron Shaft este o bucata din Rod of Dartol, o relicva sparta. Este adunata pentru ca dryada Shael'dryn sa poata ajuta la reasamblarea toiagului si la incheierea misiunii lui Teronis, care l-a cautat pentru a opri atacurile furbolgilor asupra Ashenvale.",al={"scopul arborelui de fier","ce este acest arbore","de ce am nevoie de arborele de fier"}},{q="Unde se gaseste Iron Shaft?",a="Este incuiat intr-un cufar aflat intr-o poiana linistita, la vest de drumul spre Felwood, in partea de nord a Ashenvale.",al={"locatia tijei de fier","gaseste tija de fier","unde este cufarul"}},{q="Cum deschizi cufarul care contine arborele?",a="Cufarul necesita o Wooden Key. Aceasta cheie este purtata de copacii stravechi corupti - Crazed si Withered Ancients - care ratacesc prin padurile de la nord-est de Raynewood Retreat.",al={"cum deschid cufarul","cheia cufarului","cheia tevii de fier"}},{q="Cine cauta Iron Shaft?",a="Shael'dryn, o dryada aflata la o fantana lunara din centrul Ashenvale, ii indruma pe aventurieri sa adune fragmentele Toiagului lui Dartol, ca parte a efortului de purificare a padurii.",al={"cine vrea o tija de fier","cel care da misiunea pentru tija de fier"}}},fx={ad78a81b={q="Ce este Iron Shaft?",a="Iron Shaft este un segment-cheie al toiagului lui Dartol, o relicva creata de Dartol. Partile toiagului au fost imprastiate prin Ashenvale, iar aceasta a ajuns incuiata intr-un cufar ascuns, langa granita cu Felwood; cheia este purtata de treantii corupti din apropiere.",al={"ce este o tija de fier","obiectul tija de fier","tija de fier din toiagul lui Dartol"}},["45340e91"]={q="De unde provine Iron Shaft si cine l-a facut?",a="A fost faurita ca parte a unei vergi magice create de Dartol. Bucatile vergi au fost imprastiate mai tarziu, iar aceasta tija a fost pusa la adapost intr-un cufar uzat, ascuns intr-o poiana de langa Felwood si pazit indirect de treantii corupti care ii detin cheia.",al={"cine a facut coada de fier","originea cozii de fier","coada de fier a lui dartol"}},["3705c59d"]={q="De ce este dorit Iron Shaft?",a="Raene Wolfrunner si Shael'dryn incearca sa reasambleze Toiagul lui Dartol, despre care Teronis credea ca ar putea incetini atacurile furbolgilor asupra elfilor noptii din Ashenvale. Reconstruirea relicvei presupune strangerea componentelor lipsa, iar aceasta tija rezistenta din fier formeaza manerul central si miezul necesar pentru a tine laolalta nestemata magica si maciulia toiagului.",al={"de ce vor arborele de fier","de ce adun arborele de fier","motivul misiunii cu arborele de fier"}}},fp="10,303,23.355.0,19.392.1,32.214.0,30.128.0,47.166.0,34.167.0"}
