P.entries["item:letter-to-jin-zil"] = {n="Letter to Jin'Zil",s="Letter to Jin'Zil este o scrisoare redactata de orcul Darsok Swiftdagger la Crossroads. Incredintata unui aventurier dupa infrangerea lui Serena Bloodfeather, aceasta ii da de stire lui Jin'Zil, witch doctor Darkspear din Stonetalon Mountains, ca nordul tinutului Barrens a fost curatat de amenintarea Bloodfeather.",h="Letter to Jin'Zil este o scrisoare redactata de orcul Darsok Swiftdagger la Crossroads.",kw={"darsok swiftdagger","harpii","jin'zil","scrisoare pentru jin'zil","malaka'jin","rokhan","serena bloodfeather","stonetalon"},ang={["faction:Horde"]="Scrisoarea serveste drept punte pentru aventurierii Horde care trec de la mentinerea ordinii in Barrens la abordarea conflictelor mai profunde ce mocnesc in Stonetalon Mountains.",["race:Troll"]="Ducerea scrisorii ii conduce direct pe calatorii Darkspear la Witch Doctor Jin'Zil, un batran practicant care continua traditia voodoo in afara Echo Isles."},sec={{t="Un mesager catre Stonetalon",b="Dupa nimicirea harpiilor din Dry Hills si uciderea Serenei Bloodfeather, Darsok Swiftdagger scrie acest mesaj unui vechi camarad. Dandu-si seama ca harpiile din Barrens isi aveau initial cuiburile in piscurile din Stonetalon Mountains, Darsok foloseste scrisoarea pentru a-i face cunostinta unui razboinic promitator cu tinuturile de la granita si pentru a-l anunta pe vrajitorul Jin'Zil ca matroana harpiilor a fost doborata."},{t="Amintiri vechi in Malaka'jin",b="La sosirea in pestera din Malaka'jin, Jin'Zil primeste vestea cu o satisfactie nostalgica. Moartea lui Serena ii aminteste batranului vraci de intemeierea Durotarului dupa Third War, cand prietenul sau Rokhan s-a alaturat vanatorului de fiare pe jumatate ogre Rexxar pentru a o ucide pe sora mai mare a Serenei, Bloodfeather. Acum ca si Serena a fost ucisa, Jin'Zil socoteste razbunarea neamului Bloodfeather pe deplin curmata."}},faq={{q="Cine a scris Letter to Jin'Zil?",a="Scrisoarea este scrisa de Darsok Swiftdagger, un orc stationat la Crossroads in Barrens, care coordoneaza apararea impotriva covoarelor de harpii pradalnice.",al={"cine a scris asta","expeditorul scrisorii","scrisoarea lui Darsok"}},{q="Unde se afla Jin'Zil?",a="Witch Doctor Jin'Zil locuieste intr-o pestera din Malaka'jin, un avanpost al trollilor Darkspear ascuns printre crestele sud-estice ale Stonetalon Mountains.",al={"unde este Jin'Zil","locatia lui Jin'Zil","gaseste-l pe Jin'Zil"}},{q="Ce veste contine scrisoarea?",a="Mesajul il informeaza pe Jin'Zil ca Serena Bloodfeather, conducatoarea harpiilor care coboara in Barrens-ul de nord, a fost ucisa, asigurand perimetrul de la nord de Crossroads.",al={"ce scrie in scrisoare","mesajul scrisorii"}},{q="De ce ii pasa lui Jin'Zil de Bloodfeather?",a="Jin'Zil isi aminteste de intemeierea Durotar dupa Third War, cand tovarasul sau Rokhan si razboinicul semi-ogru Rexxar au ucis-o pe sora mai mare a Serenei. De atunci, Serena a cautat razbunare impotriva Horde, asa ca infrangerea ei a fost o incheiere binevenita.",al={"de ce harpiile Jinzil","istoria Bloodfeather","Rokhan si Bloodfeather"}}},fx={f9426e82={q="De ce vrea Jin'Zil sa i se livreze Letter to Jin'Zil?",a="Scrisoarea aduce vesti asteptate de mult de la vechiul sau prieten Darsok Swiftdagger din Barrens. Jin'Zil nu mai primise vesti de la Darsok de multi ani, iar mesajul confirma moartea Serenei Bloodfeather, punand capat amenintarii harpiilor matriarhe care tulburau atat Barrens, cat si Stonetalon.",al={"de ce sa duc scrisoarea la Jinzil","cine vrea scrisoarea pentru Jinzil","de ce il intereseaza pe Jinzil scrisoarea"}}},fp="17,325,25.425.0,26.415.1,32.154.0,25.147.0,41.181.0,46.245.1"}
P.entries["item:letter-to-jorgen"] = {n="Letter to Jorgen",s="O scrisoare sigilata ii cere lui Jorgen din Stormwind City sa ajute la gasirea unui diplomat disparut.",h="O scrisoare sigilata ii cere lui Jorgen din Stormwind City sa ajute la gasirea unui diplomat disparut.",kw={"jaina proudmoore","jorgen","letter to jorgen","diplomat disparut","stormwind","theramore","valley of heroes"},ang={["class:Rogue"]="Ca Rogue, stii ca comunicarile discrete si informatorii de strada reticenti pot fi necesari cand descoperi probleme in capitala.",["faction:Alliance"]="Scrisoarea priveste fragila stabilitate a Alliance si solicita un raspuns discret la un incident care ameninta legaturile dintre Stormwind si Theramore."},sec={{t="O convocare impartiala",b="Un diplomat aflat in drum spre Theramore nu a ajuns la intrevederea cu Lady Jaina Proudmoore, iar anchetatorii regali s-au grabit sa tina cazul departe de ochii lumii. In timp ce agentii oficiali au cercetat capitala, alte canale au intrat in miscare. Scrisoarea ocoleste birocratia militara si il cauta pe Jorgen, un veteran ursuz care pescuieste sub statuile uriase din Valley of Heroes. Ea face apel la vechi obligatii si il atrage intr-o ancheta secreta, pe fondul zvonurilor despre o conspiratie Defias."}},faq={{q="Care este scopul acestei scrisori?",a="Scrisoarea isi prezinta purtatorul si ii cere lui Jorgen sa-si respecte o veche datorie. Il trimite pe purtator la Valley of Heroes, pentru ca Jorgen sa poata ajuta la anchetarea disparitiei unui diplomat fara a atrage atentia publicului.",al={"la ce foloseste Letter to Jorgen","de ce Letter to Jorgen","scopul scrisorii"}},{q="Cine este Jorgen?",a="Jorgen este un contact retras, aflat chiar inauntrul portilor din Stormwind, care isi petrece timpul pescuind in Valley of Heroes. Nu-i plac intreruperile, dar o datorie veche il obliga sa ajute atunci cand i se arata scrisoarea.",al={"cine este Jorgen","NPC-ul Jorgen","Jorgen din Stormwind"}},{q="La ce disparitie se refera scrisoarea?",a="Un diplomat de seama a parasit Stormwind cu vaporul spre Theramore pentru a se intalni cu Lady Jaina Proudmoore, apoi a disparut pe drum. Suspiciunile cad asupra Defias Brotherhood, desi intreaga conspiratie este inca tinuta sub stricta tacere.",al={"ce diplomat lipseste","cine a disparut","diplomat disparut"}},{q="Unde este livrata scrisoarea?",a="Scrisoarea este dusa la Valley of Heroes, intrarea grandioasa in Stormwind City, strajuita de monumente dedicate eroilor din Second War. Jorgen pescuieste langa apa, aproape de portile din fata.",al={"unde duc scrisoarea","locatia lui Jorgen","unde este Jorgen"}}},fx={["0eeb183b"]={q="Ce este Letter to Jorgen?",a="Aceasta scrisoare este un mesaj confidential trimis cu privire la disparitia misterioasa a unui diplomat din Stormwind, aflat in drum spre Theramore. Deoarece agentii regali oficiali scotocesc deja orasul la vedere, aceasta nota sigilata apeleaza la contacte private si discrete din afara canalelor obisnuite ale coroanei, pentru a cerceta posibila implicare a Defias Brotherhood.",al={"ce este Letter to Jorgen","obiectul Letter to Jorgen","despre Letter to Jorgen"}},["5d64bfbf"]={q="De unde provine Letter to Jorgen si cine l-a scris?",a="Scrisoarea a fost redactata de Bishop DeLavey in Stormwind, care dorea o ancheta independenta asupra diplomatului disparut. Avand mai multa incredere in aliatii personali decat in anchetatorii regali care atrag atentia, el a scris mesajul special pentru a-l chema in ajutor pe vechiul sau prieten Jorgen, care duce acum o viata discreta langa apele din Valley of Heroes.",al={"cine a scris Letter to Jorgen","cine a trimis Letter to Jorgen","originea lui Letter to Jorgen"}},["9fd54092"]={q="De ce este cautata Letter to Jorgen?",a="Jorgen are nevoie de scrisoare fiindca aceasta descrie o obligatie secreta pe care nu o poate ignora. Desi nu vrea sa fie smuls din pescuitul sau linistit, continutul misivei il convinge sa ajute la dezvaluirea complotului Defias inainte ca panica sa izbucneasca in capitala.",al={"de ce sa livrez letter to jorgen","de ce are nevoie jorgen de scrisoare","scopul predarii letter to jorgen"}}},fp="16,82,23.457.0,35.208.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="Lewis' Note",s="La Sentinel Hill, Quartermaster Lewis trimite o cerere urgenta de provizii unui armurier particular din Stormwind. Un curier o duce cu un grifon si cere echipament de protectie pentru garnizoana din Westfall.",h="La Sentinel Hill, Quartermaster Lewis trimite o cerere urgenta de provizii unui armurier particular din...",kw={"grifon","lewis' note","limited immunity","old town","osric strang","quartermaster lewis","sentinel hill","thor"},ang={["race:Human"]="Livrarea rechizitiilor ii invata pe tinerii aventurieri Human cum sa foloseasca reteaua de gryphons a regatului si arata cat de putin fac conducatorii din Stormwind pentru a-i echipa pe aparatorii din Westfall."},sec={{t="Un apel pentru otel",b="People's Militia din Sentinel Hill primeste putin sprijin din partea House of Nobles din Stormwind. Ciocnirile cu Defias Brotherhood ii epuizeaza fara incetare proviziile deja modeste de echipament. Pentru a-i tine pe aparatori echipati, Quartermaster Lewis apeleaza la afaceri private, in locul proviziilor coroanei. Cererea sa ocoleste complet canalele militare oficiale. Un curier al Alliance trebuie sa zboare cu grifonul pana in Old Town si sa-i prezinte ordinul lui Osric Strang, proprietarul Limited Immunity."}},faq={{q="Ce este Lewis' Note?",a="Lewis' Note este ordinul scris al lui Quartermaster Lewis, prin care ii cere lui Osric Strang, un armurier din Stormwind, sa trimita echipament de protectie garnizoanei din Westfall, aflata la ananghie.",al={"ce este acest obiect","scopul biletului lui Lewis","la ce foloseste biletul"}},{q="Cine a scris acest bilet?",a="Quartermaster Lewis a scris nota. El administreaza proviziile, rezervele si armamentul People's Militia de la Sentinel Hill.",al={"cine este lewis","quartermaster lewis"}},{q="Cine primeste biletul?",a="Biletul ajunge mai intai la Thor, stapanul grifonilor de la Sentinel Hill. De acolo, este livrat direct lui Osric Strang, in interiorul magazinului sau de armuri, Limited Immunity, din Old Town-ul Stormwind.",al={"unde trebuie dusa nota","cine primeste nota lui Lewis","nota pentru Osric Strang"}},{q="De ce nu-si procura garnizoana armura direct de la regat?",a="Guvernul din Stormwind a neglijat in mare masura Westfall, lasandu-i pe aparatorii sai fara finantare militara directa sau armuri furnizate de coroana. Lewis se bazeaza pe legaturi comerciale precum Osric Strang pentru a mentine militia echipata.",al={"de ce sa cumperi de la Osric","de ce nu ajuta Stormwind","ajutorul Stormwind pentru Westfall"}}},fp="11,194,16.462.0,20.162.0,20.125.0,22.184.0,57.215.0"}
