P.entries["item:logging-rope"] = {n="Logging Rope",s="Logging Rope este o franghie groasa, esentiala pentru exploatarile forestiere in desfasurare ale Warsong clan din Ashenvale. Transporturile acestei funii trainice au fost atacate din ambuscada si furate de triburile locale de furbolg, care se opun cu violenta extinderii Horde in padurea stravechi.",h="Logging Rope este o franghie groasa, esentiala pentru exploatarile forestiere in desfasurare ale Warsong clan...",kw={"Ashenvale","Foulweald","Locke Okarr","franghie de exploatare forestiera","Splintertree Post","Thistlefur","tabara de taietori de lemne Warsong","Warsong Supplies"},ang={["faction:Horde"]="Recuperarea liniei de exploatare forestiera este vitala pentru a mentine masinaria de razboi a Warsong clan aprovizionata cu lemn, in ciuda ambuscadelor constante.",["race:Orc"]="Asezarile orcesti din Kalimdor depind in intregime de lemnul din Ashenvale, astfel ca fiecare lada de unelte forestiere deturnata este o insulta care cere razbunare."},sec={{t="Linii furate",b="Intretinerea utilajelor construite de goblini si a gaterelor din Warsong Lumber Camp necesita cantitati uriase de franghie rezistenta pentru exploatarea lemnului. In loc sa ajunga la taietorii de lemne din tabara lor, transporturile esentiale au fost interceptate de triburile de furbolgi Foulweald si Thistlefur. Innebuniti de coruptie si gata sa-si apere cu inversunare padurile stramosesti, acesti furbolgi tin franghiile furate in taberele lor din nordul si centrul Ashenvale."},{t="Aprovizionarea efortului de razboi",b="Locke Okarr din Splintertree Post trebuie sa recupereze lantul logistic ratacit inainte ca tabara de taiat lemne Warsong sa-si inceteze activitatea. Recuperarea franghiei grele direct din vizuinile matroanelor si razboinicilor furbolgi ii permite Horde sa asigure lemn de taiat, busteni legati si echipamente pentru ferastraie, in ciuda rezistentei constante de gherila din partea locuitorilor bastinasi ai padurii."}},faq={{q="La ce foloseste Logging Rope?",a="Este o franghie groasa, de calitate industriala, de care Warsong Lumber Camp are nevoie pentru a lega lemnul taiat, a tari bustenii peste teren accidentat si a fixa utilaje grele in Ashenvale.",al={"utilizarea franghiei la exploatarea lemnului","de ce are nevoie Warsong de franghie","franghia pentru taierea lemnului a lui Warsong"}},{q="Cine a furat funia de taiat lemne?",a="Transporturile au fost atacate de Foulweald si Thistlefur, furbolgii bastinasi, care duc liniile furate in vizuinile satelor si taberele lor din Ashenvale.",al={"cine a luat franghia","hot de franghii","care furbolgi au franghie"}},{q="Cine vrea aceasta franghie inapoi?",a="Locke Okarr, aflat la Splintertree Post, cere franghia impreuna cu alte provizii ratacite, pentru ca operatiunile de la Warsong Lumber Camp sa nu se impotmoleasca.",al={"cine are nevoie de funie pentru taiat lemne","misiunea celui care da funia pentru taiat lemne"}},{q="De ce fura furbolgii proviziile pentru taierea lemnelor?",a="Furbolgii se opun cu violenta defrisarilor sistematice ale Horde din Ashenvale. Interceptarea convoaielor de aprovizionare perturba activitatea gaterelor si razbuna patrunderea pe teritoriile lor.",al={"motivul furbolgilor","de ce ataca furbolgii transporturile"}}},fx={["26f07746"]={q="Ce este Logging Rope?",a="Logging Rope este o franghie rezistenta, esentiala pentru exploatarile forestiere intinse ale Warsong clan din Ashenvale. Folosita pentru a fixa, a trage si a lega trunchiurile uriase taiate, ea este un element indispensabil al recoltei zilnice din tabara de taietori.",al={"ce este franghia de exploatare forestiera","informatii despre franghia forestiera","franghia forestiera warsong"}}},fp="12,249,12.446.0,24.366.0,30.170.0,27.161.0,25.159.0,43.174.0"}
