P.entries["item:lonebrow-s-journal"] = {n="Lonebrow's Journal",s="Lonebrow's Journal este un jurnal ponosit, gasit strans in mainile ramasitelor scheletice ale exploratorului pitic Henrig Lonebrow, la baza lui Great Lift. Paginile sale descriu ultima calatorie sinistra a lui Lonebrow prin Barrens si semnaleaza pericolele care pandesc in Razorfen Kraul.",h="Lonebrow's Journal este un jurnal ponosit, gasit strans in mainile ramasitelor scheletice ale exploratorului...",kw={"crone of the kraul","falfindel waywarder","marele lift","henrig lonebrow","razorfen kraul","thalanaar","thousand needles"},ang={["faction:Alliance"]="Scrierile finale ale lui Henrig Lonebrow creeaza o legatura esentiala intre cercetasii Alliance si druizii care pazesc granita cu Feralas, mobilizand ajutor impotriva amenintarii quilboar.",["race:Dwarf"]="Descoperirea unei rude cazute in tinuturi atat de indepartate si ostile este o amintire sobra a primejdiilor cu care se confrunta exploratorii dwarves in timp ce cerceteaza regiuni mult dincolo de Khaz Modan."},sec={{t="O ultima dorinta la Great Lift",b="Henrig Lonebrow si-a gasit un sfarsit nefericit langa baza Great Lift, care leaga Barrens de Thousand Needles. Zacand abandonat pe o margine stancoasa, ramasitele lui scheletice inca strang acest jurnal uzat de vreme. Jurnalul marturiseste ultimele lui calatorii si ii indeamna pe cel care il descopera sa duca vestea druidului night elf Falfindel Waywarder din Thalanaar, avanpostul de frontiera care duce spre Feralas. Notitele lui Lonebrow arunca o lumina esentiala asupra pericolului quilboar care se naste in sudul Barrens."},{t="Legaturi cu Razorfen",b="Cand ii sunt inmanate lui Falfindel Waywarder, insemnarile lui Lonebrow confirma ingrijorarea tot mai mare a Alliance fata de quilboarii din Razorfen Kraul. Continutul jurnalului duce direct la chemarea eroilor, care trebuie sa loveasca in inima vizuinii spinoase si sa o infranga pe Charlga Razorflank, Crone of the Kraul, cea care orchestreaza amenintarea quilboar."}},faq={{q="Cine a fost Henrig Lonebrow?",a="Henrig Lonebrow era un calator pitic care si-a gasit sfarsitul la poalele Great Lift, in Thousand Needles. A murit tinandu-si jurnalul strans in mana, dorind ca insemnarile din el sa ajunga la elfii noptii stationati in Thalanaar.",al={"Henrig Lonebrow","cine este Lonebrow","piticul mort din lift"}},{q="Unde poate fi gasit jurnalul?",a="Jurnalul se afla langa scheletul lui Henrig Lonebrow, putin mai departe de rampa de la baza Great Lift, pe o lespede joasa si stancoasa din nordul Thousand Needles.",al={"unde este jurnalul lui Lonebrow","gaseste jurnalul lui Lonebrow","scheletul de la Great Lift"}},{q="Cine ar trebui sa primeasca Lonebrow's Journal?",a="Jurnalul trebuie dus spre vest, de-a lungul Thousand Needles, la Falfindel Waywarder, un druid night elf stationat in Thalanaar, la granita cu Feralas.",al={"cui ii duc jurnalul","Falfindel Waywarder","unde predau jurnalul"}},{q="La ce duce jurnalul?",a="Citirea jurnalului si raportarea catre Falfindel Waywarder dezvaluie informatii despre quilboar si duc la o misiune in Razorfen Kraul, unde trebuie invinsa vrajitoarea Charlga Razorflank.",al={"misiunea crone of the kraul","continuarea jurnalului lui lonebrow"}}},fx={a9190e03={q="Ce este Lonebrow's Journal?",a="Lonebrow's Journal este un jurnal personal, ros de vreme, gasit strans in mainile scheletice ale piticului Henrig Lonebrow. Descoperit la poalele Great Lift din Thousand Needles, acesta ii consemneaza calatoriile si ultimele dorinte inainte sa-si gaseasca sfarsitul in canion.",al={"jurnalul lui Lonebrow, ce este","ce este cartea asta","jurnalul lui Henrig Lonebrow"}},["090ee1d4"]={q="De unde provine Lonebrow's Journal si cine l-a facut?",a="Jurnalul a fost scris de Henrig Lonebrow, un calator pitic care a strabatut canioanele primejdioase din Thousand Needles. L-a purtat cu el pana la moartea sa, in apropierea bazei Great Lift, unde ramasitele sale si volumul au fost descoperite in cele din urma.",al={"cine a scris jurnalul lui Lonebrow","autorul jurnalului lui Lonebrow","de unde provine jurnalul"}},ea8f453f={q="De ce si-ar dori cineva Lonebrow's Journal?",a="Predarea jurnalului implineste ultimele dorinte ale piticului cazut. Falfindel Waywarder, un druid Night Elf aflat la Thalanaar, la granita cu Feralas, vrea sa-i citeasca insemnarile pentru a intelege soarta lui Henrig si a descoperi pericolele care se pregatesc in Razorfen Kraul.",al={"de ce sa duc jurnalul lui Lonebrow","cine are nevoie de jurnalul lui Lonebrow","de ce vor jurnalul lui Lonebrow"}}},fp="18,277,30.495.0,20.327.1,24.221.0,27.151.0,38.150.0,30.175.1"}
P.entries["item:lorgalis-manuscript"] = {n="Lorgalis Manuscript",s="Lorgalis Manuscript este un text stravechi legat de venerarea si istoria Old Gods, pastrat din ruinele night elven cazute, de sub Ashenvale. Ascuns in complexul templului scufundat din Blackfathom Deeps, pastreaza secrete ravnite de cercetatori intunecati, dornici sa trezeasca puteri stravechi si adormite.",h="Lorgalis Manuscript este un text stravechi legat de venerarea si istoria Old Gods, pastrat din ruinele night...",kw={"blackfathom deeps","forlorn cavern","gerrig bonegrip","ironforge","lorgalis","manuscript","old god","cei care dorm"},ang={["class:Warlock"]="Manuscrisul ofera o rara privire asupra traditiilor interzise ale Old Gods si ale entitatilor din adancuri, dezvaluind cunostinte ravnite de cei care se ocupa cu artele intunecate.",["race:NightElf"]="Textul se afla in ruinele inundate unde locuiau odinioara night elves, iar veneratia sa pentru Aku'mai si Old Gods dezvaluie cultul intunecat care s-a inradacinat in acele sali cazute."},sec={{t="Un tom al celor adormiti",b="Lorgalis Manuscript se afla pe fundul Blackfathom Deeps, ruinele scufundate unde elfii disparuti de multa vreme au trait candva, inainte de caderea orasului lor. Scris de un oarecare Lorgalis, textul vorbeste despre Old Gods care au cuprins Azeroth cu furie cand lumea era noua si care zac acum inlantuiti si adormiti; il preamareste totodata pe Aku'mai, un slujitor al Old Gods care salasluieste in Deeps. Se spune ca invatatura sa poate deschide porti mistice si trezi entitati stravechi care dorm adanc sub lume. Pastrat intr-un cufar de fier ciuruit, printre coridoarele inundate, a atras atentia cultistilor si a invatatilor umbrelor deopotriva."},{t="Ochi in umbra",b="In Forlorn Cavern din Ironforge, un colectionar excentric pe nume Gerrig Bonegrip angajeaza aventurieri indrazneti sa treaca marea si sa recupereze textul. Bonegrip vorbeste cu veneratie despre 'zilele de pe urma' si trezirea zeitatilor adormite. Dupa ce este recuperat, textul urmeaza sa fie transcris si impartasit cercului sau tainuit de frati si surori, raspindind invataturi interzise, pe care locuitorii de la suprafata nu trebuiau niciodata sa le inteleaga."}},faq={{q="Ce este Lorgalis Manuscript?",a="Este un text vechi, scris de un anume Lorgalis, care contine cunostinte intunecate si ezoterice despre Old Gods. Se spune ca in el se afla secretele necesare pentru a descuia porti si a trezi entitati primordiale adormite.",al={"ce este Lorgalis Manuscript","povestea cartii Lorgalis","ce face manuscrisul"}},{q="Unde se afla manuscrisul?",a="Manuscrisul se afla intr-un cufar de fier ciuruit, scufundat adanc in Blackfathom Deeps, un templu Night Elf in ruine de-a lungul Zoram Strand, in Ashenvale.",al={"unde gasesti Lorgalis Manuscript","locatia manuscrisului","cufarul Blackfathom"}},{q="Cine vrea manuscrisul?",a="Gerrig Bonegrip, un pastrator enigmatic al traditiei, care isi desfasoara activitatea din Forlorn Cavern, in Ironforge, le incredinteaza aventurierilor sarcina de a-l recupera. Planuieste sa-i copieze invataturile stravechi si sa le raspandeasca printre confratii sai discreti.",al={"cine vrea Lorgalis Manuscript","misiunea lui Gerrig Bonegrip","cine este Bonegrip"}},{q="De ce vorbeste Gerrig Bonegrip despre zilele de pe urma?",a="Bonegrip se alatura celor care studiaza si venereaza Old Gods. Interesul sau pentru scrierile elfe stravechi se concentreaza asupra cunostintelor care ar putea sa-i trezeasca pe 'Those Who Sleep', vestind ceea ce el considera a fi sfarsitul vremurilor.",al={"Gerrig si sfarsitul zilelor","cultist Bonegrip","Bonegrip si Old Gods"}}},fx={["61ae2bf7"]={q="De unde provine Lorgalis Manuscript si cine l-a creat?",a="Manuscrisul a fost scris de un anume Lorgalis si zace pe fundul lui Blackfathom Deeps, ruinele scufundate unde locuiau candva elfii, disparuti de multa vreme, inainte de caderea orasului lor. Nu se stie cine a fost Lorgalis. Textul consemneaza cunoasteri interzise despre Old Gods si Cei Care Dorm si il preamareste pe Aku'mai, un slujitor al Old Gods care salasluieste in Deeps. Este incuiat intr-un cufar de fier rodat, in salile inundate.",al={"originea Lorgalis Manuscript","cine a scris Lorgalis Manuscript","unde a fost creat Lorgalis Manuscript"}}},fp="19,301,25.582.0,19.443.1,32.216.0,32.161.0,25.210.0,49.217.0"}
