P.entries["item:mary-s-looking-glass"] = {n="Mary's Looking Glass",s="Mary's Looking Glass este o oglinda de mana abandonata, pretuita odinioara de Blind Mary, inainte ca tragedia sa-i rapeasca vederea si viata. Lasata in padurile bantuite din Duskwood, a fost scotocita de un ghoul ratacitor, apoi cautata pentru a intregi telescopul lui Viktori Prism'Antras.",h="Mary's Looking Glass este o oglinda de mana abandonata, pretuita odinioara de Blind Mary, inainte ca tragedia...",kw={"blind mary","darkshire","duskwood","ghoul nebun","look to the stars","oglinda","mary's looking glass","cimitirul Tranquil Gardens","viktori prism'antras"},ang={["faction:Alliance"]="Recuperarea relicvelor din ghearele ororilor care bantuie Tranquil Gardens Cemetery le ofera o oarecare alinare cetatenilor impovarati din Darkshire si sprijina proiectele orasului.",["profession:Engineering"]="Inginerii pot aprecia ingeniozitatea lui Viktori, care a transformat o oglinda veche de uz casnic intr-un reflector optic functional pentru un instrument de observare astronomica."},sec={{t="O comoara Forsaken",b="Inainte de soarta ei cumplita, Blind Mary tinea mult la aceasta oglinda lustruita. Dupa moarte si pierderea ochilor, sa-si priveasca chipul devenise o amintire chinuitoare a ceea ce pierduse. A aruncat oglinda in spatele hambarului, lasand-o prada beznei care se apropia din Duskwood. Acolo a ajuns in ghearele unui ghoul nebun, ratacind prin periferiile in ruina, care a dus obiectul spre sud, in criptele din Tranquil Gardens Cemetery."},{t="Privind spre ceruri",b="In Darkshire, excentricul astronom Viktori Prism'Antras visa sa priveasca prin amurgul vesnic din Duskwood, spre cerul senin de deasupra. Construirea telescopului sau necesita lentile optice speciale si sticla reflectorizanta. Aflind de ce avea nevoie, Mary i-a indrumat pe aventurieri sa-i vineze pe mortii-vii salbatici care dau tircoale capelei in ruina a cimitirului, pentru a recupera oglinda, pe care urma sa o foloseasca drept reflector optic in aparatul sau urias de observat stelele."}},faq={{q="De ce a aruncat Mary oglinda?",a="Oglinda a fost candva una dintre cele mai pretioase comori ale lui Mary, dar a aruncat-o in spatele hambarului dupa un incident despre care nu vorbeste pe deplin. Intr-o alta intalnire, ea explica faptul ca si-a scos ochii, fiindca nu-si putea suporta infatisarea.",al={"de ce a aruncat-o Mary","de ce a aruncat oglinda","povestea oglinzii lui Blind Mary"}},{q="Cine a ajuns sa aiba oglinda dupa ce Mary a aruncat-o?",a="Un Ghoul Nebun, care ratacea prin padurile din spatele vechii ferme a lui Mary, a cotrobait prin lucrurile aruncate si a gasit oglinda. Strigoiul smintit si-a stabilit in cele din urma salasul in capela parasita din Tranquil Gardens Cemetery.",al={"cine are oglinda","cine a scapat oglinda","unde este oglinda"}},{q="De ce vrea Viktori Prism'Antras oglinda lui Mary?",a="Viktori construieste un telescop elaborat pentru a strapunge bezna din Duskwood si a studia stelele. Are nevoie de o suprafata reflectorizanta fina pentru a directiona lumina prin aparat, iar sticla conservata a lui Mary se potriveste perfect proiectului sau.",al={"de ce are Viktori nevoie de oglinda","utilizarea oglinzii de buzunar a lui Viktori","oglinda telescopului"}},{q="Unde poate fi gasit Ghoul-ul nebun care tine oglinda?",a="Insane Ghoul pandeste in coltul indepartat din sud-estul tinutului Duskwood, bantuid de obicei capela de piatra in ruina din Tranquil Gardens Cemetery.",al={"locatia ghoulului nebun","unde se afla ghoulul nebun","ghoulul din Tranquil Gardens"}}},fx={afb2ba8d={q="Ce este Mary's Looking Glass?",a="Mary's Looking Glass este o oglinda de mana care ii apartinuse candva lui Blind Mary, inainte ca tragedia sa o loveasca. Mary o considera una dintre cele mai de pret comori personale ale sale, dar in cele din urma a aruncat-o in spatele hambarului, dupa un incident ingrozitor. Mai tarziu, aceasta a ajuns in ghearele unui ghoul ratacitor, strigoi, din Duskwood.",al={"ce este oglinda lui Mary","obiectul oglinda lui Mary","oglinda lui Blind Mary"}}},fp="20,269,19.454.0,19.443.0,42.239.0,53.200.0,56.227.0,55.147.0"}
