P.entries["item:mountain-lion-blood"] = {n="Mountain Lion Blood",s="Mountain Lion Blood este un reactiv colectat de la pradatorii care dau tarcoale prin Hillsbrad Foothills si pe pantele inzapezite din Alterac. Apothecary Lydon din Tarren Mill cauta acest sange proaspat pentru a prepara temutul Elixir of Pain al Royal Apothecary Society.",h="Mountain Lion Blood este un reactiv colectat de la pradatorii care dau tarcoale prin Hillsbrad Foothills si...",kw={"Alterac","Apothecary Lydon","Elixir of Pain","Hillsbrad","sange de leu de munte","Royal Apothecary Society","Tarren Mill"},ang={["faction:Horde"]="Adunarea reactivilor din animale in jurul Tarren Mill intareste direct prezenta fortificata a Hordei impotriva enclavelor umane ostile din Hillsbrad.",["race:Undead"]="Fiecare fiola adunata ajuta Royal Apothecary Society sa dezvolte arme biologice devastatoare pentru a asigura Lordaeron pentru Forsaken."},sec={{t="Reactivul dealurilor",b="Inaltimile si colinele de la marginea Hillsbrad si Alterac sunt strabatute de lei de munte salbatici si infometati. In vreme ce vanatorii obisnuiti ii cauta pentru blana si ghearele lor, Forsaken din Royal Apothecary Society vad valoare in ceea ce le curge prin vine. Sangele proaspat de leu de munte are anumite proprietati biologice despre care Apothecary Lydon din Tarren Mill crede ca vor sta la baza unei noi bauturi toxice, puternice, menite sa le aduca suferinta celor vii."},{t="Alimentarea New Plague",b="Experimentele lui Apothecary Lydon din Tarren Mill contribuie direct la misiunea generala a Royal Apothecary Society: desavarsirea New Plague a Forsaken. Recoltand sangele fiarelor salbatice viguroase, Lydon incearca sa perfectioneze o potiune pe care o numeste Elixir of Pain, testand cat de puternice pot fi substantele organice locale transformate in arme impotriva dusmanilor Dark Lady."}},faq={{q="La ce foloseste Mountain Lion Blood?",a="Apothecary Lydon din Tarren Mill are nevoie de zece fiole de Mountain Lion Blood pentru a distila un amestec letal numit Elixir of Pain, parte a cercetarilor Royal Apothecary Society asupra unor boli noi.",al={"la ce foloseste sangele de leu de munte","cine are nevoie de sange de leu","sange de leu pentru Elixir of Pain"}},{q="Unde se poate colecta Mountain Lion Blood?",a="Este adunata de la leii de munte care vaneaza prin Hillsbrad Foothills si pana in crestele inzapezite invecinate din Alterac Mountains.",al={"unde gasesc sange de leu de munte","locatia sangelui de leu de munte","ce lei lasa sange"}},{q="De ce vrea Apothecary Lydon in mod special sange de pisica salbatica?",a="Lydon crede ca fluidele vitale ale leilor de munte agresivi si rezistenti sunt baza biologica ideala pentru prepararea unei licori toxice deosebit de chinuitoare, menita locuitorilor in viata din Hillsbrad.",al={"de ce sange de leu","de ce vrea Lydon sange de leu"}},{q="Este Mountain Lion Blood util pentru retetele de alchimie?",a="Nu. Este un reactiv experimental de cercetare, adunat exclusiv pentru activitatea personala a lui Apothecary Lydon, si nu este un ingredient folosit in alchimia standard a meseriilor.",al={"pot alchimistii folosi sange de leu de munte","este sangele de leu folosit in alchimie"}}},fx={dcf44a54={q="Ce este Mountain Lion Blood?",a="Este sange proaspat recoltat de la leii de munte pradatori care cutreiera pantele accidentate din Hillsbrad Foothills si Alterac Mountains. Desi nu le este de folos alchimistilor de rand sau mestesugarilor, proprietatile sale biologice sunt pretioase pentru experimentele alchimice letale ale Royal Apothecary Society.",al={"ce este sangele de leu de munte","povestea sangelui de leu de munte","ce este acest sange"}},["7c379830"]={q="De unde provine Mountain Lion Blood si cine l-a obtinut?",a="Nu este confectionata sau fabricata, ci se obtine direct de la pisicile salbatice native din nordul Lordaeronului. Puma de munte care cutreiera tinuturile inalte dintre Hillsbrad si Alterac sunt vanate si sangerate de agentii care lucreaza pentru farmacistii Forsaken stationati la Tarren Mill.",al={"de unde provine sangele de leu de munte","sursa sangelui de leu de munte","cine a creat sangele de leu de munte"}}},fp="19,253,20.474.0,22.370.0,37.200.0,43.139.0,59.206.0,59.158.0"}
P.entries["item:muddy-journal-pages"] = {n="Muddy Journal Pages"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="Mudsnout Blossoms sunt formatiuni fungice toxice, cu miros intepator, care cresc in Nethander Stead, in Hillsbrad Foothills. Pazite de gnollii locali si recoltate de Royal Apothecary Society, aceste ciuperci dezgustatoare sunt folosite in cercetarea elixirurilor lui Apothecary Lydon.",h="Mudsnout Blossoms sunt formatiuni fungice toxice, cu miros intepator, care cresc in Nethander Stead, in...",kw={"Apothecary Lydon","Elixir of Agony","colinele Hillsbrad","Mudsnout Blossom","gnoli Mudsnout","Nethander Stead","Tarren Mill"},ang={["profession:Herbalism"]="Desi botanistii si fitoterapeutii i-ar putea confunda numele cu cel al unei flori obisnuite, Mudsnout Blossom este de fapt o ciuperca volatila si urat mirositoare, pretuita de toxicologi si alchimisti ai intunericului.",["race:Undead"]="Forsaken folosesc pe scara larga proprietatile toxice ale florii, culegand-o pentru a rafina arme biochimice destinate Royal Apothecary Society."},sec={{t="O ciuperca toxica",b="In ciuda numelui lor floral, Mudsnout Blossoms sunt de fapt ciuperci mari, rau mirositoare, care cresc mai ales in pamantul murdar de la Nethander Stead, la sud de Tarren Mill. Rasare printre taberele gnollilor locali Mudsnout, care isi apara cu inversunare teritoriul. Pentru organismele vii, sporii si carnea ciupercii actioneaza ca o otrava virulenta, provocand agonie si degradare biologica rapida."},{t="Combustibil pentru Royal Apothecary Society",b="In Tarren Mill, Apothecary Lydon cauta Mudsnout Blossoms ca materie prima pentru experimentele sale chimice. Sub mandatul Lady Sylvanas Windrunner, Royal Apothecary Society trudeste fara incetare pentru a crea o noua molima, capabila sa nimiceasca atat Scourge, cat si omenirea vie. Proprietatile corozive ale acestor ciuperci, care vestejesc carnea, le fac o componenta de baza ideala pentru potiunea lui Lydon, infamul Elixir of Agony."}},faq={{q="Ce este un Mudsnout Blossom?",a="Desi i se spune floare, este o ciuperca mare, intepatoare si otravitoare, care creste in solul umed din Hillsbrad Foothills.",al={"povestea despre Mudsnout Blossom","este Mudsnout Blossom o floare","ce fel de planta este Mudsnout Blossom"}},{q="Unde cresc Mudsnout Blossoms?",a="Ele cresc pe tot cuprinsul Nethander Stead, o ferma abandonata la sud de Tarren Mill si la est de raul care curge pe langa Southshore. Zona este puternic infestata cu gnolli Mudsnout.",al={"locatia mudsnout blossom","unde gasesc flori mudsnout","ciuperci de la nethander stead"}},{q="De ce le colecteaza Royal Apothecary Society?",a="Apothecary Lydon din Tarren Mill are nevoie de ele pentru a prepara Elixir of Agony. Forsaken cerceteaza toxine care sa-i ajute sa creeze o noua plaga, capabila sa nimiceasca atat viii, cat si Scourge.",al={"de ce vrea lydon mudsnout blossoms","elixir of agony ingrediente","apothecary lydon ciuperca"}},{q="La ce foloseste Royal Apothecary Society florile?",a="Apothecary Lydon aduna ciupercile urat mirositoare pentru urmatorul sau elixir, in cadrul cercetarilor Forsaken asupra bolilor si otravurilor.",al={"experimente cu Mudsnout Blossom","utilizarea elixirului Mudsnout Blossom"}}},fx={f0998bd9={q="De unde provin Mudsnout Blossoms?",a="Mudsnout Blossoms sunt ciuperci mari si urat mirositoare, care cresc pe campurile din Nethander Stead, in sudul Hillsbrad Foothills. Se dezvolta in jurul gnollilor Mudsnout care salasluiesc acolo si isi pazesc cu inversunare peticul de pamant, desi nu se stie daca gnollii cultiva intentionat ciupercile intepatoare sau doar isi fac cuib printre ele.",al={"originea mudsnout blossom","de unde au aparut mudsnout blossoms","cine a creat mudsnout blossom"}}},fp="16,254,14.399.0,37.429.1,27.120.0,32.181.0,52.192.0,60.134.0"}
P.entries["item:mudsnout-composite"] = {n="Mudsnout Composite",s="Mudsnout Composite este o pasta alchimica preparata de Apothecary Lydon in Tarren Mill din Mudsnout Blossoms recoltate. Este un ingredient de baza esential, transportat in Undercity pentru cercetarile Royal Apothecary Society asupra unei noi molime.",h="Mudsnout Composite este o pasta alchimica preparata de Apothecary Lydon in Tarren Mill din Mudsnout Blossoms...",kw={"apothecarium","apothecary lydon","elixir of agony","master apothecary faranell","mudsnout blossom","mudsnout composite","royal apothecary society"},ang={["profession:Herbalism"]="Mudsnout Blossoms dovedesc ca pana si flora locala modesta poate fi zdrobita si transformata in arma sub privirea experimentata a unui apotecar.",["race:Undead"]="Fiecare transport de acest fel, precum acest amestec, contribuie direct la misiunea Dark Lady: asigurarea viitorului celor Forsaken prin dezvoltarea unei plagi care sa-i distruga atat pe cei vii, cat si pe Scourge."},sec={{t="O baza pentru putrezire",b="Acest amestec fin, preparat pe teren de Apothecary Lydon, este obtinut direct din Mudsnout Blossoms culese in Hillsbrad Foothills. Desi este otravitor de unul singur, are nevoie de un coloid special de descompunere - pregatit chiar de Master Apothecary Faranell - pentru a-si dezlantui insusirile letale. Odata combinat, amestecul devine o componenta chimica esentiala in crearea Elixir of Agony al Dark Lady."},{t="Corespondenta apotecarilor",b="Transportarea compusului de la Tarren Mill la Apothecarium din Undercity reflecta natura descentralizata si iterativa a alchimiei Forsaken. Cercetatorii de teren aduna in permanenta reactivi regionali si trimit mostre inapoi maestrilor din capitala, pentru rafinare. In ciuda cererilor insistente ale Lady Sylvanas de a grabi rezultatele impotriva oamenilor vii si a celor din Scourge, Faranell apreciaza compusul drept o baza ingenioasa pentru atingerea scopului lor mai amplu."}},faq={{q="La ce se foloseste Mudsnout Composite?",a="Este o pasta intermediara preparata din Mudsnout Blossoms. Master Apothecary Faranell trebuie sa o trateze cu un coloid al descompunerii in Undercity, pentru a ajuta la prepararea Elixir of Agony.",al={"scopul amestecului Mudsnout","la ce foloseste amestecul Mudsnout"}},{q="Cine a creat compusul?",a="Apothecary Lydon, un cercetator Forsaken stationat la Tarren Mill, in Hillsbrad Foothills, a zdrobit flori proaspete pentru a prepara pasta, apoi a trimis-o spre nord.",al={"cine a creat amestecul Mudsnout","creatorul amestecului Mudsnout"}},{q="De ce are nevoie Master Apothecary Faranell de el?",a="Faranell supravegheaza marea lucrare a Royal Apothecary Society pentru crearea unei noi plagi. Amestecul lui Lydon furnizeaza baza vegetala specifica, necesara progresului cercetarilor lor asupra toxinelor letale.",al={"de ce sa-l duci la Faranell","Faranell si Mudsnout"}}},fx={["432a2438"]={q="Ce este Mudsnout Composite?",a="Mudsnout Composite este un amestec rafinat, preparat de Apothecary Lydon in Tarren Mill. Obtinut prin macinarea unor Mudsnout Blossoms rare, care se gasesc in Hillsbrad Foothills, acest compus puternic este o baza alchimica esentiala in cercetarile Royal Apothecary Society de a crea o noua molima devastatoare pentru Forsaken.",al={"amestecul mudsnout","ce este amestecul mudsnout"}}},fp="18,249,16.417.0,25.449.1,40.196.0,26.157.0,44.190.0"}
P.entries["item:mudsnout-mixture"] = {n="Mudsnout Mixture",s="Mudsnout Mixture este o baza alchimica toxica, concoctata de Master Apothecary Faranell in Undercity. Creat prin amestecarea unui compus din bot de noroi cu un coloid alchimic al putrezirii, acesta sta la baza letalului Elixir of Agony al Royal Apothecary Society.",h="Mudsnout Mixture este o baza alchimica toxica, concoctata de Master Apothecary Faranell in Undercity.",kw={"farmacist","coloid de descompunere","Elixir of Agony","Faranell","Hillsbrad","Lydon","amestecul Mudsnout","Undercity"},ang={["faction:Horde"]="Aventurierii Hoardei care lucreaza in Tarren Mill actioneaza ca mesageri si agenti de teren, transportand amestecuri toxice prin Lordaeron pentru a consolida pozitia Forsaken in Hillsbrad.",["race:Undead"]="Amestecul demonstreaza ingeniozitatea necrutatoare a Royal Apothecary Society, care transforma ingrediente obisnuite din salbaticie in arme chimice menite sa-i nimiceasca pe cei vii."},sec={{t="Un coloid al descompunerii",b="Cand Apothecary Lydon din Tarren Mill vrea sa creeze o noua arma biologica virulenta, trimite spre Undercity un amestec de baza din Mudsnout Blossoms, ciuperci toxice din Nethander Stead, stapanita de gnolli. Impresionat de potentialul amestecului, Master Apothecary Faranell isi adauga propriul coloid de putrefactie, obtinand Mudsnout Mixture, o solutie instabila. Aceasta stabilizeaza compusul de ciuperci, pregatindu-i totodata proprietatile virulente pentru o rafinare catalitica ulterioara, inapoi, la poalele dealurilor."},{t="Catalizarea agoniei",b="Desi este puternic de una singura, Mudsnout Mixture ramane inerta fara catalizatorii esentiali care sa-i activeze agentii contaminanti. Faranell le cere curierilor sa duca flaconul inapoi la Tarren Mill, alaturi de un elixir Strong Troll's Blood, solzi veninosi de naga Daggerspine si ochi de murloc Torn Fin. Odata catalizata de Lydon, aceasta mixtura devine letalul Elixir of Agony - o otrava specifica, menita sa raspandeasca distrugerea printre dusmanii vii ai Forsaken."}},faq={{q="La ce se foloseste Mudsnout Mixture?",a="Serveste drept baza chimica intermediara pentru Elixir of Agony, o otrava experimentala perfectionata de Apothecary Lydon in Tarren Mill pentru a-i macelari pe dusmanii Forsaken.",al={"scopul amestecului Mudsnout","la ce foloseste amestecul Mudsnout","utilizarea amestecului Mudsnout"}},{q="Cine prepara Mudsnout Mixture?",a="Master Apothecary Faranell, conducatorul Royal Apothecary Society, care locuieste in Apothecarium of the Undercity, o prepara infuzand un amestec crud de Mudsnout cu propriul sau coloid al descompunerii.",al={"cine prepara amestecul mudsnout","creatorul amestecului mudsnout"}},{q="De ce necesita componente de gnoll?",a="Nu, in ciuda numelui. Amestecul este facut din Mudsnout Blossoms, ciuperci toxice care cresc la Nethander Stead printre gnoll-ii Mudsnout; Apothecary Lydon le amesteca pentru a obtine compozitul, inainte ca Faranell sa-i adauge coloidul de putreziciune.",al={"de ce mudsnout","povestea otravii gnoll"}},{q="Cum este activat amestecul?",a="Pentru a activa agentii contaminanti latenti din amestec, Apothecary Lydon are nevoie de un Elixir din sange de Troll puternic, precum si de solzi de naga Daggerspine si ochi de murloc Torn Fin, recoltati de-a lungul coastei Hillsbrad.",al={"activeaza amestecul Mudsnout","reactivii Elixir of Agony"}}},fx={f656f7cb={q="Ce este Mudsnout Mixture?",a="Este o potiune alchimica experimentala, conceputa de Royal Apothecary Society. Alcatuit dintr-un amestec de Mudsnout Blossoms si ciuperci otravitoare din Nethander Stead, preparatul include si coloidul de descompunere propriu al lui Master Apothecary Faranell, folosit drept baza instabila pentru cercetarile apotecarilor asupra molimei.",al={"ce este amestecul Mudsnout","amestecul Mudsnout","compozitia Mudsnout"}},ac01c76e={q="De ce vrea Apothecary Lydon Mudsnout Mixture?",a="Apothecary Lydon din Tarren Mill are nevoie de el pentru a sintetiza Elixir of Agony, o potiune experimentala menita sa raspandeasca boala si moartea printre dusmanii Forsaken. Activandu-i agentii contaminanti cu sange de troll si reactivi de coasta, el intentioneaza sa dezvolte cercetarea despre plagi a Royal Apothecary Society.",al={"de ce este necesar amestecul Mudsnout","de ce vrea Lydon amestecul Mudsnout","la ce foloseste amestecul Mudsnout"}}},fp="16,266,18.511.0,20.436.1,38.184.0,33.196.0,37.235.0,29.216.0"}
P.entries["item:murloc-head"] = {n="Murloc Head",s="Murloc Heads sunt trofee sinistre, retezate de la creaturile amfibii care dau tarcoale prin Western Strand, in Hillsbrad Foothills. Lieutenant Farren Orinelle din Southshore le cere drept dovada materiala a eliminarii amenintarilor, pentru a-si multumi superiorul, Marshal Redpath.",h="Murloc Heads sunt trofee sinistre, retezate de la creaturile amfibii care dau tarcoale prin Western Strand...",kw={"Farren Orinelle","Farren's Proof","dealurile Hillsbrad","Marshal Redpath","murloc","cap de murloc","Southshore","Western Strand"},ang={["faction:Alliance"]="Eliberarea Western Strand protejeaza fragila economie piscicola din Southshore si securizeaza coasta pentru o fortareata Alliance vulnerabila din Lordaeron."},sec={{t="O dovada si mai infioratoare",b="Southshore este amenintat din toate directiile, insa murlocii agresivi stransi de-a lungul Western Strand reprezinta un pericol imediat pentru pescarii locali si calatorii de pe coasta. Desi aventurierii Alliance matura frecvent plajele pentru a rari aceste creaturi, seriful Marcus Redpath cere dovezi incontestabile inainte de a aproba rapoartele despre aparare. Pentru a-i face pe plac birocratiei, Lieutenant Farren Orinelle se bazeaza pe luptatori platiti, care sa aduca capete de murloci reci si picurande, o sarcina neplacuta pe care Farren insusi o gaseste cu totul dezgustatoare, mai ales fiindca privelistea i-a taiat pofta de mancare pentru fructele de mare locale din Southshore."}},faq={{q="De ce vrea Farren Orinelle capete de murloc?",a="Maresalul Marcus Redpath nu s-a multumit cu simple rapoarte despre alungarea murlocilor de pe plaje. Pentru a verifica daca amenintarea fusese cu adevarat redusa, a cerut dovezi concrete, obligandu-l pe locotenentul Farren sa adune capete retezate drept dovada.",al={"dovada lui Farren","de ce capete de murloc","cine vrea capete de murloc in Southshore"}},{q="Unde se gasesc acesti murloci?",a="Sunt adunate de la triburile de murloci care napadesc Western Strand, fasia de coasta de la vest de Southshore, in Hillsbrad Foothills.",al={"locatia capetelor de murloc","de unde iei capete de murloc in Hillsbrad","murlocii din Western Strand"}},{q="De ce i se face atat de scarba lui Farren din cauza lor?",a="Lui Farren i se par pestii care umbla pe jos profund nefiresti si gretosi. Privelistea capetelor taiate, pline de mazga si sange, care picura pe podea il dezgusta atat de tare, incat refuza sa manance peste, aliment de baza intr-un oras-port precum Southshore.",al={"reactia lui Farren","Farren mancand peste"}},{q="Rezolva strangerea capetelor problema murlocilor din Southshore?",a="Capetele constituie dovada ceruta de Marshal Redpath. Acesta accepta livrarea, apoi ii cere lui Farren sa-si indrepte atentia catre amenintarile de pe Eastern Strand.",al={"inceteaza murlocii sa atace","lantul de misiuni al lui Farren"}}},fx={ab7abae9={q="Ce este un Murloc Head?",a="Este capul abia taiat al unui murloc ucis pe coasta din Hillsbrad Foothills. Rece, vascos si scurgand lichide respingatoare, este dovada fizica incontestabila a unei bestii ucise in apararea Southshore.",al={"ce este capul de murloc","informatii despre capul de murloc","obiectul cap de murloc"}},["598cfa24"]={q="De unde provin Murloc Heads?",a="Sunt taiate direct din trupurile murlocilor care pandesc pe Western Strand, chiar la vest de Southshore. Nu sunt obiecte mestesugite, ci trofee macabre luate de la jefuitorii de pe tarm care pun in pericol garnizoana Alliance.",al={"unde cad capetele de murloc","cine a facut capul de murloc","sursa capului de murloc"}}},fp="11,253,24.630.0,43.239.0,30.138.0,35.248.0,60.158.0"}
P.entries["item:musquash-root"] = {n="Musquash Root",s="Sub Stonewrought Dam, Musquash Root creste in Wetlands. Radacina rara este greu de cules, iar un coven ascuns sub Stormwind are nevoie de ea pentru o potiune.",h="Sub Stonewrought Dam, Musquash Root creste in Wetlands.",kw={"a noble brew","lord Wishock","Musquash Root","Stonewrought Dam","Tear of Tilloa","zonele umede","Zardeth"},ang={["class:Warlock"]="Ca Warlock sub Slaughtered Lamb, ai nevoie de aceasta radacina pentru a-i reduce la tacere pe nobilii bagareti si a-ti proteja sanctuarul fragil din oras.",["profession:Herbalism"]="Ca herbalist, poti vedea cum umezeala de sub cascadele barajului Stonewrought Dam hraneste o flora neobisnuita si periculoasa."},sec={{t="Un ingredient rar",b="Musquash Root creste in pamantul umed de sub cascadele Stonewrought Dam. Ceata si locul retras fac planta greu de cules. Putini herbalisti o cauta, dar practicantii artelor intunecate ii pretuiesc proprietatile chimice si alchimice."},{t="Planul lui Warlock",b="Zardeth of the Black Claw cauta Musquash Root si Tear of Tilloa sub Stormwind, in Slaughtered Lamb. Plantele rare vor alcatui o potiune discreta, menita sa-l neutralizeze pe Lord Wishock, un membru al House of Nobles care a inceput sa cerceteze conclavul ascuns de Warlock din oras."}},faq={{q="Unde se gaseste Musquash Root?",a="Musquash Root creste in Wetlands, la poalele cascadei de sub Stonewrought Dam.",al={"unde se afla Musquash Root","locatia lui Musquash Root","cum gasesti Musquash Root"}},{q="La ce este folosita Musquash Root?",a="Zardeth of the Black Claw doreste Musquash Root si Tear of Tilloa pentru o potiune menita sa-l tina ocupat pe Lord Wishock si sa-i zadarniceasca demersul de a cere o ancheta asupra covenului de warlock din Stormwind.",al={"ce efect are musquash root","rolul musquash root","de ce am nevoie de musquash root"}},{q="Cine vrea sa fie culeasa aceasta radacina?",a="Zardeth of the Black Claw, un warlock din catacombele de sub Slaughtered Lamb, in Mage Quarter din Stormwind, trimite agenti sa recupereze Musquash Root.",al={"cine are nevoie de musquash root","cine ofera misiunea legata de musquash root","cine solicita musquash root"}},{q="Cine este Lord Wishock?",a="Lord Wishock este membru al House of Nobles din Stormwind. Dupa ce a aflat despre covenul de warlocks din oras, a inceput sa indemne consiliul sa deschida o ancheta oficiala.",al={"cine este wishock","lord wishock"}}},fx={["32cf7ee1"]={q="Ce este Musquash Root?",a="Musquash Root este o planta rara care creste indeosebi in stropii umezi si cetosi de la baza cascadei de sub Stonewrought Dam, in Wetlands. Cunoscuta alchimistilor intunecati si vracilor pentru proprietatile sale naturale puternice, este un ingredient esential in prepararea bauturilor inselatoare si a otravurilor, atunci cand este combinata cu alte plante rare.",al={"ce este Musquash Root","povestea despre Musquash Root","informatii despre Musquash Root"}},d9341dd1={q="De unde provine Musquash Root si cine a facut-o?",a="Musquash Root este o planta naturala, nu o creatie artificiala. Creste numai in Wetlands, inradacinata in piatra umeda si solul imbibat de la poalele cascadei aflate chiar sub marele Stonewrought Dam.",al={"originea musquash root","unde creste musquash root","cine a creat musquash root"}}},fp="13,157,17.237.0,20.277.1,29.91.0,31.186.0,30.153.0,20.165.0"}
P.entries["item:mysterious-fossil"] = {n="Mysterious Fossil"}
P.entries["item:nak-s-skull"] = {n="Nak's Skull"}
P.entries["item:nek-rosh-s-head"] = {n="Nek'rosh's Head",s="Nek'rosh's Head este dovada macabra a caderii lui Nek'rosh, capetenia Dragonmaw clan din Wetlands. Obtinut de aventurieri din Alliance, acest trofeu ii este inmanat lui Captain Stoutfist pentru a confirma ca amenintarea orcilor care primejduia Menethil Harbor a fost nimicita.",h="Nek'rosh's Head este dovada macabra a caderii lui Nek'rosh, capetenia Dragonmaw clan din Wetlands.",kw={"Captain Stoutfist","sef de trib","Dragonmaw","Menethil","Nek'rosh","Nekrosh","Wetlands"},ang={["faction:Alliance"]="Prezentarea acestui trofeu sumbru lui Captain Stoutfist protejeaza Menethil Harbor de un atac iminent si iti castiga trecere importanta in ochii Kingdom of Ironforge.",["race:Dwarf"]="Dragonmaw ii chinuie pe locuitorii din Khaz Modan inca din Second War; purtarea capului taiat al capeteniei aduce dreptatea mult asteptata aparatorilor tinuturilor mlastinoase."},sec={{t="O lovitura decisiva",b="Dragonmaw clan reprezinta o primejdie permanenta in mlastini, unde isi aduna fortele si armele de asediu impotriva portului Menethil Harbor, aflat sub stapanirea Alliance. Dupa ce le dau foc catapultelor, aparatorii portului trebuie sa-l ucida pe Chieftain Nek'rosh. Taierea capului sau ii ofera lui Captain Stoutfist si autoritatilor din Ironforge dovada de netagaduit ca stapanirea razboinicului asupra Wetlandsului a luat sfarsit."}},faq={{q="Cine a fost Nek'rosh?",a="Nek'rosh era capetenia care comanda ramasitele organizatiei Dragonmaw clan, active in Wetlands, orchestrand atacuri si eforturi de razboi indreptate impotriva teritoriilor din apropiere ale Alliance.",al={"cine este Nek'rosh","capetenia Nek'rosh","cine a fost Nekrosh"}},{q="Cine vrea Nek'rosh's Head?",a="Captain Stoutfist, comandantul care coordoneaza apararea din Menethil Harbor, are nevoie de cap drept dovada concreta ca seful de trib a fost invins, inainte de a-l rasplati pe campion in numele lui Ironforge.",al={"cine ia capul","predarea capului lui Nek'rosh","unde duc capul lui Nek'rosh"}},{q="De ce a fost vizat Nek'rosh pentru a fi ucis?",a="Nek'rosh a condus fortele Dragonmaw care amenintau Menethil Harbor. Distrugandu-le armele de asediu si eliminandu-le capetenia, Alliance a urmarit sa dea o lovitura devastatoare prezentei clanului in regiune.",al={"de ce sa-l ucid pe nekrosh","de ce defeat nek'rosh"}}},fx={e464fcda={q="Ce este Nek'rosh's Head?",a="Este capul taiat al Chieftain Nek'rosh, conducatorul de razboi al Dragonmaw clan din Wetlands. Este o dovada macabra si incontestabila ca cel mai mare dusman local al Ironforge Mountaineers a fost, in sfarsit, ucis.",al={"ce este capul lui nekrosh","obiectul capul lui nekrosh","capul taiat al lui nekrosh"}},["160e4c8d"]={q="De unde provine Nek'rosh's Head si cine l-a creat?",a="Este luat direct de la capetenia Nek'rosh dupa ce il invingi in tabara Dragonmaw din Wetlands. Nu a fost faurit sau fabricat, ci retezat de la capetenia orc cazuta, ca trofeu si dovada a mortii sale.",al={"de unde provine capul lui Nekrosh","cum obtii capul lui Nekrosh","originea capului lui Nekrosh"}},ce210494={q="De ce vrea Captain Stoutfist Nek'rosh's Head?",a="Captain Stoutfist cere dovezi incontestabile ca liderul Dragonmaw clan a fost infrant. Cu Nek'rosh mort si catapultele lor de razboi distruse, Stoutfist stie ca Dragonmaw va avea dificultati in a-si reveni, asigurand astfel ca Menethil Harbor si Wetlands sunt in sfarsit in siguranta in fata unui atac organizat.",al={"de ce vrea Stoutfist capul lui Nekrosh","de ce vor capul lui Nekrosh","scopul capului lui Nekrosh"}}},fp="15,281,17.395.0,17.175.0,26.198.0,36.220.0"}
P.entries["item:neru-fragment"] = {n="Neru Fragment",s="Neru Fragment este una dintre cele patru piese de piatra sculptata straveche care alcatuiesc Goaz Stone, o relicva descoperita la situl de excavare Whelgar's Excavation din Wetlands. Dezgropata din pamantul rascolit, contine un fragment de scriere straveche Titan, care descrie istoria primordiala a Azeroth.",h="Neru Fragment este una dintre cele patru piese de piatra sculptata straveche care alcatuiesc Goaz Stone, o...",kw={"sapatura","goaz stone","pamant afanat","fragmentul lui Neru","prospector whelgar","uncovering the past","wetlands"},ang={["race:Dwarf"]="Pentru Explorer's League, recuperarea fragmentelor de tablite precum Neru Fragment este esentiala pentru dezvaluirea secretelor Titan si reconstituirea originilor neamului piticilor."},sec={{t="Fragment din Goaz Stone",b="Descoperita de expeditia arheologica dwarven condusa de Prospector Whelgar, Goaz Stone s-a sfaramat in patru ramasite distincte: fragmentele Ados, Modr, Golm si Neru. Cand raptoarele au napadit situl de excavare, lucrarile s-au oprit, iar Neru Fragment a ramas ingropat sub pamantul afanat, in mijlocul fiarelor agresive. Recuperarea fragmentului este esentiala pentru reasamblarea tablitei, permitandu-le carturarilor dwarven sa descifreze o insemnare uitata, ale carei cuvinte pastrate pomenesc un plan divin si o profetie tragica."},{t="Citirea tablitei restaurate",b="Dupa ce cele patru fragmente restaureaza Goaz Stone, Prospector Whelgar continua sa-i traduca inscriptia in limba Titan. Cuvintele devenite acum lizibile vorbesc despre Old Gods inlantuiti sub pamant."}},faq={{q="Ce este Neru Fragment?",a="Este o bucata de piatra straveche desprinsa dintr-o relicva mai mare, numita Goaz Stone. Expeditia dwarf a descoperit-o in Wetlands, inainte ca raptoarele sa le napadeasca sapatura.",al={"povestea fragmentului Neru","ce este fragmentul Neru","bucata din tablitele Neru"}},{q="Unde se gaseste fragmentul?",a="Este imprastiata prin Whelgar's Excavation, plina de raptoare, la est de Menethil Harbor, in Wetlands; de obicei este ingropata sub pamant afanat sau ascunsa printre artefacte abandonate.",al={"unde gasesti fragmentul lui Neru","locatia fragmentului lui Neru","cum obtii fragmentul lui Neru"}},{q="Ce se intampla cand sunt adunate toate cele patru fragmente?",a="Prospector Whelgar reasambleaza Goaz Stone pentru a putea continua sa-i descifreze scrierea Titan si sa cerceteze misterul sugerat de textul ramas.",al={"Goaz Stone, completa","ce spune Goaz Stone","deznodamantul din Uncovering the Past"}}},fx={["1f660d59"]={q="De unde provine Neru Fragment si cine l-a creat?",a="Fragmentul provine din piatra straveche Goaz Stone, descoperita la Whelgar's Excavation, in Wetlands. Inscrisul foloseste scrierea Titan, dar textul recuperat al misiunii nu-i identifica autorul.",al={"originea fragmentului neru","cine a creat fragmentul neru","de unde provine fragmentul neru"}},b6f45f31={q="De ce vrea Prospector Whelgar Neru Fragment?",a="Prospector Whelgar a dezgropat Goaz Stone chiar inainte ca situl sapaturilor sa fie invadat de raptori, dar a descoperit ca inscriptia se intrerupea in patru locuri distincte. Are nevoie urgent de Neru Fragment, alaturi de celelalte trei bucati, pentru a asambla tablitele si a continua descifrarea referintelor la un plan divin si la o profetie despre osanda.",al={"de ce sa gasesti fragmentul Neru","de ce are Whelgar nevoie de fragmentul Neru","scopul fragmentului Neru"}}},fp="13,284,23.503.0,27.174.1,26.175.0,28.173.0,50.163.1"}
P.entries["item:nessa-s-collection"] = {n="Nessa's Collection"}
P.entries["item:nether-gem"] = {n="Nether Gem",s="Nether Gem este o piatra arcana fermecata, incredintata de o figura enigmatica de la Brightwater Lake. Incarcata cu putere magica, ea serveste drept canal de comunicare la mare distanta, permitandu-i stapanului sa proiecteze o aparitie arcana si sa comunice direct cu Bethor Iceshard din Undercity, desi natura deplina a legaturii dintre ei ramane de descoperit.",h="Nether Gem este o piatra arcana fermecata, incredintata de o figura enigmatica de la Brightwater Lake.",kw={"bethor iceshard","brightwater lake","gunther arcanus","nether gem","prodigal lich","undercity"},ang={["class:Mage"]="Pentru practicantii magiei arcane, Nether Gem arata cum magii iscusiti strabat distante uriase prin clarviziune magica si proiectarea unor imagini, in loc sa-si riste viata calatorind.",["race:Undead"]="Livrarea pietrei marcheaza un triumf diplomatic major pentru Forsaken, castigandu-l ca aliat pe puternicul Gunther Arcanus impotriva Scourge si a Scarlet Crusade."},sec={{t="Un canal al comuniunii arcane",b="Faurita sau vrajita de Gunther Arcanus pe insula sa izolata din Brightwater Lake, Nether Gem serveste drept legatura mistica in Tirisfal Glades. Dupa ce s-a eliberat prin propria vointa neclintita de sub controlul Lich King, Gunther a evitat multa vreme, din suspiciune, natiunea Forsaken abia nascuta. Dupa ce isi primeste inapoi cartea de vraji pierduta, incredinteaza gema unui emisar, ca gest de bunavointa. Odata adusa la Bethor Iceshard, in varful Magic Quarter din Undercity, piatra proiecteaza chipul magic al lui Gunther direct in fata conducatorului Breslei Magilor, deschizand calea pentru ca magul singuratic sa se alieze cu Lady Sylvanas si Forsaken."}},faq={{q="Ce face Nether Gem?",a="Nether Gem ii permite lui Gunther Arcanus sa comunice de la mare distanta cu Bethor Iceshard. Cand Bethor canalizeaza magie in piatra, in Undercity, aceasta proiecteaza o imagine eterica a lui Gunther, permitandu-le celor doi magi puternici sa vorbeasca direct.",al={"scopul Nether Gem","ce este Nether Gem","ce face Nether Gem"}},{q="Cine a faurit Nether Gem?",a="Nestemata ii este oferita de Gunther Arcanus, un necromant redutabil care locuieste pe o insula din Brightwater Lake. El i-o da unui aventurier, pentru a o duce vechiului sau tovaras Bethor, dupa ce ii este returnata cartea de vraji pierduta.",al={"cine a creat Nether Gem","de unde provine Nether Gem","nestemata lui Gunther"}},{q="De ce este Nether Gem importanta pentru Forsaken?",a="Obiectul este instrumentul care il aduce cu succes pe Gunther Arcanus de partea celor din Forsaken. La inceput, Gunther nu avea incredere in ceilalti strigoi, temandu-se ca erau inca sclavi ai Scourge; gema ii permite sa reia legatura cu Bethor Iceshard si sa-si jure credinta fata de Lady Sylvanas.",al={"de ce este importanta Nether Gem","Gunther, Forsaken","Nether Gem a Forsakenilor"}}},fx={aa73e2cb={q="Ce este Nether Gem?",a="Nether Gem este un focar magic incredintat tie de Gunther Arcanus, un mag strigoi puternic care locuieste pe o insula din Brightwater Lake. Incarcat cu energii arcane mistice, serveste drept canal magic prin care Gunther poate comunica de la mari distante si isi poate proiecta chipul direct catre vechiul sau aliat, Bethor Iceshard, in Undercity.",al={"ce este Nether Gem","povestea Nether Gem","obiectul Nether Gem"}}},fp="10,357,29.636.1,28.250.0,27.218.1,50.288.1"}
P.entries["item:ng-5"] = {n="NG-5",s="NG-5 este denumirea prescurtata pentru Nitromirglyceronium, un compus chimic renumit pentru volatilitatea sa. Procurat pentru inventatorul gnom Gaxim Rustfizzle din Stonetalon Mountains, este catalizatorul esential pentru planurile sale ingineresti explozive.",h="NG-5 este denumirea prescurtata pentru Nitromirglyceronium, un compus chimic renumit pentru volatilitatea sa.",kw={"dinamita","explozibili","Gaxim Rustfizzle","Gnome","NG-5","NG5","Nitromirglyceronium","Stonetalon"},ang={["profession:Engineering"]="Inginerii vor recunoaste NG-5 drept Nitromirglyceronium, un catalizator chimic capricios, pretuit de mesteri atunci cand pulberea neagra obisnuita nu are forta necesara pentru a aprinde munitia grea.",["race:Gnome"]="Folosirea unei solutii chimice instabile pentru a arunca in aer vagoane intregi cu dinamita doar ca diversiune este ingeniozitatea gnomica in forma ei cea mai buna: riscanta si spectaculoasa."},sec={{t="Un reactiv instabil",b="Cunoscut oficial sub numele de Nitromirglyceronium, NG-5 este o solutie chimica extrem de periculoasa, manipulata numai cu precautie extrema - sau cu entuziasm gnomesc nesabuit. Gaxim Rustfizzle, un agent aflat in Stonetalon Mountains, are nevoie de aceasta substanta ca element esential pentru aprindere. Potrivit lui Gaxim, NG-5 produce reactia exacta necesara pentru a detona vagoane intregi incarcate cu dinamita, provocand o explozie uriasa menita sa serveasca drept diversiune haotica impotriva adversarilor sai din regiune."}},faq={{q="Ce este NG-5?",a="NG-5 vine de la Nitromirglyceronium, un amestec chimic extrem de instabil si volatil, folosit in principal ca reactiv de aprindere exploziv in demolari avansate si in ingineria gnomica.",al={"ce este ng5","ce este Nitromirglyceronium","obiect ng 5"}},{q="Cine il vrea pe NG-5 si de ce?",a="Gnomul inginer Gaxim Rustfizzle din Stonetalon Mountains are nevoie de substanta chimica. Ea este componenta esentiala pentru a aprinde in mod sigur mai multe care incarcate cu dinamita, menite sa creeze o diversiune spectaculoasa.",al={"cine are nevoie de NG-5","NG-5 pentru Gaxim Rustfizzle","de ce sa iau NG-5"}},{q="Este periculos sa manevrezi NG-5?",a="Extrem de periculos. Furnizorul ii avertizeaza pe curieri sa manipuleze compusul cu mare grija, glumind ca oricine nu este aliat cu Gaxim va sfarsi, cel mai probabil, facandu-se bucati.",al={"este NG-5 sigur","exploziv NG-5","va exploda NG-5"}}},fx={["43a87313"]={q="De unde provine NG-5 si cine l-a fabricat?",a="NG-5, cunoscut si sub numele de Nitromirglyceronium, este obtinut de la o cunostinta a lui Gaxim Rustfizzle, care prepara compusi chimici speciali. Este un amestec alchimic extrem de volatil, conceput special pentru reactii explozive si oferit doar insotit de avertismente severe cu privire la cat de usor poate spulbera un curier neatent.",al={"cine a creat NG-5","de unde obtii NG-5","creatorul NG-5"}}},fp="4,253,18.509.0,13.183.0,23.224.0,28.187.0"}
P.entries["item:nida-s-necklace"] = {n="Hilary's Necklace",s="Hilary's Necklace este o amintire draga din copilarie, pierduta sub apele lacului Lake Everstill din Redridge Mountains. Daruita tinerei Hilary de tatal ei, bijuteria a alunecat in apele tulburi cand copiii din Lakeshire pescuiau pe docuri.",h="Hilary's Necklace este o amintire draga din copilarie, pierduta sub apele lacului Lake Everstill din Redridge...",kw={"Effsee","noroi sclipitor","Hilary","Lake Everstill","Lakeshire","Nida","colierul lui Nida","Redridge","Shawn"},ang={["faction:Alliance"]="Aparatorii din Lakeshire sunt suprasolicitati de amenintarile din jur, astfel ca micile gesturi de bunatate - precum ajutorul dat copiilor din partea locului pentru a-si recupera obiectele dragi pierdute - raman in seama aventurierilor Alliance aflati in trecere."},sec={{t="Pierdut in adancuri",b="In timp ce pescuia de-a lungul malului din Lakeshire impreuna cu prietenul ei Shawn, tanara Hilary si-a scapat din greseala pretiosul colier in Lake Everstill. Mostenirea are o valoare sentimentala uriasa, fiind un dar primit de la tatal ei. De teama fiarelor feroce si a murlocilor agresivi din adancuri, copiii din partea locului stau in siguranta pe docuri, lasand colierul scufundat si ingropat in malul de pe fundul lacului, pana cand un aventurier va fi dispus sa se scufunde in apa tulbure ca sa-l recupereze."}},faq={{q="Cui ii apartine acest colier?",a="Colierul ii apartine lui Hilary, o fetita care locuieste in orasul Lakeshire din Redridge Mountains. A fost un dar special primit de la tatal ei.",al={"cine detine colierul","cine detine colierul Nidei","al cui este acest colier","cine detine colierul lui Hilary"}},{q="Cum a ajuns colierul in Lake Everstill?",a="Hilary pescuia langa apa impreuna cu tovarasul ei, Shawn, cand colierul i-a alunecat de la gat si s-a scufundat pe fundul lacului, ajungand intr-o movilita de namol sclipitor.",al={"cum a ajuns in lac","de ce este colierul in apa","cum s-a pierdut colierul"}},{q="De ce nu s-au scufundat copiii ca sa-l recupereze?",a="Parintii lor le interzic cu strictete sa inoate in Lake Everstill. Apele adanci adapostesc pradatori acvatici periculosi si murloci agresivi, care reprezinta o amenintare mortala pentru localnici.",al={"de ce Nida n-a inotat dupa el","de ce nu poate Shawn sa ia colierul","de ce Hilary n-a inotat dupa el"}},{q="Cine este Effsee?",a="Effsee este pisica de companie a Hilary. Sta langa ea in Lakeshire si il intampina bucuroasa pe cel care ii inapoiaza colierul, alaturi de tanara sa stapana.",al={"cine e pisicuta","nida cat","pisica hilary"}}},fx={a22bd4db={q="De unde si-a luat Hilary colierul?",a="Colierul a fost un dar de la tatal lui Hilary. Desi are o valoare istorica sau magica redusa, este o amintire de familie pretioasa, daruita unei fetite care locuieste in Lakeshire.",al={"cine a facut colierul lui hilary","de unde provine colierul lui hilary","cine i-a dat colierul lui hilary"}},["14f3017c"]={q="De ce este cautat Hilary's Necklace?",a="Hilary si-a pierdut colierul in timp ce pescuia de-a lungul docurilor de pe Lake Everstill. Pentru ca parintii ei le interzic copiilor sa se scufunde in apele pline de monstri, prietenul ei Shawn le cere aventurierilor aflati in trecere sa infrunte adancurile lacului si sa-i recupereze amintirea draga.",al={"de ce sa caut colierul lui hilary","cine vrea colierul lui hilary","de ce vrea hilary sa-si recapete colierul"}}},fp="17,266,18.487.0,33.156.0,46.171.0,47.193.0,14.132.0"}
P.entries["item:nightmare-shard"] = {n="Nightmare Shard",s="Nightmare Shard este o relicva cristalina pe care Falla Sagewind o incredinteaza curierilor dupa ce examineaza un fragment stralucitor, corupt, recuperat din Wailing Caverns. Continand esenta pura si tulburata a Emerald Dream, poarta o viziune nelinistitoare care ii face pe druizii de rang inalt din Darnassus si Thunder Bluff sa dea imediat alarma si sa pastreze tacerea.",h="Nightmare Shard este o relicva cristalina pe care Falla Sagewind o incredinteaza curierilor dupa ce...",kw={"emerald dream","falla sagewind","fragment stralucitor","hamuul runetotem","in nightmares","mathrengyl bearwalker","nightmare shard","wailing caverns"},ang={["class:Druid"]="Pentru druizi, fragmentul dezvaluie cu fiori ca sanctuarul lor sacru, Emerald Dream, nu mai este neatins de corupere, confirmandu-le temerile legate de soarta lui Naralex in Wailing Caverns.",["faction:Horde"]="Fragmentul duce vesti cumplite direct la Elder Rise din Thunder Bluff, unde Hamuul Runetotem se straduieste sa intareasca locul taurenilor in marea comunitate Cenarion."},sec={{t="O viziune corupta",b="Cand Falla Sagewind cerceteaza ciobul misterios si stralucitor, dezgropat adanc in Wailing Caverns, isi da seama ca energia acestuia este cu mult mai intunecata decat se asteptase. In loc sa oglindeasca vitalitatea senina a Emerald Dream, fragmentul reflecta o suferinta rasucita, nefireasca - un cosmar trait cu ochii deschisi. Temandu-se de ceea ce ar putea insemna prezenta lui, ea leaga aceasta esenta pangarita in Nightmare Shard si porunceste ca acesta sa fie dus fara intarziere direct la conducatorii venerabili din Cenarion Circle."},{t="Prevestiri tacute",b="La predarea obiectului catre arhidruidul Hamuul Runetotem de pe Elder Rise sau Mathrengyl Bearwalker din Darnassus, ambii maestri reactioneaza cu uimire si consternare cand privesc in adancurile sale. Viziunea din interior le clatina stapanirea de sine, confirmandu-le banuielile tacute ca ceva a mers cumplit de rau chiar in Dream. Nedorind sa starneasca panica in randul publicului, druizii confisca repede fragmentul si il avertizeaza pe curier sa nu mai vorbeasca despre cele vazute."}},faq={{q="Ce este Nightmare Shard?",a="Este un ciob incredintat aventurierilor de Falla Sagewind, care contine esenta capturata a Emerald Dream, extrasa dintr-un artefact adus din Wailing Caverns. In locul energiilor pasnice ale naturii, emana o viziune intunecata si corupatoare a visului.",al={"ce este Nightmare Shard","povestea lui Nightmare Shard"}},{q="Cine a creat Nightmare Shard?",a="Falla Sagewind ii da fragmentul curierului dupa ce analizeaza o bucata stralucitoare adusa din Wailing Caverns. Dandu-si seama de gravitatea si coruptia naturii sale, ii incredinteaza curierului sarcina de a-l duce direct la druizii seniori pentru studiu.",al={"cine a creat nightmare shard","de unde provine fragmentul"}},{q="De ce sunt atat de alarmati conducatorii druidilor de acesta?",a="Privind in ciob, Hamuul Runetotem si Mathrengyl Bearwalker descopera ca Emerald Dream este rasucit in mod activ de un cosmar. Din cauza pericolului si a panicii pe care aceasta dezvaluire le-ar putea provoca, ambii batrani opresc imediat orice discutie ulterioara si pastreaza chestiunea strict intre membrii seniori ai Cenarion Circle.",al={"de ce este Hamuul ingrijorat","de ce ascunde Mathrengyl fragmentul"}},{q="Unde trebuie livrata aschia?",a="Aventurierilor Horde li se cere sa o duca la arhidruidul Hamuul Runetotem, pe Elder Rise din Thunder Bluff, in timp ce calatorii Alliance o duc la Mathrengyl Bearwalker, aflat in Cenarion Circle din Darnassus.",al={"cui duc fragmentul","unde predau Nightmare Shard"}}},fp="15,344,18.487.0,12.467.1,28.253.0,32.245.0,43.337.1,42.208.0"}
P.entries["item:nightsaber-fang"] = {n="Nightsaber Fang"}
P.entries["item:nissa-s-remains"] = {n="Nissa's Remains",s="Nissa's Remains sunt ramasitele pamantesti recuperate ale Nissei Agamand, o nobila din dinastia Agamand, candva instarita, din nordul Tirisfal Glades. Ucisa si ridicata ca slujitoare fara minte a Scourge in timpul Third War, ea si familia sa sunt acum vanate de fostii muncitori, care cauta razbunare.",h="Nissa's Remains sunt ramasitele pamantesti recuperate ale Nissei Agamand, o nobila din dinastia Agamand...",kw={"fabricile Agamand","Brill","Coleman Farthing","Deaths in the Family","Nissa Agamand","ramasitele Nissei","Tirisfal Glades"},ang={["faction:Horde"]="Ucidera Agamands reanimati si curatarea morilor lor asigura securitatea nordului Tirisfal Glades, eliminand focarele persistente de Scourge care ameninta Brill si Undercity.",["race:Undead"]="Pentru Forsaken, recucerirea Tirisfalului inseamna sa-i alunge atat pe fostii lor asupritori din Scourge, cat si pe aristocratii bogati care i-au osandit pe muncitorii de rand la viata de mort-viu, dintr-o mandrie nesabuita."},sec={{t="O mostenire a mandriei",b="Inainte de Third War, familia Agamand era cea mai bogata si mai influenta dinastie din Tirisfal Glades si detinea mori prospere pe dealurile nordice. Cand Plague of Undeath s-a intins peste Lordaeron, patriarhii familiei au refuzat cu incapatanare sa evacueze. In schimb, si-au fortificat mosiile si si-au convins slujitorii si muncitorii sa nu cedeze. Aceasta aroganta i-a costat pe toti viata. Agamands au cazut in fata Scourge si s-au ridicat nu cu mandra lor independenta neatinsa, ci ca sclavi tarsaiti si lipsiti de minte, legati de vointa lui Lich King."},{t="Razbunare amara",b="In orasul Brill, supravietuitorii care mai tarziu si-au castigat libertatea sub conducerea reginei Sylvanas Windrunner nu au uitat mandria fatala a familiei. Coleman Farthing, fost muncitor in morile Agamand, poarta pica fostilor sai stapani pentru ca si-au atras lucratorii in ghearele mortii vii. El le cere aventurierilor sa-i doboare pe Agamands inviati si sa le recupereze ramasitele fizice, precum cele ale Nissei. Pentru Farthing si altii dintre Forsaken, arderea sau distrugerea acestor relicve aduce un sentiment sumbru de incheiere definitiva si razbunare plina de ranchiuna."}},faq={{q="Cine a fost Nissa Agamand?",a="Nissa era membra a familiei Agamand, nobili din Lordaeron care detineau intinsele Agamand Mills din Tirisfal Glades. Cand Scourge a napadit Lordaeron, ea a pierit alaturi de rudele sale si a fost inviata ca slujitoare strigoi, aflata sub controlul Lich King.",al={"cine este nissa","povestea lui nissa","nissa agamand"}},{q="De ce vrea Coleman Farthing ramasitele Nissei?",a="Coleman Farthing a lucrat in viata la morile Agamand. Ii poarta familiei o ranchiuna amara, deoarece refuzul ei arogant de a fugi i-a convins pe muncitorii loiali sa ramana si sa moara. Adunarea ramasitelor lor ii permite sa se razbune pe fostii stapani.",al={"de ce coleman vrea ramasitele","de ce sunt ucisi agamands","motivul lui coleman farthing"}},{q="Unde sunt stranse aceste ramasite?",a="Nissa Agamand bantuie ruinele Agamand Mills din nordul Tirisfal Glades, ratacind printre fermele darapanate alaturi de rudele ei reanimate si de thrall-urile fara minte ale Scourge.",al={"unde o gasesc pe Nissa","locatia Nissei in Agamand"}},{q="Si-a pastrat Nissa liberul arbitru, la fel ca Forsaken?",a="Nu. Spre deosebire de Forsaken, care s-au desprins de Lich King, Nissa si familia ei au ramas inrobita de Scourge, ca strigoi lipsiti de ratiune, fara constiinta si libertatea de care se bucura cetatenii din Undercity.",al={"nissa este forsaken","nissa avea liber arbitru","nissa este flagelul"}}},fx={a9aa03e3={q="Ce sunt Nissa's Remains?",a="Acestea sunt ramasitele trupesti ale lui Nissa Agamand, membra a bogatei dinastii Agamand, care stapanea candva morile din nordul Tirisfal Glades. Cand Scourge a strabatut Lordaeron, familia si-a fortificat domeniul si i-a convins pe muncitori sa reziste. La fel ca restul neamului ei, Nissa a cazut prada Plague si s-a ridicat ca o sluga fara minte in slujba Lich King.",al={"ce sunt ramasitele lui Nissa","ramasitele lui Nissa","cui apartin ramasitele lui Nissa"}},["4cb46b58"]={q="De unde provin Nissa's Remains si cine le-a creat?",a="Sunt recuperate chiar de pe cadavrul distrus al Nissei Agamand, de la Agamand Mills. Candva o aristocrata mandra, ea a cazut prada Plague of Undeath si a ramas pe pamanturile stramosesti ca o creatura moarta vie. Acestea sunt ramasitele pe care le salvezi dupa ce-i dai odihna formei lipsite de minte din randurile Scourge.",al={"de unde obtii ramasitele Nissei","cum obtii ramasitele Nissei","cine a lasat ramasitele Nissei"}}},fp="15,298,17.567.0,18.540.0,22.260.0,47.246.0,33.194.0,49.197.0"}
P.entries["item:nitroglycerin"] = {n="Nitroglycerin"}
P.entries["item:nondescript-letter"] = {n="Nondescript Letter",s="Nondescript Letter este o scrisoare pecetluita, fara niciun insemn, incredintata Forsaken nou treziti, care parasesc Deathknell. Inmanata de Calvin Montague sub pretextul unei insarcinari, ea il indruma pe purtator de-a lungul drumului, pana la Innkeeper Renee, la Gallows' End Tavern din Brill.",h="Nondescript Letter este o scrisoare pecetluita, fara niciun insemn, incredintata Forsaken nou treziti, care...",kw={"intelegerea unui Rogue","Brill","Calvin Montague","Deathknell","Innkeeper Renee","scrisoare fara descriere","Renee"},ang={["class:Rogue"]="Atitudinea sireata a lui Calvin Montague si schimbarea brusca de purtare a lui Renee poarta toate semnele intrigilor marunte ale celor din Rogue si ale comunicarii codificate din lumea interlopa.",["race:Undead"]="Pentru Forsaken abia ridicati din morti, aceasta scrisoare este unul dintre primele motive de a parasi limitele Deathknell si de a explora asezarile mai intinse din Tirisfal Glades."},sec={{t="O misiune pentru curier",b="Forsaken abia inviati, care vor sa plece din Deathknell, sunt abordati de Calvin Montague, un pungas siret care sta prin preajma marginii satului. Pretinzand ca s-a saturat sa lupte cu zombi si arahnide lipsite de minte, Calvin le cere calatorilor sa duca un plic simplu, fara insemne, pe drumul spre est, pana la Brill. Scrisoarea, adresata in treacat unui hangit pe nume Renee, este un pretext pentru a-i impinge pe calatori afara din vale si spre Gallows' End Tavern, desi promisiunile lui Calvin privind o rasplata bogata par de la bun inceput lipsite de temei."},{t="Corespondenta suspecta",b="Dupa ce primeste scrisoarea in Brill, Innkeeper Renee incearca mai intai sa joace o comedie exagerat de vesela, pretinzand ca trebuie sa fie o veste placuta de la mama ei sfanta din Deathknell. Cand isi da seama ca mesagerul s-a prins de jocul ei stangaci, buna dispozitie ii piere, inlocuita de o iritare acuta. Smulge scrisoarea, refuza sa spuna cine a trimis-o de fapt sau ce contine si-i porunceste taios purtatorului sa plece, daca nu vrea sa inchirieze o camera."}},faq={{q="Ce este Nondescript Letter?",a="Este un plic simplu, cu aspect obisnuit, pe care Calvin Montague il da aventurierilor Forsaken abia sositi in Deathknell, pentru a-l duce la Innkeeper Renee din Brill.",al={"scrisoare fara descriere","ce este aceasta scrisoare","scrisoarea lui Calvin"}},{q="Cine trimite scrisoarea si cine o primeste?",a="Calvin Montague, un hot stationat in Deathknell, le da scrisoarea curierilor. Este adresata Innkeeper Renee de la Gallows' End Tavern din Brill.",al={"cine a trimis scrisoarea","cine primeste scrisoarea","expeditorul scrisorii"}},{q="Ce spune de fapt scrisoarea?",a="Continutul exact al scrisorii nu ii este dezvaluit jucatorului. Cand este intrebata, Innkeeper Renee renunta la atitudinea ei vesela si iti spune furioasa ca originea si continutul scrisorii nu te privesc.",al={"ce scrie in scrisoare","continutul scrisorii","poti citi scrisoarea"}},{q="De ce vrea Calvin Montague sa fie livrat?",a="Calvin pretinde ca este prea prins cu lupta impotriva zombiilor si paianjenilor din zona pentru a face singur comisionul. In realitate, livrarea ii indruma pe calatori in afara Deathknell si le prezinta facilitatile si locurile de odihna disponibile in Brill.",al={"de ce sa trimiti scrisoarea","motivul lui Calvin","de ce Brill"}}},fp="18,262,18.530.0,25.447.1,31.163.0,42.151.0,34.214.0,43.230.0"}
P.entries["item:nori-s-mug"] = {n="Nori's Mug"}
P.entries["item:notched-rib"] = {n="Notched Rib",s="Notched Rib este un trofeu osos luat de la hoardele de morti-vii fara minte care ratacesc prin Tirisfal Glades. Deathguard Dillinger aduna aceste ramasite crestate in Brill, ca dovada a eforturilor de a slabi controlul Scourge asupra Agamand Mills.",h="Notched Rib este un trofeu osos luat de la hoardele de morti-vii fara minte care ratacesc prin Tirisfal...",kw={"agamand mills","Brill","soldat cu craniul crapat","deathguard dillinger","coasta crestata","soldat rattlecage","Scourge","Tirisfal Glades"},ang={["race:Undead"]="Pentru Forsaken, strangerea acestor oase sfaramate face parte dintr-un razboi continuu pentru supravietuire impotriva slugilor lipsite de minte ale Lich King, care ar vrea sa-i tarasca inapoi in sclavie."},sec={{t="O dovada cruda a luptei",b="Fortele Scourge care se aduna pe campurile nordice din Tirisfal Glades sunt alcatuite din schelete inviate, imbracate in armuri zdrentuite. Din randurile lor, soldatii Cracked Skull si Rattlecage se napustesc asupra oricarei fiinte vii sau inzestrate cu vointa libera pe care o intalnesc. Loviturile care le sfasie trupurile fragile le lasa oasele crapate si brazdate. Pentru a se asigura ca cercetasii si voluntarii Forsaken ii starpesc cu adevarat pe acesti intrusi lipsiti de minte, in loc sa se multumeasca sa-i observe, gardienii mortii cer dovezi palpabile. O coasta crestata si marcata de lupta dovedeste fara putinta de tagada ca inca un slujitor al Lich King a fost facut tandari."},{t="Asigurarea morilor",b="Agamand Mills reprezinta o pozitie strategica esentiala la nord-vest de Brill. Daca Scourge isi consolideaza temeinic pozitiile printre gospodariile si morile de vant ruinate, vor putea folosi locul ca baza de pornire pentru atacuri lansate adanc in inima lui Tirisfal. Deathguard Dillinger supravegheaza drumurile spre nord si trimite campioni sa zdrobeasca hoardele de schelete inainte ca acestea sa se poata intari. Gramezile de coaste crestate aduse inapoi la Brill dovedesc ca liniile Forsaken rezista si macina incet avangarda Scourge, os cu os."}},faq={{q="Ce este o Notched Rib?",a="Este un os scheletic, brazdat de cicatrice, luat de la soldatii Scourge inviorati, care ocupa nordul Tirisfal Glades. Este dus la Deathguard Dillinger ca dovada fizica a distrugerii dusmanilor.",al={"coasta crestata","ce este o coasta crestata","obiectul coasta crestata"}},{q="De unde provin Notched Rib-urile?",a="Sunt recuperate de la Cracked Skull Soldiers si Rattlecage Soldiers care patruleaza in perimetrul Agamand Mills, la nord-vest de Brill.",al={"unde gasesc o coasta crestata","cine lasa coaste crestate","sursa coastelor crestate"}},{q="Cine vrea aceste oase?",a="Deathguard Dillinger, stationat pe drumul chiar in afara orasului Brill, le strange impreuna cu Blackened Skulls, pentru a confirma ca inaintarea Scourge a fost respinsa.",al={"cine ia coastele crestate","unde se predau coastele crestate","cine are nevoie de o coasta crestata"}},{q="De ce se aduna Scourge la Agamand Mills?",a="Strigoii fara minte incearca sa-si stabileasca o baza de pregatire la mori. Din aceasta pozitie, fortele Scourge ar putea lansa cu usurinta atacuri in toata regiunea Tirisfal Glades si ar ameninta asezarile Forsaken.",al={"Scourge la Agamand Mills","de ce sunt schelete la mori","amenintarea Scourge de la Agamand Mills"}}},fp="11,236,20.629.0,18.542.0,22.191.0,32.141.0,22.157.0,46.196.0"}
P.entries["item:nugget-slug"] = {n="Nugget Slug",s="Nugget slugs sunt elemente de fixare mecanice speciale, de calibrul 17.5, folosite in ingineria industriala. Depozitate in galeti de scule de catre Venture Company la Sludge Fen, sunt ravnite de mestesugarii care incearca sa repare utilaje volatile.",h="Nugget slugs sunt elemente de fixare mecanice speciale, de calibrul 17.5, folosite in ingineria industriala.",kw={"barrens","melc nugget","samophlange","sludge fen","galeata de unelte","venture company","wenikee boltbucket"},ang={["profession:Engineering"]="Orice inginer stie ca amestecarea componentelor hardware proprietare de calibru saptesprezece virgula cinci cu un samophlange instabil, proiectat de goblini, e o invitatie la o demontare rapida si exploziva."},sec={{t="Elemente de fixare industriale din Sludge Fen",b="Nituri Nugget sunt elemente de fixare metalice rezistente, fabricate pentru ansambluri industriale solicitante. Cu calibrul precis de 17.5, aceste componente sunt esentiale pentru utilajele grele folosite in exploatarile Venture Company. Desi sunt inutile ca marfuri obisnuite, sunt indispensabile mestesugarilor care lucreaza cu echipamente goblin personalizate."},{t="Mesterind la Samophlange",b="Wenikee Boltbucket are nevoie de o colectie insemnata de melci-bobite pentru a repara un samoflang instabil, recuperat din Barrens. Cum Venture Company lasa in mod regulat galeti de scule imprastiate prin santierele sale de foraj de la Sludge Fen, operatiunile de recuperare se dovedesc banoase pentru scormonitori - chiar daca reparatiile lui Wenikee se incheie, in cele din urma, cu o explozie brusca."}},faq={{q="Ce este un limax de pepita?",a="Un bolt de tip nugget este un element de fixare sau un boltar metalic specializat, de calibrul 17.5, folosit in utilaje grele. Acestea servesc drept componente structurale in mecanisme industriale complexe, precum instalatiile de foraj petrolier si samophlange-urile.",al={"ce sunt nituri nugget","povestea niturilor nugget","element de fixare tip melc"}},{q="Unde se gasesc melcii cu pepite?",a="Sunt depozitate in galeti de unelte imprastiate prin Sludge Fen, o tabara de foraj a Venture Company situata in nord-estul Barrens.",al={"unde gasesc melcii Nugget","locatia melcului Nugget","Sludge Fen, galeti de scule"}},{q="De ce are nevoie Wenikee Boltbucket de ele?",a="Wenikee Boltbucket vrea sa mestereasca la un samophlange recuperat si sa-l repare. Fiindca a ramas fara elemente de fixare de calibrul saptesprezece virgula cinci, ii trimite pe aventurieri sa le recupereze din tabara apropiata a Venture Company.",al={"cine are nevoie de limacsi nugget","de ce vrea Wenikee limacsi","repararea Samophlange"}},{q="Folosirea melcilor nugget repara samophlange-ul?",a="Fara succes. Dupa ce Wenikee monteaza in masina melcii recuperati si incepe lucrarile de intretinere, samophlange-ul explodeaza brusc chiar in fata ei.",al={"functioneaza masina","explozia Samophlange","rezultatul reparatiei lui Wenikee"}}},fx={f3aea894={q="De unde provin niturile nugget si cine le fabrica?",a="Aceste proiectile de calibru saptesprezece virgula cinci sunt echipamente industriale folosite de Venture Company la Sludge Fen. Muncitorii si inginerii lor le pastreaza in stoc in galeti cu unelte raspandite prin zonele de foraj si excavare din estul Barrens.",al={"de unde provin melcii Nugget","cine produce melcii Nugget","originea melcului Nugget"}}},fp="11,232,38.358.0,30.376.1,22.206.0,29.133.0,38.215.0,48.156.1"}
P.entries["item:ogre-s-monocle"] = {n="Ogre's Monocle",s="Ogre's Monocle este un ochelar supradimensionat purtat de Zzarc'Vul, un capcaun care traieste in Vul'Gol Ogre Mound, in sudul Duskwood. Lentila sa uriasa ii ofera lui Viktori Prism'Antras din Darkshire dimensiunile exacte necesare pentru a asambla un telescop astronomic elaborat.",h="Ogre's Monocle este un ochelar supradimensionat purtat de Zzarc'Vul, un capcaun care traieste in Vul'Gol Ogre...",kw={"cog","darkshire","look to the stars","ogre's monocle","telescop","viktori prism'antras","vul'gol ogre mound","zzarc'vul"},ang={["faction:Alliance"]="Recuperarea lentilei de la ogrele Vul'Gol indeparteaza o bruta periculoasa din padurile sudice, ajutandu-i totodata pe cetatenii napastuiti din Darkshire sa-si gaseasca alinarea in stele.",["profession:Engineering"]="Proiectul lui Cog ilustreaza ambitia tipica a gnomilor: folosirea unor componente neobisnuite, precum ochelarii uriasi, atunci cand lentilele slefuite cu precizie nu sunt disponibile pe teren."},sec={{t="O lentila ciudata",b="Desi ogres nu sunt renumiti pentru invatatura rafinata, Zzarc'Vul a intrat cumva in posesia unui monoclu urias, potrivit staturii sale masive. Cand locuitorul din Darkshire, Viktori Prism'Antras, a pornit sa construiasca un instrument de observare a stelelor dupa planurile desenate de inginerul gnome Cog, a descoperit ca lentilele obisnuite erau mult prea mici. Ochelarii lui Zzarc'Vul s-au dovedit a fi singura bucata de sticla slefuita din regiune cu curbura si dimensiunile necesare pentru a focaliza lumina prin dispozitivul terminat."},{t="Smulgerea lui din Vul'Gol",b="Pentru a obtine monoclul, trebuie sa-ti faci curaj sa infrunti Vul'Gol Ogre Mound, la umbra partii sudice din Duskwood. Zzarc'Vul traieste printre fratii sai brutali si nu pare deloc dispus sa renunte de bunavoie la accesoriul sau distinctiv. Pentru a pune mana pe lentila, trebuie sa-l invingi pe propriul teritoriu, apoi sa duci sticla inapoi la Darkshire, ca Viktori sa-si poata indrepta in sfarsit privirea spre cerul noptii."}},faq={{q="Cine poarta Ogre's Monocle?",a="Monoclul este detinut de Zzarc'Vul, un ogre renumit care rataceste prin Vul'Gol Ogre Mound, in sudul Duskwood.",al={"cine lasa monoclul","cine are monoclul ogresc","obiectul lui Zzarc'Vul"}},{q="De ce are Viktori Prism'Antras nevoie de o lentila de ochean de ogre?",a="Viktori construieste un telescop dupa planurile desenate de gnomul Cog. Dispozitivul necesita o lentila optica neobisnuit de mare, iar monoculul masiv al lui Zzarc'Vul este singura bucata de sticla din Duskwood care corespunde specificatiilor.",al={"de ce e nevoie de un monoclu","la ce foloseste monoclul","lentila telescopului"}},{q="Cum a ajuns un ogre sa aiba un monoclu urias?",a="Sursa nu explica felul in care Zzarc'Vul a obtinut monoclul. Stabileste doar ca are unul suficient de mare pentru telescopul lui Viktori.",al={"de ce poarta un ogre monoclu","povestea ochelarilor de citit ai unui ogre"}},{q="Unde se afla Vul'Gol Ogre Mound?",a="Vul'Gol Ogre Mound se afla in dealurile sudice din Duskwood, la sud de drumul principal care trece intre Darkshire si granita vestica.",al={"unde este vulgol","movila capcaunilor din duskwood"}}},fx={["94fbe42d"]={q="Ce este Ogre's Monocle?",a="Ogre's Monocle este o lentila optica supradimensionata, purtata ca ochelar de Zzarc'Vul, un capcaun de seama care locuieste in Vul'Gol Ogre Mound, in sudul Duskwood. Desi asemenea accesorii optice fine sunt extrem de rare printre capcauni, lentila sa masiva de sticla o face deosebit de potrivita pentru utilaje optice grele.",al={"ce este monoclul de capcaun","obiectul monoclu de capcaun","luneta de capcaun"}}},fp="14,266,14.496.0,22.382.0,31.114.0,54.233.0,36.143.0,40.137.0"}
P.entries["item:okra"] = {n="Okra"}
P.entries["item:ordanus-head"] = {n="Ordanus' Head",s="Ordanus' Head este trofeul macabru luat de la Keeper Ordanus din Raynewood Retreat, in Ashenvale. Revendicat in numele magilor elfi de sange Braelyn Firehand, acesta serveste drept dovada incontestabila ca unul dintre cei mai varstnici fii ai lui Cenarius a cazut prada razbunarii arcane.",h="Ordanus' Head este trofeul macabru luat de la Keeper Ordanus din Raynewood Retreat, in Ashenvale.",kw={"ashenvale","braelyn firehand","cenarius","keeper of the grove","ordanus","ordanus' head","raynewood retreat","stonetalon","sunrock retreat"},ang={["class:Druid"]="Pentru un druid, purtarea capului retezat al unui fiu mai varstnic al lui Cenarius este o amintire sumbra a urii amare si sangeroase pe care vrajitorii arcani inca o nutresc fata de aparatorii salbaticiei.",["faction:Horde"]="Uciderea lui Ordanus si ducerea capului sau la Braelyn ajuta la consolidarea pozitiei Horde de-a lungul granitelor disputate dintre Stonetalon si Ashenvale, slabind conducerea locala a elfilor noptii."},sec={{t="O ranchiuna din trecut",b="Keeper Ordanus era un vechi pazitor al padurii, unul dintre urmasii de vaza ai zeului padurilor, Cenarius. Cand Braelyn Firehand a urcat pe culmile din Stonetalon Mountains, la porunca stapanului ei, voia sa puna capat reprimarii magiei de catre druizi in zona varfului si sa se razbune pe Ordanus. Pazitorul a fost insa dus in graba in inima tinutului Ashenvale, inainte ca ea sa-l poata lovi. Folosindu-se de clarviziunea arcana pentru a privi prin bolta padurii, Firehand si-a localizat sanctuarul printre ramurile din Raynewood Retreat, cerandu-i capul retezat drept dovada ca a raspuns, in sfarsit, arogantei semizeului salbatic."},{t="Pretul trufiei",b="Braelyn poarta de multa vreme pica impotriva lui Ordanus, pe care l-a cunoscut odinioara, si ii uraste pe druizii care incearca sa inabuse fluxul magiei. In timpul vietii, Ordanus se considera superior chiar si vechii nobilimi Highborne. Luandu-i capul, Firehand riposteaza simbolic impotriva mostenirii lui Cenarius, declarand ca niciun paznic al salbaticiei nu poate opri intoarcerea puterii magice neimblanzite."}},faq={{q="Cine a fost Keeper Ordanus?",a="Keeper Ordanus era un strajer stravechi al padurii si fiu mai mare al lui Cenarius. Cu mult timp in urma, s-a infruntat cu practicantii magiei arcane din randul nobilimii elfilor noptii, avand reputatia ca ii privea cu o profunda aroganta pe cei care practicau artele arcane.",al={"cine este Ordanus","povestea lui Ordanus","ce este Ordanus"}},{q="Unde este colectat acest cap?",a="Capul este luat de la Keeper Ordanus, de pe platforma inalta de lemn din Raynewood Retreat, o enclava fortificata a elfilor noptii, construita in copaci, in centrul Ashenvale.",al={"unde gasesc capul lui Ordanus","locatia lui Ordanus","Ordanus din Raynewood Retreat"}},{q="De ce vrea Braelyn Firehand capul lui?",a="Braelyn Firehand il cunostea pe Ordanus de mult timp si ii dispretuia aroganta, caci se considera superior chiar si celor din Highborne. De asemenea, ii uraste pe druizi si pe fiii lui Cenarius pentru ca incearca sa opreasca fluxul magiei si pentru ca l-au dus pe Ordanus departe de culme inainte ca ea sa ajunga la el.",al={"de ce vrea braelyn capul lui ordanus","ranchiuna lui braelyn","de ce sa-l ucizi pe ordanus"}},{q="Ce se intampla dupa ce este livrat capul?",a="Ducerea lui Ordanus' Head la Braelyn, la Sunrock Retreat, ii achita datoria de sange, iar ea il rasplateste pe mercenar cu darul puternic pe care i l-a promis.",al={"unde predau capul lui Ordanus","dupa ce moare Ordanus","recompensa misiunii lui Braelyn Firehand"}}},fx={e1459048={q="De unde provine Ordanus' Head?",a="Acest trofeu sumbru este luat direct de la Keeper Ordanus, unul dintre cei mai varstnici fii ai semizeului padurii Cenarius. Desi se credea candva in siguranta in varful Stonetalon Peak, Ordanus a fugit in Ashenvale si s-a adapostit sus, in Raynewood Retreat, inainte de a fi vanat si ucis.",al={"originea capului lui Ordanus","de unde provine capul lui Ordanus","cui ii apartine capul lui Ordanus"}}},fp="13,250,22.596.0,19.383.1,23.243.0,29.165.0,40.270.0,41.145.1"}
P.entries["item:orendil-s-cure"] = {n="Orendil's Cure",s="Orendil's Cure este o potiune medicinala preparata de ierboristul Orendil Broadleaf in nordul Ashenvale. Facuta din rara planta Bathran's Hair, este menita sa trateze misterioasa boala mortala de care sufera Relara Whitemoon in Astranaar.",h="Orendil's Cure este o potiune medicinala preparata de ierboristul Orendil Broadleaf in nordul Ashenvale.",kw={"ashenvale","astranaar","bathran's hair","orendil broadleaf","orendil's cure","pelturas whitemoon","relara"},ang={["profession:Herbalism"]="Remediul demonstreaza extraordinara putere medicinala a florei native din Ashenvale, in special a Bathran's Hair, care creste doar in anumite locuri umbroase ale padurii.",["race:NightElf"]="Pentru Night Elves din Astranaar, salvarea lui Relara este o chestiune urgenta pentru intreaga comunitate, care imbina cunoasterea padurii a pustnicilor precum Orendil cu credinta divina in Elune."},sec={{t="Speranta unui tata",b="Cand tanara Relara Whitemoon s-a imbolnavit grav in Astranaar, leacurile obisnuite s-au dovedit nefolositoare impotriva bolii sale. Tatal ei disperat, Pelturas Whitemoon, a apelat la Orendil Broadleaf, un pustnic si maestru al leacurilor naturale, care locuieste in tinuturile nordice din Ashenvale. Folosind manunchiuri din rara planta Bathran's Hair, culeasa din ruinele bantuite ale Bathran's Haunt, Orendil a preparat acest leac special. Sosirea fiolei ii da lui Pelturas speranta acolo unde inainte abia mai avea, desi leacul doar incetineste boala, iar Pelturas trebuie sa incerce remediile suplimentare sugerate de Orendil."}},faq={{q="La ce se foloseste Orendil's Cure?",a="Leacul a fost formulat pentru a o alina si trata pe Relara Whitemoon, o tanara copila Night Elf din Astranaar, doborata de o boala brusca si grava.",al={"scopul leacului lui orendil","ce efect are leacul","pentru cine este leacul"}},{q="Cine a preparat leacul?",a="A fost pregatita de Orendil Broadleaf, un herbalist night elf retras, care locuieste in padurile nordice din Ashenvale si e renumit pentru maiestria sa in folosirea florei padurii si a remediilor.",al={"cine a creat leacul lui Orendil","creatorul leacului lui Orendil"}},{q="Ce ingrediente au fost folosite la prepararea sa?",a="Ingredientul esential este Bathran's Hair, o planta delicata si rara, culeasa printre ruinele din Bathran's Haunt, in nordul Ashenvale.",al={"ingredientele leacului","ce contine leacul lui Orendil"}},{q="Vindeca aceasta potiune complet copilul?",a="Nu in intregime. Pelturas descopera mai tarziu ca leacul lui Orendil doar a incetinit boala care ii macina fiica, asa ca porneste in cautarea unui remediu mai puternic, sugerat de Orendil: Elune's Tear.",al={"a vindecat-o","este relara vindecata"}}},fx={["8e86537e"]={q="Ce este Orendil's Cure?",a="Orendil's Cure este un preparat medicinal facut de fitoterapeutul Orendil Broadleaf in nordul Ashenvale. Conceput ca tratament specializat pentru o afectiune brusca si grava, acesta reprezinta o incercare urgenta de a salva viata unui copil night elf care sufera de o maladie misterioasa.",al={"povestea leacului lui orendil","ce este leacul lui orendil","remediul lui orendil"}},["6add91d1"]={q="De ce este necesar Orendil's Cure?",a="In Astranaar, fiica tanara a lui Pelturas Whitemoon, Relara, este grav bolnava. Disperat sa gaseasca un leac dupa ce tratamentele obisnuite s-au dovedit ineficiente, tatal ei a apelat la priceperea lui Orendil Broadleaf. Herboristul a pregatit acest amestec special in speranta ca va stabiliza copila inainte ca boala sa-i curme viata.",al={"de ce este nevoie de leacul lui Orendil","cine are nevoie de leacul lui Orendil","de ce sa livrez leacul lui Orendil"}}},fp="14,245,15.600.0,32.151.0,21.175.0,38.136.0,43.182.1"}
P.entries["item:oslow-s-toolbox"] = {n="Oslow's Toolbox",s="Oslow's Toolbox contine uneltele esentiale de constructie de care are nevoie Foreman Oslow in Lakeshire. In drum din Goldshire, proviziile au fost transportate cu barca peste Lake Everstill, dar s-au scufundat in urma unui bombardament cu catapulte orce.",h="Oslow's Toolbox contine uneltele esentiale de constructie de care are nevoie Foreman Oslow in Lakeshire.",kw={"foreman oslow","lake everstill","lakeshire","oslow","redridge","lada scufundata","uneltele pierdute","cutie de unelte"},ang={["faction:Alliance"]="Cum Lakeshire este aproape izolata sub asediul Blackrock, recuperarea proviziilor lui Oslow este esentiala pentru a mentine intacte lucrarile de aparare ale orasului."},sec={{t="O traversare hotaratoare",b="Mentinerea apararii si a infrastructurii din Lakeshire este o incercare istovitoare, mai ales cand orcii Blackrock asediaza Redridge Mountains. Foreman Oslow a cerut sa-i fie aduse unelte importante de constructie din Goldshire. Cum podul principal care ducea in Lakeshire fusese distrus de inamic, transportul a trebuit incarcat intr-o barca cu rame pentru a traversa Lake Everstill. Traversarea s-a incheiat brusc, cand fortele Blackrock au lovit vasul cu o piatra de catapulta, trimitand barca si lada grea a lui Oslow drept in adancurile infestate de murloci."}},faq={{q="De ce se afla Oslow's Toolbox pe fundul lacului?",a="Transportul uneltelor venea din Goldshire. Deoarece podul din Lakeshire fusese distrus in timpul asediului, proviziile trebuiau sa traverseze Lake Everstill cu barca. Orcs Blackrock au bombardat barca cu vasle cu o catapulta, scufundand-o si trimitand lada cu unelte pe fundul lacului.",al={"de ce este trusa de scule in apa","cum si-a pierdut Oslow uneltele","povestea trusei de scule scufundate"}},{q="Cui ii apartine aceasta trusa de unelte?",a="Trusa de scule ii apartine lui Foreman Oslow, supraveghetorul lucrarilor de constructie si reparatie din Lakeshire. Fara echipamentul potrivit, este practic imposibil sa mentina fortificatiile orasului in fata atacurilor neintrerupte.",al={"cine este oslow","proprietarul oslow","uneltele lui foreman oslow"}},{q="Unde s-au scufundat uneltele in Lake Everstill?",a="Uneltele se afla intr-un cufar scufundat, langa epava barcii cu vasle distruse din Lake Everstill, printre bolovanii subacvatici aflati la sud de o tabara de murloci de pe tarm, usor de remarcat.",al={"locatia trusei de scule","unde este cufarul scufundat","unde s-a scufundat barca"}},{q="Ce primejdii pazesc cufarul scufundat?",a="Apele din jurul epavei sunt infestate de murloci ostili si bestii acvatice rapace, inclusiv de periculosi Lake Threshers, care pandesc in zonele mai adanci ale lacului.",al={"pericole langa lada de scule","dusmani de la Lake Everstill","ce pazeste uneltele lui Oslow"}}},fx={["543d5407"]={q="De ce are nevoie Foreman Oslow sa i se recupereze trusa de scule?",a="Lakeshire se afla sub asediu puternic, orasul fiind izolat si ducand o lipsa disperata de provizii esentiale. In calitate de maistru al orasului, Oslow are nevoie de echipamentul sau pentru a intretine si repara cladirile si apararile din Lakeshire. Cum caruta de livrare din Goldshire nu a putut traversa podul distrus, pierderea uneltelor de schimb in lac a blocat lucrarile esentiale de constructie, iar recuperarea lor a devenit vitala pentru supravietuirea orasului.",al={"de ce vrea Oslow","de ce are Oslow nevoie de unelte","de ce sa recuperez cutia de unelte a lui Oslow"}}},fp="15,215,18.576.0,49.284.0,22.215.0,43.182.0,36.175.0"}
P.entries["item:osric-s-crate"] = {n="Osric's Crate",s="La Sentinel Hill, Osric's Crate aduce armuri din Stormwind pentru People's Militia. Aparatorii infrunta Defias Brotherhood si gnoll jefuitori fara ajutorul armatei Stormwind.",h="La Sentinel Hill, Osric's Crate aduce armuri din Stormwind pentru People's Militia.",kw={"dungar longdrink","grifon","osric","lada lui osric","militia populara","quartermaster lewis","sentinel hill","westfall"},ang={["faction:Alliance"]="Pentru Alliance, fiecare transport de arme si armuri care ajunge la Sentinel Hill contribuie la apararea granitelor vestice ale regatului impotriva Defias Brotherhood."},sec={{t="Provizii pentru front",b="Westfall se confrunta cu Defias Brotherhood si cu gnoll-i jefuitori, in timp ce armata Stormwind lipseste. La Sentinel Hill, People's Militia trebuie sa se descurce fara sprijinul oficial al coroanei. Osric's Crate contine armuri nou fabricate, trimise din capitala catre Quartermaster Lewis, care sa le imparta luptatorilor voluntari."},{t="Reteaua de curieri inaripati",b="Gryphons transporta lada de la cuibul lui Dungar Longdrink, din Trade District al Stormwind, la Thor, la Sentinel Hill. Zborul evita drumurile primejdioase prin Elwynn Forest si de-a lungul granitei cu Westfall, unde banditii pot intinde ambuscade calatorilor. Gryphons ajuta la aprovizionarea garnizoanelor de frontiera pe timp de razboi."}},faq={{q="Ce se afla in Osric's Crate?",a="Osric's Crate contine armuri de protectie faurite in Stormwind. Quartermaster Lewis primeste livrarea si pregateste distribuirea ei printre luptatorii care apara Sentinel Hill.",al={"ce este in lada","continutul lazii lui Osric"}},{q="Cine este Osric?",a="Osric este un armurier din Stormwind care a pregatit transportul pentru People's Militia, care a pus stapanire pe Westfall.",al={"cine este osric","cine a trimis lada lui Osric"}},{q="Cine primeste lada?",a="Quartermaster Lewis primeste lada. El gestioneaza proviziile si echipamentul People's Militia de la Sentinel Hill, in Westfall.",al={"unde trebuie dusa lada","cui ii dau lada lui Osric","destinatarul lazii"}},{q="De ce este lada livrata cu un grifon?",a="Banditii si nelegiuitii fac periculoase drumurile prin Stormwind, Elwynn Forest si Westfall. Zborul cu gryphon de la Dungar Longdrink din Stormwind la Thor, in Sentinel Hill, transporta armura rapid si in siguranta.",al={"de ce sa transport lada pe calea aerului","de ce sa folosesc grifoni","zborul cu lada al lui Osric"}}},fx={["34d354cb"]={q="Ce este Osric's Crate?",a="Osric's Crate este un transport de armuri expediat din Stormwind City. Este pregatit pentru aparatorii stationati la Sentinel Hill, in Westfall, care duc o lipsa disperata de echipament in timp ce rezista atacurilor Defias Brotherhood.",al={"ce este lada lui osric","obiectul lada lui osric","ce se afla in lada lui osric"}},["091b5cbb"]={q="De unde provine Osric's Crate si cine a facut-o?",a="Lada provine din Stormwind City, unde Osric a pregatit-o si a trimis-o pentru a aproviziona People's Militia. Gryphon Master Dungar Longdrink ti-o incredinteaza ca s-o duci cu grifonul peste regat, pana in Westfall.",al={"cine a facut lada lui Osric","de unde provine lada lui Osric","originea lazilor lui Osric"}},["11fb3015"]={q="De ce ar dori cineva Osric's Crate?",a="Quartermaster Lewis si People's Militia de la Sentinel Hill au nevoie urgenta de armura din interior. Cum Westfall a fost abandonat de fortele regale si invadat de haiduci, fiecare bucata de echipament de protectie este esentiala pentru a-i mentine in viata pe aparatori.",al={"de ce sa livrez lada lui Osric","de ce vrea Lewis lada lui Osric","scopul lazii lui Osric"}}},fp="13,175,22.317.0,22.301.0,29.174.0,13.101.0,23.128.0,38.208.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Package of Empty Ooze Containers"}
P.entries["item:painted-gnoll-armband"] = {n="Painted Gnoll Armband",s="La Westbrook Garrison, Painted Gnoll Armbands dovedesc ca gnolls Riverpaw au fost ucisi. Benzile insemnate provin de la haitele care imping spre granita de vest a Elwynn Forest.",h="La Westbrook Garrison, Painted Gnoll Armbands dovedesc ca gnolls Riverpaw au fost ucisi.",kw={"recompensa","deputy rainer","elwynn forest","gnolli","bratara de brat pictata cu un gnoll","riverpaw","stone cairn lake","westbrook garrison"},ang={["faction:Alliance"]="Ca aventurier din Alliance, strangerea acestor bratari ajuta Westbrook Garrison sa apere granita vestica a Stormwind, in timp ce armata regulata a orasului este trimisa in alta parte."},sec={{t="Insemnele Riverpaw",b="Riverpaw pack isi marcheaza warriors si cercetasii cu banderole grosolane, pictate cu modele tribale rudimentare. Banderolele pictate sunt adunate de la gnolls Riverpaw de la granitele salbatice ale Elwynn Forest. Pentru aparatorii din Stormwind insa, ele reprezinta o amenintare teritoriala tot mai mare, care se apropie de Stone Cairn Lake si de padurile de la sud de Westbrook Garrison."},{t="Recompensa pentru Westbrook Garrison",b="Armata Stormwind este raspandita si solicitata pana la limita in tot regatul, lasand Westbrook Garrison in mare dificultate sa apere granita vestica. Deputy Rainer ofera o recompensa permanenta pentru uciderea alergatorilor si nevolnicilor Riverpaw. Bratarile lor pictate dovedesc uciderile, ajutandu-i pe deputy sa tina socoteala recompenselor si sa rareasca haitele din apropierea fermelor."}},faq={{q="De ce vrea Westbrook Garrison aceste bratari?",a="Deputy Rainer, de la Westbrook Garrison, strange brasardele drept dovada ca gnollii Riverpaw au fost ucisi. Soldatii garnizoanei nu pot tine piept singuri haitelor care se apropie, asa ca Stormwind le ofera recompense aventurierilor care aduc insemnele.",al={"de ce bratari","cine vrea bratari pictate de gnoll","recompensa lui Deputy Rainer"}},{q="Ce gnolli poarta aceste banderole pictate?",a="Gnollii Riverpaw poarta banderolele pictate. Riverpaw Outrunners si Riverpaw Runts impanzesc padurile de la sud de Westbrook Garrison si malurile din jurul Stone Cairn Lake.",al={"de unde pica bratarile","cine lasa bratara pictata de gnoll","ce gnolli au bratari"}},{q="De ce se afla gnollii Riverpaw in Elwynn Forest?",a="Riverpaw packs au inaintat spre est de-a lungul marginilor Elwynn Forest, ridicandu-si tabere in apropiere de Stone Cairn Lake si la marginea padurii. Cu prezenta militara a regatului diminuata, vaneaza, scormonesc dupa provizii si ameninta asezarile din apropiere.",al={"de ce sunt gnolii aici","invazia gnolilor in Elwynn","Riverpaw in Elwynn"}},{q="Ce semnificatie are vopseaua de pe banderole?",a="Vopseaua marcheaza trofeele luate de la Riverpaw gnolls si ajuta la dovedirea uciderilor in fata lui Deputy Rainer. Modelele nu au niciun rang sau inteles precizat.",al={"de ce sunt pictati","marcaje pe bratara gnoll"}}},fx={["586b453e"]={q="Ce este Painted Gnoll Armband?",a="Un Painted Gnoll Armband este o podoaba personala rudimentara, purtata de gnollii Riverpaw. Confectionate si pictate de haita, aceste bratari le marcheaza prezenta in tinuturile de granita din Elwynn Forest. Pentru Stormwind Army, ele sunt o dovada fizica incontestabila ca un gnoll jefuitor a fost ucis.",al={"ce este banderola pictata a gnolilor","povestea banderolei pictate a gnolilor","banderola gnolilor"}}},fp="21,171,22.284.0,29.328.0,48.232.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="Panther Cage Key",s="Panther Cage Key este o cheie mica de metal aflata in posesia lui Wizlo Bearingshiner, la Whitereach Post. Descuie o cusca intarita, in care este tinut captiv un pradator furios, printre ramasitele unei caravane atacate prin ambuscada in Thousand Needles.",h="Panther Cage Key este o cheie mica de metal aflata in posesia lui Wizlo Bearingshiner, la Whitereach Post.",kw={"centaur","dispozitiv hipercondensator","panther cage key","thousand needles","whitereach post","wizlo bearingshiner"},ang={["faction:Horde"]="Ajutorul dat lui Wizlo contribuie la securizarea drumurilor din Thousand Needles din jurul Whitereach Post, amenintate de urmarile volatile ale raidurilor centaurilor.",["profession:Engineering"]="Cheia descuie cusca in care se afla prototipul instabil al unui inventator, dovedind ca inventatorii excentrici isi ascund cele mai delicate mecanisme in cele mai primejdioase locuri cu putinta."},sec={{t="O incuietoare instabila",b="Cand o caravana de calatori a fost atacata si jefuita de centauri la nord de Whitereach Post, inventatorul goblin Wizlo Bearingshiner abia a scapat cu viata. Printre ramasitele carutelor si marfurile praduite, talharii au lasat neatinsa o singura comoara: o cusca solida in care se afla o pantera rara si fioroasa. La gatul pradatorului atarna o inventie pretioasa a lui Wizlo, un hipercapacitor. Nedorind sa se apropie de fiara care maraia, centaurul a pastrat distanta, lasand cheia lui Wizlo singura modalitate de a deschide usa si de a recupera dispozitivul."}},faq={{q="Cine furnizeaza Panther Cage Key?",a="Cheia le este inmanata aventurierilor de Wizlo Bearingshiner, un mester goblin care se odihneste la Whitereach Post, in nord-vestul Thousand Needles.",al={"cine ofera cheia panterei","unde gasesti Panther Cage Key","sursa cheii Panther Cage"}},{q="Ce descuie cheia?",a="Descuie o cusca de fier aflata printre carele distruse ale unei caravane in ruina, la nord de Whitereach Post. Inauntru se afla o pantera furioasa si primejdioasa.",al={"ce deschide cheia pantera","locatia custii panterei","unde se afla cusca"}},{q="De ce nu a jefuit centaurul cusca?",a="Centaurii au jefuit restul caravanei, dar pantera captiva din interior era atat de feroce si amenintatoare, incat pana si atacatorii au refuzat sa-i umble la cusca.",al={"de ce a plecat centaurul lasand pantera","de ce se teme centaurul de pantera"}},{q="Ce se afla in cusca in afara de bestie?",a="Gizmo-ul hipercondensator de pret al lui Wizlo este prins in jurul gatului panterei, astfel ca oricine spera sa recupereze inventia trebuie sa descuie cusca si sa infrunte pradatorul in mod direct.",al={"de ce sa deschizi cusca","ce se afla pe pantera"}}},fx={b335554a={q="De ce vrea Wizlo Bearingshiner inapoi Panther Cage Key?",a="Wizlo Bearingshiner iti incredinteaza cheia doar pentru a deschide cusca de la caravana sa distrusa si a ucide pantera feroce din interior. Bestia poarta la gat pretiosul sau dispozitiv cu hipercondensator. Vrea sa-i inapoiezi cheia impreuna cu inventia dupa ce-ti termini treaba, ca sa se asigure ca ramasitele caravanei si proprietatea sa periculoasa sunt pe deplin inventariate.",al={"de ce Panther Cage Key","de ce are Wizlo nevoie de cheie","de ce vrea Panther Cage Key"}}},fp="16,219,17.550.0,34.133.0,25.147.0,37.165.0,42.176.0"}
P.entries["item:parker-s-lunch"] = {n="Parker's Lunch",s="Parker's Lunch este o masa proaspat pregatita si impachetata de Darcy in Lakeshire. Destinata lui Guard Parker, aflat in patrulare, ofera o privire simpla asupra legaturilor de zi cu zi si a micilor bucurii ale aparatorilor din Redridge.",h="Parker's Lunch este o masa proaspat pregatita si impachetata de Darcy in Lakeshire.",kw={"un pranz gratuit","Darcy","stragerul Parker","Lakeshire","Parker's Lunch","Redridge"},ang={["faction:Alliance"]="In lipsa unor intariri trimise la timp de capitala, solidaritatea localnicilor si a putinilor garzi ramase este cea care mentine Lakeshire in functiune.",["profession:Cooking"]="O masa calda si satioasa este adesea singurul lucru care le da putere strajerilor de la frontiera sa indure orele lungi si fiarele ostile din salbaticie."},sec={{t="O masa pentru drum",b="In timp ce Redridge Mountains este lovit de atacurile gnollilor si orcilor Blackrock, micile bucurii ale vietii de zi cu zi dainuie. Darcy, chelnerita de la hanul din Lakeshire, pregateste acest pranz gustos pentru Guard Parker, care patruleaza drumul expus ce duce spre sud, catre Duskwood. Garnizoana din Redridge este suprasolicitata si izolata de ajutorul Stormwindului, asa ca fiecare gardian trebuie sa tina singur paza, mult timp. Livrarea acestui pachet nu doar hraneste o santinela, ci da nastere si unei idile timide si de durata intre cei doi locuitori ai orasului."}},faq={{q="Cine a pregatit Parker's Lunch?",a="Pranzul a fost pregatit de Darcy, o chelnerita de la hanul din Lakeshire. Ingrijorata pentru Guard Parker, aflat intr-o patrulare primejdioasa, ea se bazeaza pe aventurierii aflati in trecere ca sa i-l duca in siguranta.",al={"cine a facut Parker's Lunch","cine mi-a dat Parker's Lunch","pranzul lui Darcy din Redridge"}},{q="Unde il putem gasi pe Guard Parker?",a="Guard Parker patruleaza drumul principal de pamant care duce spre sud-vest, iesind din Lakeshire catre granita cu Duskwood. Merge de colo-colo pe acest traseu, pazind zona de gnollii ratacitori.",al={"locatia lui Guard Parker","unde este Guard Parker","gaseste-l pe Guard Parker"}},{q="Ce face gardianul Parker dupa ce isi primeste pranzul?",a="Parker este profund miscat de atentia lui Darcy. Recunoscator pentru mancarea calda primita in timpul patrulei sale dificile, cauta curand o cale de a-i intoarce bunatatea si cere ajutor pentru a-i trimite narcise proaspete de la botanist.",al={"continuarea pranzului lui Parker","Darcy si Parker","reactia lui Parker la pranz"}},{q="De ce nu livreaza Darcy pranzul chiar ea?",a="Drumurile din afara Lakeshire sunt pline de gnolli Redridge agresivi si invadatori Blackrock. Desi Guard Parker are pregatirea de lupta si armura necesare pentru a supravietui in patrulare, oamenii obisnuiti din oras, precum Darcy, nu-si pot asuma in siguranta riscul de a calatori singuri.",al={"de ce nu poate darcy sa-l aduca","de ce sa livrezi pranzul in redridge"}}},fx={["2351e721"]={q="Ce este Parker's Lunch?",a="Parker's Lunch este un pachet cu mancare pregatit de Darcy, ajutorul hangitei din Lakeshire. L-a pregatit anume pentru gardianul Parker, care petrece multe ore istovitoare patruland drumurile primejdioase de la sud de oras, spre Duskwood.",al={"ce contine pranzul lui Parker","obiectul de pranz al lui Parker"}},b73a829b={q="De ce trebuie sa i se aduca pranzul Garzii Parker?",a="Guard Parker este postat departe de siguranta relativa a orasului Lakeshire, pazind drumul de granita impotriva gnollilor ratacitori si a orcilor Blackrock. Neputand sa-si paraseasca postul si sa se intoarca la han, depinde de bunatatea localnicilor precum Darcy - si a calatorilor aflati in trecere - pentru a primi hrana in timpul serviciului.",al={"de ce sa duc pranzul lui Parker","de ce vrea Parker pranzul","de ce are nevoie gardianul Parker de pranz"}}},fp="14,201,19.526.0,28.194.0,32.182.0,52.210.1,44.241.0"}
P.entries["item:partially-filled-vessel"] = {n="Partially Filled Vessel"}
P.entries["item:pendant-of-shadow"] = {n="Pendant of Shadow",s="Pendant of Shadow este un talisman intunecat purtat de magul renegat Morganth, in varful Tower of Ilgalar, in Redridge Mountains. Dus la magul Theocritus, in Tower of Azora, acesta serveste drept dovada incontestabila ca vrajitorul renegat a fost eliminat inainte ca ambitiile sale sinistre sa dea roade.",h="Pendant of Shadow este un talisman intunecat purtat de magul renegat Morganth, in varful Tower of Ilgalar, in...",kw={"Morganth","Pendant of Shadow","Redridge","Scythe of Elune","Theocritus","Tower of Azora","Tower of Ilgalar"},ang={["class:Mage"]="Recuperarea talismanului intunecat la cererea lui Theocritus scoate in evidenta responsabilitatea continua a magilor de a-i supraveghea pe vrajitorii necinstiti si imprudenti care ameninta regatul.",["class:Warlock"]="Morganth ilustreaza pericolul de a atrage prea multa atentie din partea Tower of Azora in timp ce cauti artefacte volatile si interzise precum Scythe of Elune."},sec={{t="Semnul unui vrajitor intunecat",b="Pastrat de vrajitorul Warlock razvratit Morganth in locul sau de panda din Tower of Ilgalar, Pendant of Shadow este imbibat cu vrajitorie intunecata. Morganth incerca sa dezlege misterele Scythe of Elune, o relicva straveche, de o putere imensa si nestatornica. Temandu-se de prapadul pe care vrajitorul l-ar putea dezlantui asupra Redridge Mountains si regatului Stormwind, mage-ul Theocritus le-a cerut aventurierilor sa se infiltreze in Ilgalar, sa puna capat uneltirilor lui Morganth si sa-i smulga talismanul, ca dovada a mortii sale."}},faq={{q="Unde gasesc Pendant of Shadow?",a="Pandantivul este purtat de warlock-ul Morganth, care locuieste chiar in varful Tower of Ilgalar, in nord-estul Redridge Mountains.",al={"locatia Pendant of Shadow","unde se afla Pendant of Shadow","cum obtin Pendant of Shadow"}},{q="Cine vrea Pendant of Shadow?",a="Talismanul trebuie dus la vrajitorul Theocritus, care locuieste in Tower of Azora, aflata in estul Elwynn Forest.",al={"cine primeste Pendant of Shadow","preda Pendant of Shadow","pandantivul pentru Theocritus"}},{q="De ce are Theocritus nevoie de acest pandantiv?",a="Theocritus cere pandantivul drept dovada concreta ca Morganth a fost ucis si ca urmarirea periculoasei Scythe of Elune a luat sfarsit.",al={"de ce o vrea Theocritus","scopul Pendant of Shadow"}},{q="Ce amenintare reprezenta Morganth cu pandantivul?",a="Morganth era in cautarea Scythe of Elune, greu de gasit. Theocritus se temea ca, daca vrajitorul intunecat reusea sa puna mana pe artefact, avea sa dezlantuie o putere catastrofala asupra Redridge si a regatului din jur.",al={"ce facea morganth","povestea lui morganth"}}},fx={d0e37f9a={q="Ce este Pendant of Shadow?",a="Pendant of Shadow este un talisman intunecat purtat de warlock-ul renegat Morganth, in varful Tower of Ilgalar din Redridge Mountains. Legat nemijlocit de ambitiile sinistre si de artele intunecate ale lui Morganth, pandantivul ii serveste vrajitorului Theocritus drept dovada a infrangerii sale. Theocritus se teme de haosul pe care Morganth l-ar putea dezlantui asupra Stormwindului daca nu este oprit.",al={"ce este Pendant of Shadow","povestea lui Pendant of Shadow","informatii despre Pendant of Shadow"}}},fp="17,310,23.500.1,38.135.0,32.122.0,38.160.1,47.209.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Pendant of the Sea Lion",s="Pendant of the Sea Lion este un talisman druidic sacru, simbol al uniunii dintre agilitatea si rezistenta acvatica. Asamblat la Shrine of Remulos din Moonglade, dovedeste ca initiatul este pregatit sa-si stapaneasca forma acvatica.",h="Pendant of the Sea Lion este un talisman druidic sacru, simbol al uniunii dintre agilitatea si rezistenta...",kw={"forma acvatica","Dendrite Starblaze","Mathrengyl Bearwalker","Moonglade","Pendant of the Sea Lion","Remulos","Turak Runetotem"},ang={["class:Druid"]="Asamblarea acestui talisman marcheaza o etapa esentiala in pregatirea unui druid, deblocand abilitatea de a respira sub apa si de a inota fara efort, sub forma unui leu de mare.",["race:Tauren"]="Pentru Shu'halo care urmeaza calea Cenarion Circle, ducerea pandantivului inapoi la Turak Runetotem cinsteste atat stramosii, cat si invataturile din Moonglade."},sec={{t="Un simbol al adancurilor",b="Pentru a dobandi aspectul acvatic al leului de mare, un druid trebuie sa-si dovedeasca maiestria in fata celor mai mari primejdii ale apelor. Pandantivul se faureste recuperand doua jumatati diferite: una intruchipeaza agilitatea necesara pentru a trece pe langa pradatorii acvatici, iar cealalta ofera rezistenta necesara pentru a suporta scufundari indelungate. Duse la Shrine of Remulos din Moonglade, cele doua piese sunt unite intr-un singur intreg."},{t="Dovada maiestriei",b="Dupa ce este faurit, pandantivul complet este dus inaintea mentorilor varstnici, precum Turak Runetotem, pe inaltimile semete din Thunder Bluff, sau Mathrengyl Bearwalker, in Darnassus. Talismanul ofera o dovada de netagaduit a incercarilor initiatului sub indrumarea lui Dendrite Starblaze, ingaduindu-le batranilor sa-i impartaseasca tainele transformarii in forma acvatica."}},faq={{q="Care este scopul Pendant of the Sea Lion?",a="Este dovada ca un initiat Druid a trecut probele de agilitate si rezistenta acvatica, demonstrand ca este pregatit sa invete forma de transformare acvatica.",al={"la ce foloseste pendant of the sea lion","folosirea pandantivului leului de mare","de ce sa iei pendant of the sea lion"}},{q="Unde este asamblat pandantivul?",a="Cele doua jumatati - una simbolizand agilitatea, cealalta rezistenta - trebuie unite la Shrine of Remulos, aflat in refugiul sacru din Moonglade.",al={"cum se confectioneaza pandantivul cu leu de mare","unde se imbina jumatatile pandantivului"}},{q="Cui trebuie sa-i prezint pandantivul in Thunder Bluff?",a="Druizii Tauren ii ofera pandantivul terminat lui Turak Runetotem in Elder Rise din Thunder Bluff, pentru a-si incheia pregatirea.",al={"cine primeste pandantivul in Thunder Bluff","pandantivul pentru Turak Runetotem","predarea formei acvatice a Hoardei"}},{q="Pot castiga si elfii noptii acest pandantiv?",a="Da. Druizii night elf trec prin aceeasi incercare in Moonglade si ii duc pandantivul asamblat lui Mathrengyl Bearwalker, in Darnassus.",al={"pandantivul leului marin al Aliantei","pandantivul leului marin din Darnassus"}}},fx={["203d1c94"]={q="Ce este Pendant of the Sea Lion?",a="Pendant of the Sea Lion este un talisman druidic sacru care simbolizeaza stapanirea apei. Intruchipeaza agilitatea necesara pentru a evita pradatorii acvatici periculosi, precum si rezistenta profunda de care este nevoie pentru a ramane sub apa fara sa iesi la suprafata. Druizii poarta aceasta relicva ce reuneste cele doua calitati, ca dovada concreta ca inteleg echilibrul salbatic al naturii inainte de a adopta o infatisare acvatica.",al={"ce este Pendant of the Sea Lion","informatii despre pandantivul leului de mare","povestea pandantivului leului de mare"}},ad633d46={q="De unde provine Pendant of the Sea Lion si cine l-a facut?",a="Talismanul este faurit de druizi tineri care trec prin Trial of the Sea Lion. Se obtine recuperand doua piese separate - Half Pendant of Aquatic Agility si Half Pendant of Aquatic Endurance - din locurile de incercare si reunindu-le in fata Shrine of Remulos, in Moonglade, pentru a uni aspectele intr-o singura emblema sacra.",al={"cine a facut pendant of the sea lion","originea pandantivului leului de mare","cum este creat pendant of the sea lion"}},["384283bf"]={q="De ce si-ar dori cineva Pendant of the Sea Lion?",a="Mentorii druizi cer sa vada pandantivul terminat, ca dovada de netagaduit a pregatirii tale. In Thunder Bluff, Turak Runetotem are nevoie de medalion pentru a verifica daca ai trecut incercarile din Moonglade, inainte de a-ti impartasi secretele formei acvatice. Dendrite Starblaze din Moonglade examineaza si el relicva asamblata, pentru a confirma incheierea incercarii.",al={"de ce sa vrei Pendant of the Sea Lion","cine vrea pandantivul leului de mare","de ce sa arati Pendant of the Sea Lion"}}},fp="23,237,19.408.0,16.338.0,51.166.0,31.148.0,49.125.0,39.138.0"}
P.entries["item:perenolde-tiara"] = {n="Perenolde Tiara",s="In ruinele din Alterac a reaparut o mostenire de familie a casei Perenolde, impodobita cu smaralde. Mesterii Dwarven din Ironforge au facut-o, iar acum colectionarii din Stormwind o cauta.",h="In ruinele din Alterac a reaparut o mostenire de familie a casei Perenolde, impodobita cu smaralde.",kw={"Alterac","smaralde","Grel'borg","Ironforge","avar","Perenolde","Remington","Ridgewell","diadema"},ang={["faction:Alliance"]="Ca membru al Alliance, te confrunti cu o amara amintire a Casei Perenolde, a carei tradare din timpul Second War aproape ca a distrus Alliance of Lordaeron initiala.",["race:Dwarf"]="Ca Dwarf, poti vedea arta prelucrarii pietrelor pretioase din Ironforge in smaraldele pe care bijutierii sai maestri le taie si le monteaza pentru familia regala Human din nord."},sec={{t="O relicva a unui regat ruinat",b="Familia Perenolde a condus Alterac inainte ca regatul sa cada in timpul Second War. Printre comorile sale se numara o tiara delicata, lucrata de bijutieri maestri din Ironforge si impodobita cu smaralde stralucitoare. Dupa ce tradarea regelui Aiden Perenolde a adus ruina asupra Alterac, tiara a disparut in mijlocul pustiirii crestelor inalte."},{t="Premiul zgarcitului",b="Grel'borg the Miser, un ogre mage, a dezgropat tiara in timp ce cauta bogatii abandonate printre ruinele din Alterac. Vestea despre relicva supravietuitoare a ajuns la Count Remington Ridgewell, un nobil bogat din Stormwind care colectioneaza relicve celebre pentru muzeul familiei sale. Acum, countul vrea sa-i ia tiara ogre-ului."}},faq={{q="Ce este Perenolde Tiara?",a="Perenolde Tiara este o mostenire de familie a casei regale Perenolde din Alterac. Bijutierii Dwarven din Ironforge au faurit-o si au impodobit-o cu smaralde, inainte ca aceasta sa se piarda odata cu prabusirea regatului.",al={"povestea perenolde tiara","ce este tiara asta","tiara alterac"}},{q="Cine detine acum tiara?",a="Grel'borg the Miser, un ogre mage, a gasit tiara printre ruinele acoperite de zapada din Alterac. O pazeste in timp ce cauta mai multe comori prin regatul ruinat.",al={"unde este tiara","cine lasa tiara","tiara lui Grelborg"}},{q="De ce il vrea Count Remington Ridgewell?",a="Count Remington Ridgewell colectioneaza antichitati istorice si de mare prestigiu pentru muzeul familiei sale din Stormwind. Isi doreste tiara drept piesa de rezistenta, provenita dintr-un regat al oamenilor cazut.",al={"cine vrea tiara","de ce o vrea Remington","motivul lui Remington Ridgewell"}},{q="Cine au fost Perenolde?",a="Perenolde au condus regatul Alterac. In timpul Second War, King Aiden Perenolde a tradat Alliance in favoarea Orcish Horde, iar tinutul sau a cazut in ruina.",al={"familia Perenolde","Casa Perenolde","conducatorii din Alterac"}}},fx={da959daa={q="De unde provine Perenolde Tiara si cine a facut-o?",a="Tiara provine din regatul nordic ruinat Alterac, unde era o pretioasa mostenire de familie a casei regale Perenolde. Se spune ca a fost lucrata de maestri bijutieri pitici din Ironforge, nu de mestesugari oameni, care au impodobit piesa ornamentata cu cei mai fini smaralde.",al={"cine a facut Perenolde Tiara","originea Perenolde Tiara","unde a fost faurita tiara"}}},fp="15,178,27.319.0,17.305.0,28.187.0,28.152.0,43.172.0,24.161.0"}
