P.entries["item:plainstrider-feather"] = {n="Plainstrider Feather",s="Adunate de la pasarile iuti care strabat campiile din Mulgore, penele Plainstrider Feathers sunt materiale esentiale, stranse de tinerii vanatori de pe Red Cloud Mesa. Taurenii din Camp Narache le folosesc mai ales la confectionarea hainelor si a podoabelor tribale, cinstind totodata fapturile care asigura cele necesare satului.",h="Adunate de la pasarile iuti care strabat campiile din Mulgore, penele Plainstrider Feathers sunt materiale...",kw={"Camp Narache","pana","Grull Hawkwind","Mulgore","plainstrider","Red Cloud Mesa","The Hunt Begins"},ang={["class:Hunter"]="Pandirea sprintenilor alergatori de campie prin Red Cloud Mesa ii ofera unui initiat prima incercare de rabdare, urmarire si respect fata de prada.",["race:Tauren"]="Pentru un tauren tanar, recoltarea penelor de la un alergator de campie este o prima lectie esentiala despre a nu considera niciodata de la sine inteles nimic din ceea ce ofera creaturile Earth Mother si despre folosirea fiecarei parti a prazii pentru hrana si imbracaminte."},sec={{t="Prima ofranda a unui vanator",b="Pe Red Cloud Mesa, tinerii tauren invata de timpuriu ca supravietuirea depinde de iscusinta la urmarit si la vanatoare. Plainstriderii alearga nestingheriti pe platoul acoperit de iarba, oferind atat hrana, cat si materiale practice. Smulgerea penelor lor rezistente ii permite taberei sa confectioneze vesminte si echipament traditionale. Sa-i oferi aceste pene impreuna cu carne proaspata lui Grull Hawkwind demonstreaza respect fata de nevoile tribului si constituie prima incercare in drumul spre recunoasterea de catre Chief Hawkwind si primirea in Thunder Bluff."}},faq={{q="La ce se folosesc Plainstrider Feathers?",a="Taurenii din Camp Narache le folosesc in principal la confectionarea hainelor si obiectelor ceremoniale. Grull Hawkwind le aduna de la vanatorii incepatori pentru a reface proviziile tribului.",al={"scopul penei","la ce foloseste pana de plainstrider","de ce colectam pene"}},{q="Cine aduna Plainstrider Feathers pe Red Cloud Mesa?",a="Grull Hawkwind le cere in numele asezarii Camp Narache, pentru a reface proviziile satului si a verifica daca tinerii vanatori au disciplina necesara pentru a asigura hrana tribului.",al={"cine vrea pene","cine are nevoie de pene","pene pentru Grull Hawkwind"}},{q="Unde pot fi gasiti plainstrider?",a="Ei ratacesc prin pajistile deschise de pe Red Cloud Mesa si prin campiile domoale din Mulgore.",al={"unde gasesti plainstriders","locatia unui plainstrider","loc de farmat pene"}},{q="De ce are Grull Hawkwind nevoie de aceste pene pentru ritualurile tribale?",a="Vanatoarea este o piatra de temelie a culturii tauren, practicata atat pentru supravietuire, cat si pentru placere. Intoarcerea cu carne si pene dovedeste in fata lui Chief Hawkwind ca un novice poate sustine tribul inainte de a-si continua drumul spre Thunder Bluff.",al={"povestea Hunt Begins","vanatoarea de initiere Tauren","de ce vanam alergatorii de campie"}}},fx={f2ff74a3={q="Ce este Plainstrider Feather?",a="Plainstrider Feather este penaj adunat de la pasarile mari, nezburatoare, care cutreiera pasunile din Mulgore. Taurenii din Red Cloud Mesa folosesc fiecare resursa a pamantului cu profund respect, iar aceste pene rezistente si colorate sunt materiale practice pentru confectionarea hainelor de zi cu zi si a podoabelor traditionale.",al={"ce este o pana de plainstrider","informatii despre pana de plainstrider","pene de plainstrider"}},["8bb68bd8"]={q="De unde provin Plainstrider Feathers?",a="Aceste pene cresc in mod natural si sunt culese direct de la plainstriderii salbatici care cutreiera Red Cloud Mesa si campiile intinse din Mulgore. Nu sunt confectionate de maini muritoare, ci adunate de vanatori dupa o vanatoare reusita in prerie.",al={"sursa penelor de Plainstrider","de unde iei pene de Plainstrider","cine a facut pana de Plainstrider"}}},fp="20,300,25.496.0,40.164.0,52.172.0,33.97.0,64.234.0"}
P.entries["item:plainstrider-kidney"] = {n="Plainstrider Kidney"}
P.entries["item:plainstrider-meat"] = {n="Plainstrider Meat",s="Plainstrider Meat este vanatul proaspat obtinut de la pasarile nezburatoare care ratacesc prin campiile din Mulgore. Pentru tinerii tauren care ajung la maturitate pe Red Cloud Mesa, strangerea acestei hrane inseamna atat provizii esentiale pentru iarna, cat si un ritual important de trecere.",h="Plainstrider Meat este vanatul proaspat obtinut de la pasarile nezburatoare care ratacesc prin campiile din...",kw={"Camp Narache","Chief Hawkwind","Grull Hawkwind","Mulgore","plainstrider","carne de plainstrider","Red Cloud Mesa","The Hunt Begins"},ang={["class:Hunter"]="Plainstriderul iute le ofera vanatorilor in devenire o prima incercare de urmarire si tragere la tinta prin campiile deschise din Mulgore.",["race:Tauren"]="Pentru tinerii tauren care pasesc pe Red Cloud Mesa, vanatoarea de plainstriders este primul pas practic spre a castiga respectul lui Chief Hawkwind si dreptul de a intra in Thunder Bluff."},sec={{t="Hrana pentru podis",b="Viata taurenilor este legata inseparabil de pamant, imbinand respectul pentru natura cu necesitatea practica de a supravietui. Asezarea Camp Narache de pe Red Cloud Mesa depinde in mare masura de vanatul din pajistile dimprejur. Carnea de plainstrider asigura provizii esentiale pentru sat cand rezervele se imputineaza, iar penajul acestor pasari este folosit la haine si podoabe ceremoniale."},{t="Incercarea unui Hunter tanar",b="Vanatoarea de strideri de campie este una dintre primele incercari date tinerilor care vor sa castige respectul tribului. Grull Hawkwind ii indruma pe aspirantii la rangul de vanator sa urmareasca pasarile sprintene de-a lungul platoului si sa adune carne si pene, dovedindu-si abilitatile de urmarire si independenta inainte de a se infatisa in fata tatalui sau, Chief Hawkwind."}},faq={{q="La ce foloseste Plainstrider Meat?",a="Vanatorii tineri aduna Plainstrider Meat in Red Cloud Mesa pentru a reface proviziile de hrana epuizate din Camp Narache, indeplinind o sarcina esentiala pentru Grull Hawkwind.",al={"de ce carne de plainstrider","misiune cu carne de plainstrider","ce fac cu carnea de plainstrider"}},{q="Cine cere aceasta carne?",a="Grull Hawkwind, fiul lui Chief Hawkwind, le cere initiatilor sa vaneze alergatorii de campie de pe platou pentru a reface proviziile de hrana ale tribului si a-si dovedi vrednicia de sustinatori ai acestuia.",al={"cine are nevoie de carne de strider de campie","carne pentru Grull Hawkwind"}},{q="Unde poate fi gasita Plainstrider Meat?",a="Este recoltata de la plainstriderii nezburatori care cutreiera pajistile din Mulgore, indeosebi dealurile domoale din Red Cloud Mesa.",al={"unde gasesti carne de plainstrider","locatiile plainstriderilor","vaneaza plainstrideri pentru carne"}},{q="De ce este considerata importanta vanatoarea de plainstrideri pentru Tauren?",a="Taurenii vaneaza atat din necesitate practica, cat si ca disciplina spirituala. Aducerea vanatului in tabara dovedeste respect fata de Earth Mother, independenta si capacitatea de a sustine tribul.",al={"cultura vanatorii la tauren","de ce sunt vanati plainstriders"}}},fx={f404715e={q="Ce este Plainstrider Meat?",a="Plainstrider Meat este carne proaspata de vanat, luata de la pasarile nezburatoare care cutreiera campiile din Mulgore. Pentru taureni din Red Cloud Mesa, este un aliment de baza vital, obtinut prin vanatori traditionale care sustin asezarea si onoreaza legatura dintre vanator si prada.",al={"informatii despre carnea de plainstrider","ce este carnea de plainstrider","povestea carnii de plainstrider"}},["00c8b7f8"]={q="De unde provine Plainstrider Meat?",a="Plainstrider Meat provine de la pasaretul salbatic din Mulgore. Vanatorii tineri il iau direct de la fiarele care cutreiera Red Cloud Mesa, in timpul primelor lor ritualuri de vanatoare pentru trib.",al={"de unde provine carnea de Plainstrider","originea carnii de Plainstrider","cum obtii carne de Plainstrider"}},f1043112={q="De ce se cauta Plainstrider Meat in Camp Narache?",a="Proviziile de hrana din Camp Narache s-au imputinat, iar tribul se bazeaza pe vanatoarea iscusita pentru a-si reface rezervele. Grull Hawkwind le cere vanatorilor tineri sa adune Plainstrider Meat, ca sa hraneasca satul si sa-si dovedeasca iscusinta in fata lui Chief Hawkwind.",al={"de ce am nevoie de carne de plainstrider","scopul carnii de plainstrider","de ce sa aduni carne de plainstrider"}}},fp="17,257,23.401.0,22.311.0,35.162.0,23.166.0,37.138.0,64.202.0"}
P.entries["item:plainstrider-scale"] = {n="Plainstrider Scale",s="O solza rezistenta recoltata de la tallstriderii care cutreiera campiile intinse din Mulgore. Este o componenta esentiala a unui leac traditional pregatit de Maur Raincaller pentru a combate o infectie virulenta.",h="O solza rezistenta recoltata de la tallstriderii care cutreiera campiile intinse din Mulgore.",kw={"bloodhoof village","maur raincaller","mazzranache","mulgore","plainstrider","leac","solzi","tallstrider"},ang={["race:Tauren"]="Adunarea leacurilor din tinut reflecta abilitatile traditionale de supravietuire predate tinerilor vanatori din Mulgore, care folosesc fiecare parte a faunei salbatice din campii pentru a-si sustine tribul."},sec={{t="Un ingredient rar",b="Desi striders sunt cunoscuti mai ales pentru penele lor moi si carnea slaba, picioarele lor puternice sunt acoperite cu solzi tari, protectori. Acestia rezista terenului aspru cu tufisuri dese si ghearelor pradatorilor. Gasirea unui solz intreg, potrivit pentru leacuri, cere rabdare, fiindca numai anumiti striders din Mulgore au solzi suficient de tari pentru a fi macinati si pregatiti dupa leacuri populare."},{t="Leac pentru o muscatura otravitoare",b="Cand Maur Raincaller din Bloodhoof Village s-a intalnit cu Mazzranache, un alergator legendar cunoscut pentru ochii sai rosii, demonici, si muscatura veninoasa, a suferit o rana grava la umar. Cuprins de o febra deliranta, Maur are nevoie de o Plainstrider Scale, alaturi de o inima de lup, un femur de pumac si o pipota de swoop, pentru a curata infectia care se raspandeste inainte ca aceasta sa-i fie fatala."}},faq={{q="La ce se foloseste Plainstrider Scale?",a="Este un ingredient medicinal esential, adunat pentru Maur Raincaller in Bloodhoof Village. Amestecat cu parti de la alti pradatori din Mulgore, ingredientul este prefacut intr-un leac pentru o rana infectata si veninoasa, provocata de striderul rebel Mazzranache.",al={"la ce foloseste solzul de plainstrider","utilizarea solzilor de plainstrider","de ce este nevoie de solzi de plainstrider"}},{q="Unde gasesti Plainstrider Scale?",a="Solzii se obtin vanand plainstriderii salbatici care strabat pajistile intinse din Mulgore.",al={"unde gasesti solz de plainstrider","cum obtii solz de plainstrider","locatia solzului de plainstrider"}},{q="De ce este Maur Raincaller infectat?",a="In timp ce strabatea campiile, Maur a fost prins intr-o ambuscada si muscat de umar de Mazzranache, un tallstrider inspaimantator, cunoscut pentru muscatura sa veninoasa si ochii purpurii. Muscatura i-a provocat o febra deliranta, din ce in ce mai grava, pe care odihna obisnuita nu o poate vindeca.",al={"cum s-a imbolnavit maur","de ce este bolnav maur","muscatura lui mazzranache"}},{q="Ce alte ingrediente ii mai trebuie lui Maur pentru remediul sau?",a="Pe langa Plainstrider Scale, Maur are nevoie de un Prairie Wolf Heart, un Flatland Cougar Femur si un Swoop Gizzard pentru a incheia amestecul medicinal.",al={"ingredientele lui Maur Raincaller","leacul pentru Mazzranache","obiectele misiunii Mazzranache"}}},fx={["95a4c3dd"]={q="Ce este Plainstrider Scale?",a="Este o solza rezistenta, speciala, jupuita de pe struti inalti care cutreiera pajistile batute de vant din Mulgore. Desi pasarile si strutii sunt cunoscuti mai ales pentru penajul si ciocurile lor ascutite, picioarele lor viguroase sunt acoperite de solzi aspri si intariti, capabili sa reziste campiilor neiertatoare. Samanilor si botanistilor le sunt de folos acesti solzi rari si densi, datorita proprietatilor lor protectoare, atunci cand prepara alifii si leacuri speciale.",al={"ce este o solza de plainstrider","solza de plainstrider","solzi de plainstrider"}},d7ded3c8={q="De unde provine o Plainstrider Scale?",a="Este o parte naturala de animal, luata direct de la stolocerii salbatici care cutreiera Mulgore. Nimeni nu o mestereste; vanatorii o recolteaza din picioarele stolocerilor cazuti de pe campii, strangand numai solzii cei mai rezistenti pentru preparate medicinale.",al={"sursa solzilor de plainstrider","de unde provin solzii de plainstrider","cine a facut solzii de plainstrider"}}},fp="18,201,17.395.0,28.371.1,40.252.0,39.107.0,32.247.0,53.149.0"}
P.entries["item:plainstrider-talon"] = {n="Plainstrider Talon",s="Plainstrider Talon este o gheara ascutita, recoltata de la plainstriderii mari, nezburatori, bastinasi din Mulgore. Samanii taureni folosesc aceste gheare, alaturi de alti reactivi naturali, pentru a fauri totemuri sacre de purificare cand sursele de apa ale tinutului sunt corupte.",h="Plainstrider Talon este o gheara ascutita, recoltata de la plainstriderii mari, nezburatori, bastinasi din...",kw={"bloodhoof village","totem de purificare","mulgore","mull thunderhorn","plainstrider","plainstrider talon","poison water","winterhoof water well"},ang={["class:Shaman"]="Folosirea unor parti din trupul fiarelor, precum ghearele, pentru a fauri totemuri purificatoare este un exemplu de practica samanica traditionala tauren, care atrage puterea direct din spiritele native ale pamantului.",["race:Tauren"]="Cinstirea sacrificiului vietuitoarelor salbatice din Mulgore este esentiala pentru vanatoarea taurenilor, asigurandu-se astfel ca fiecare fiara ucisa ajuta la vindecarea Earth Mother atunci cand goblinii ii exploateaza tinuturile."},sec={{t="Legaturile campiilor",b="Plainstriderii mari, incapabili sa zboare, cutreiera pajistile deschise din Mulgore, bazandu-se pe picioarele puternice si ghearele ascutite pentru a se apara de pradatori si a scurma pamantul dur al preeriei dupa hrana. Pentru taurenii din Bloodhoof Village, fiecare parte a unei fiare vanate poarta o insemnatate spirituala. Cand aventurierii goblini au pangarit izvoare sacre precum Winterhoof Water Well, samanul Mull Thunderhorn a cerut gheare de plainstrider, alaturi de labe de lup de preerie. In mestesugul ritualic tauren, strangerea de ingrediente de la pradatorii si vietuitoarele locale le permite samanilor sa canalizeze esenta spirituala a tinutului in totemuri capabile sa curete otrava nenaturala."}},faq={{q="Ce creaturi lasa in urma Plainstrider Talon?",a="Ghearele alergatorilor de campie sunt recoltate de la alergatorii de campie adulti, cei batrani si renumitul alergator Mazzranache, de pe pajistile din Mulgore.",al={"cine lasa gheara de plainstrider","de unde obtii gheare de plainstrider","sursa ghearei de plainstrider"}},{q="La ce se folosesc Plainstrider Talons?",a="Mull Thunderhorn din Bloodhoof Village are nevoie de gheare de plainstrider si labe de lup de prerie pentru a confectiona un totem purificator, folosit la curatarea Winterhoof Water Well de coruptie.",al={"la ce foloseste gheara de plainstrider","de ce am nevoie de gheare","misiunea ghearei de plainstrider"}},{q="De ce are Mull Thunderhorn nevoie de parti de animale pentru a curata apa?",a="Shamanismul tauren se bazeaza pe armonia cu spiritele naturii din Mulgore. Legand elemente ale faunei locale de totemul ritualic, shamanul cheama puterea bruta a pamantului insusi pentru a respinge poluantii straini adusi de goblinii Venture Company.",al={"de ce au animalele labe si gheare","ritual de purificare Shaman, gheare"}},{q="Cine a otravit fantanile cu apa din Mulgore?",a="Goblin-ii - mai exact agentii Venture Company care opereaza in Mulgore - si acolitii lor au pangarit fantanile tribale sacre, tulburand mediul local si amenintand triburile Tauren.",al={"cine a otravit fantanile","cine a otravit apa din Mulgore","vinovatul pentru Poison Water"}}},fx={fdecb439={q="Ce este Plainstrider Talon?",a="O gheara Plainstrider Talon este gheara ascutita recoltata de la plainstriderii mari, incapabili de zbor, care ratacesc prin Mulgore. Desi aceste pasari sprintene isi folosesc ghearele in mod firesc pentru aparare si pentru a scurma dupa hrana prin campii, ele poarta si o legatura innascuta cu lumea naturala. Pentru taureni, astfel de materiale reprezinta puterea pamantului si pot fi canalizate prin ritualuri samanice.",al={"ce este gheara de plainstrider","povestea ghearelor de plainstrider","ghearele plainstriderului"}},["07c33870"]={q="De unde provin Plainstrider Talons?",a="Aceste gheare provin de la plainstriderii maturi care ratacesc prin campiile deschise din Mulgore, la sud-vest de Bloodhoof Village. Vanatorii le aduna de la plainstrideri adulti si batrani sau chiar de la fiare rare precum Mazzranache, ca ofrande din belsugul pamantului.",al={"sursa ghearei de plainstrider","de unde iau gheare de plainstrider","originea ghearei de plainstrider"}},["826885d3"]={q="De ce doreste Mull Thunderhorn Plainstrider Talons?",a="Mull Thunderhorn din Bloodhoof Village are nevoie de aceste gheare pentru a crea un totem purificator pentru Winterhoof Water Well. Goblinii si acolitii lor din Venture Company au pangarit apa sacra, iar Mull trebuie sa invoce esenta primordiala a bestiilor native din Mulgore pentru a contracara otrava si a reda fantanii puritatea.",al={"de ce vrea Mull gheare","de ce este nevoie de gheara de plainstrider","scopul ghearei de plainstrider"}}},fp="18,249,19.620.0,41.152.0,38.177.0,63.258.0,40.205.0"}
P.entries["item:podrig-s-order"] = {n="Podrig's Order",s="Podrig's Order este o cerere militara scrisa, redactata de Deathguard Podrig la Sepulcher. Aceasta solicita o noua transa de Arme de la negustorul din Undercity, Gordon Wendham, pentru ca garnizoana Forsaken din Silverpine sa fie echipata corespunzator.",h="Podrig's Order este o cerere militara scrisa, redactata de Deathguard Podrig la Sepulcher.",kw={"Gordon Wendham","Hadrec","Karos Razok","Podrig","ordinul lui Podrig","Sepulcher","Silverpine"},ang={["profession:Blacksmithing"]="Armele faurite sunt esentiale pe linia frontului, unde luptele neintrerupte epuizeaza constant proviziile garnizoanei.",["race:Undead"]="Rechizitia scoate in evidenta legatura logistica vitala dintre Undercity si avanposturi indepartate precum Sepulcher, asigurandu-se ca soldatii Dark Lady sunt inarmati corespunzator impotriva lui Scourge."},sec={{t="Inarmarea din Sepulcher",b="Silverpine Forest este o frontiera primejdioasa pentru Forsaken, prinsa intre Scourge care inainteaza, bestii salbatice si alte amenintari ascunse. Dupa inventarierea echipamentului facuta de Deathguard Podrig la ordinul lui Executor Hadrec, s-a constatat ca proviziile din Sepulcher sunt in mare parte suficiente, dar ca armele de schimb sunt periculos de putine. Aceasta comunicare oficiala descrie lamele si armele necesare pentru a sustine Deathguards care tin avanpostul."},{t="Expediere prin ingrijitorul de lilieci",b="Deoarece armele nu pot fi forjate cu usurinta in criptele umede din Silverpine, cererea este trimisa lui Gordon Wendham, un negustor de arme din aglomeratul Trade Quarter of the Undercity. Pentru a grabi comanda, curierii duc documentul direct la maestrul de lilieci Karos Razok, folosind rutele aeriene ale Forsaken pentru a asigura reaprovizionarea rapida din capitala."}},faq={{q="Ce scrie in Podrig's Order?",a="Este o cerere oficiala de aprovizionare care enumera armele de inlocuire necesare garzilor mortii stationate la Sepulcher dupa pierderile obisnuite suferite pe teren.",al={"ce scrie in ordin","continutul ordinului lui Podrig","detalii despre ordinul lui Podrig"}},{q="Cine a scris Podrig's Order?",a="A fost redactat de Deathguard Podrig, la instructiunile Executor Hadrec, in urma verificarii inventarului armurieriei din Sepulcher.",al={"cine a scris-o","autorul ordinului lui podrig"}},{q="Cine primeste ordinul?",a="Este destinat lui Gordon Wendham, un negustor de arme care isi desfasoara activitatea in Trade Quarter of the Undercity.",al={"cine primeste ordinul","unde ajunge ordinul lui Podrig","destinatarul ordinului lui Podrig"}},{q="De ce are Sepulcher nevoie de arme noi?",a="Infruntarile neintrerupte cu Scourge si alte forte ostile din Silverpine Forest provoaca deseori pierderea ori avarierea echipamentului Deathguard-ilor care apara tinutul.",al={"de ce sunt necesare armele","lipsa armelor din Sepulcher"}}},fx={["92a3bbc0"]={q="Ce este Podrig's Order?",a="Podrig's Order este un document oficial de rechizitie al Forsaken, redactat pentru a asigura arme noi pentru avanpostul din Sepulcher. Scrisa de Podrig in numele lui Executor Hadrec, scrisoarea insira armele de inlocuire de care au nevoie Deathguards din garnizoana pentru a supravietui confruntarilor neintrerupte cu Scourge si cu alte orori ce pandesc in Silverpine Forest.",al={"ce este comanda lui Podrig","obiectul comanda lui Podrig","rechizitia lui Podrig"}},["6fc9fe58"]={q="De ce are nevoie Gordon Wendham de Podrig's Order?",a="In calitate de negustor de Arme din Trade Quarter of the Undercity, Gordon Wendham are nevoie de rechizitia oficiala pentru a verifica si a onora cererea de provizii a garnizoanei. Fara acest manifest verificat, Sepulcher nu poate primi transportul necesar de arme si echipament pentru reaprovizionarea gardienilor mortii de pe linia frontului.",al={"de ce vrea gordon wendham ordinul","de ce trebuie dus ordinul lui podrig la undercity","de ce este necesar ordinul lui podrig"}}},fp="14,228,20.431.0,24.366.0,34.139.0,25.133.0,23.106.0,40.164.0"}
P.entries["item:pork-belly-pie"] = {n="Pork Belly Pie",s="In Elwynn Forest, Billy Maclure vrea o placinta de la ferma Stonefield inainte sa vorbeasca despre un colier disparut. Auntie Bernice Stonefield o coace, in ciuda vrajbei dintre familiile lor.",h="In Elwynn Forest, Billy Maclure vrea o placinta de la ferma Stonefield inainte sa vorbeasca despre un colier...",kw={"auntie bernice stonefield","inapoi la billy","billy maclure","elwynn forest","maclure","placinta cu burta de porc","stonefield"},ang={["faction:Alliance"]="Pentru calatorii din Alliance care ajuta in zonele rurale din Elwynn, livrarea placintelor scoate la iveala vechile certuri din inima agricola a Stormwind.",["profession:Cooking"]="Placinta de casa a lui Auntie Bernice are influenta chiar si in vrajba dintre familii, desi reteta ei ramane secreta."},sec={{t="O mita intre fermele rivale",b="Familiile Stonefield si Maclure se cearta de ani intregi pentru pamant si mandrie, in Elwynn Forest. Tanarul Billy Maclure are o slabiciune pentru placinta cu fleica de porc pregatita de Auntie Bernice. Cand dispare un colier valoros ce apartine Stonefield family, Billy refuza sa spuna ce stie pana cand un aventurier ii aduce o felie calda. Bernice coace placinta fara tragere de inima, dorindu-si ca baiatul lacom sa se inece cu ea."}},faq={{q="La ce foloseste Pork Belly Pie?",a="Auntie Bernice Stonefield pregateste placinta pentru a-l face pe tanarul Billy Maclure sa vorbeasca. El stie ceva despre colierul disparut al Stonefield family, dar refuza sa spuna ceva pana cand ea nu ii gateste ceva.",al={"la ce foloseste placinta","de ce placinta cu burta de porc","ce fac cu placinta"}},{q="Cine coace Pork Belly Pie?",a="Auntie Bernice Stonefield coace placinta la Stonefield Farm. Il dispretuieste pe Billy Maclure si familia lui, dar o pregateste ca sa-si recupereze colierul de familie pierdut.",al={"cine a facut placinta","brutarul de placinte","placinta lui Granny Stonefield"}},{q="De ce vrea Billy Maclure mancare de la o familie rivala?",a="Billy Maclure vrea mancarea gatita de Auntie Bernice, in ciuda vrajbei dintre Stonefields si Maclures. Isi doreste placinta cu burta de porc mai mult decat ii pasa sa pastreze ranchiuna familiei sale.",al={"de ce vrea Billy placinta","de ce vrea Maclure mancare de la Stonefield"}},{q="Pot jucatorii sa manance Pork Belly Pie?",a="Nu. Placinta este destinata lui Billy Maclure si nu poate fi mancata pentru a reface sanatatea sau mana.",al={"pot sa-l mananc","placinta cu piept de porc este comestibila"}}},fx={["6505ed9f"]={q="Ce este Pork Belly Pie?",a="Este o placinta savuroasa cu carne de porc, coapta cu piept de porc, renumita pentru gustul ei delicios, in ciuda vrajbei amare dintre cele doua familii de fermieri din sudul Elwynn Forest. Pregatita proaspat in bucataria Stonefield, este o ispita menita sa-l faca pe Billy, baiatul Maclure, sa dea informatii; el sustine ca memoria ii functioneaza doar cu stomacul plin.",al={"ce este placinta cu burta de porc","povestea placintei cu burta de porc","despre placinta cu burta de porc"}}},fp="14,187,29.386.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="Powdered Azurite"}
P.entries["item:powers-of-the-void"] = {n="Powers of the Void",s="Un tom furat ii atrage atentia Drusillei La Salle in Northshire. Powers of the Void era pastrat intr-o aripa restrictionata a bibliotecii din Northshire Abbey, pana cand un novice l-a luat cu el, dezertand la Defias Brotherhood. Drusilla vrea sa-l recupereze pentru propriile studii asupra magiei intunecate.",h="Un tom furat ii atrage atentia Drusillei La Salle in Northshire.",kw={"defias brotherhood","drusilla la salle","diavol","khadgar","northshire abbey","powers of the void","stolen books","the stolen tome","warlock"},ang={["class:Warlock"]="Ca Warlock, recuperarea tomului furat iti pune la incercare vointa de a merita sa inveti sa invoci un imp.",["race:Human"]="Ca human, poti vedea ca Ordinul Sfant din Northshire pastreaza inregistrari magice periculoase alaturi de texte clericale, ascunse privirii novicilor."},sec={{t="Un text interzis din Northshire",b="Powers of the Void era pastrata in spatele unor rafturi pazite din biblioteca Northshire Abbey. Arhivele abatiei adapostesc scripturi sfinte si documente clericale, precum si lucrari savante despre energiile umbrei si Netherului. Se presupune ca tomul a fost scris de arhimagul Khadgar. Din cauza subiectului periculos, autoritatile abatiei tineau cartea sub paza, departe de vizitatorii ocazionali. Astfel, mentorul warlock din Northshire, Drusilla La Salle, nu putea sa o rasfoiasca fara sa atraga suspiciunile preotimii."},{t="Furtul si recuperarea obiectelor de catre Defias",b="Un novice din Northshire a luat tomul cu el cand si-a abandonat juramintele pentru a se alatura Defias Brotherhood. Fugind spre podgoriile invecinate, a luat cu sine mai multe volume de valoare din abatie. Drusilla trimite initiati promitatori warlock in tabara de banditi Defias ca sa recupereze cartea din corturile lor. Vrea cunostintele intunecate pentru propriile studii, iar misiunea pune la incercare daca un initiat are curajul de a lega demoni din alte lumi."}},faq={{q="Ce este Powers of the Void?",a="Powers of the Void este o carte oculta rara despre energiile umbrelor si ale Netherului, despre care se crede ca a fost scrisa de Archmage Khadgar. Cartea era pastrata intr-o aripa restrictionata a bibliotecii din Northshire Abbey, inainte sa fie furata.",al={"ce sunt Powers of the Void","cartea Powers of the Void","ce este tomul furat"}},{q="De ce a fost incuiata cartea in Northshire Abbey?",a="Northshire Abbey pastreaza arhive istorice, inclusiv texte periculoase despre magie interzisa. Cartile despre energiile Vidului si demonologie sunt incuiate, pentru a nu-i lasa pe novici si practicantii rataciti sa abuzeze de ele.",al={"de ce era la manastire","de ce il aveau preotii","aripa bibliotecii din Northshire"}},{q="Cum a obtinut cartea Defias Brotherhood?",a="Un novice de la Northshire Abbey a dezertat in Defias Brotherhood si a luat mai multe volume de pret din biblioteca cu acces restrictionat. Le-a ascuns in tabara banditilor din podgoriile Northshire.",al={"cine a furat cartea","carti furate de Defias","cum au obtinut-o Defias"}},{q="De ce vrea Drusilla La Salle Powers of the Void?",a="Drusilla La Salle este mentorul Warlock din Northshire si vrea sa obtina cunostintele din tom pentru propriile sale practici intunecate. Nu putea intra in biblioteca securizata a abatiei fara sa trezeasca suspiciuni.",al={"de ce il vrea Drusilla","cine vrea cartea","tome furat de Drusilla La Salle"}},{q="Ce ii dovedeste lui Drusilla recuperarea tomului?",a="Recuperarea tomului verifica daca un initiat are curajul sa lege demoni. Drusilla foloseste aceasta proba inainte sa-i invete sa-si invoce primul imp.",al={"de ce au warlock nevoie de carte","testul de invocare a unui imp","recompensa pentru tomul furat"}}},fx={["082e56cb"]={q="Cine a scris Powers of the Void?",a="Se crede ca tratatul arcane a fost scris de legendarul mag suprem Khadgar, care a studiat multe taine profunde si primejdioase ale magiei inainte de a trece dincolo de Dark Portal. Invataturile sale interzise despre vidul cel adanc au fost considerate mult prea periculoase pentru a fi citite la intamplare, asa ca preotii si carturarii de la Northshire Abbey l-au sigilat intr-o aripa bine pazita a bibliotecii, pana cand un novice tradator l-a furat.",al={"autorul Powers of the Void","cine a creat Powers of the Void","creatorul Powers of the Void"}}},fp="18,270,28.487.0,25.432.0,27.213.0,47.203.0,44.183.0,51.177.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Prairie Alpha Tooth",s="Un Prairie Alpha Tooth este luat de la aprigii conducatori de haita care cutreiera campiile din jurul Thunder Bluff. In traditia tauren, acesti dinti sunt o ofranda puternica pentru purificarea si cinstirea pretioaselor surse de apa ale tinutului.",h="Un Prairie Alpha Tooth este luat de la aprigii conducatori de haita care cutreiera campiile din jurul Thunder...",kw={"Bloodhoof Village","Mulgore","Mull Thunderhorn","Prairie Alpha Tooth","alfa lup de prerie","fantana cu apa","Wildmane Totem"},ang={["class:Shaman"]="Trebuie sa imbunam spiritele fantanilor cu apa prin restabilirea echilibrului pamantesc, iar oferirea coltilor unui pradator de varf consolideaza aceasta armonie naturala.",["race:Tauren"]="Sa iei coltii unui mascul alfa din prerie intruchipeaza datoria sacra a lui Hunter de a culege cu respect ceea ce este necesar, redand acea esenta primordiala pentru a vindeca pamantul otravit."},sec={{t="O ofranda purificatoare",b="Fantanile din Mulgore sunt vitale pentru tauren, iar pastrarea puritatii lor spirituale impune rituri de respect si sacrificiu. Pentru a curata Wildmane Well, Mull Thunderhorn din Bloodhoof Village are nevoie de colti adunati de la lupii de preerie alfa care pandesc in umbra lui Thunder Bluff. Fiind pradatori de varf ai campiilor ierboase unduitoare, acesti lupi intruchipeaza forta bruta a salbaticiei. Daruirea coltilor lor onoreaza echilibrul dintre vanator, prada si spiritele pamantului."}},faq={{q="La ce foloseste Prairie Alpha Tooth?",a="Mull Thunderhorn foloseste opt dintre acesti dinti intr-un ritual pentru a purifica Wildmane Well, ultima fantana de apa contaminata din apropiere de Bloodhoof Village.",al={"scopul coltilor de alfa","la ce folosesc coltii de lup in Mulgore","obiectul Wildmane Totem"}},{q="Pe unde umbla Prairie Wolf Alphas?",a="Lupii de preerie alfa pandesc prin campiile ierboase deschise din centrul si nordul Mulgore, mai ales in jurul falezelor de la baza Thunder Bluff.",al={"unde se gasesc lupii alfa de prerie","locatiile lupilor alfa","zone in care apar lupii alfa de prerie"}},{q="De ce necesita un ritual de purificare a apei dinti de lup?",a="Riturile tauren cinstesc echilibrul naturii. Curatarea fantanilor necesita componente sacre luate direct de la fiarele salbatice si feroce ale tinutului, simbolizand atat sacrificiul, cat si vitalitatea faunei din Mulgore.",al={"de ce colti de lup pentru apa","povestea ritualului cu dintele lui mull thunderhorn"}}},fx={f1f3b80c={q="Ce este un Prairie Alpha Tooth?",a="Prairie Alpha Tooth este un dinte luat de la un lup de preerie alfa, unul dintre cei mai feroce conducatori de haita care cutreiera campiile din Mulgore. Pentru tauren, acesti colti intruchipeaza puterea si spiritul pradatorilor de varf ai tinutului si au o insemnatate spirituala atunci cand sunt oferiti in cadrul unui ritual.",al={"Prairie Alpha Tooth","ce este Prairie Alpha Tooth","dinte de lup alfa de prerie"}},["0674aadd"]={q="De unde provine un Prairie Alpha Tooth?",a="Acesti colti sunt luati de la lupii de prerie alfa care cutreiera pajistile din Mulgore, mai ales in apropierea bazei din Thunder Bluff, la nord. Fiind colti naturali ai unor pradatori vii, sunt luati direct de la fiare in timpul vanatorii, nu sunt facuti de mana muritorilor.",al={"de unde provin dintii prairie alpha","originea obiectului prairie alpha tooth","cine lasa prairie alpha tooth"}}},fp="19,216,20.495.0,39.142.0,34.148.0,53.212.0"}
P.entries["item:prairie-wolf-heart"] = {n="Prairie Wolf Heart",s="Prairie Wolf Heart este un organ vital recoltat de la lupii care cutreiera pajistile din Mulgore. Este un ingredient esential intr-un leac popular urgent, pregatit de Maur Raincaller in Bloodhoof Village pentru a combate o infectie provocata de venin.",h="Prairie Wolf Heart este un organ vital recoltat de la lupii care cutreiera pajistile din Mulgore.",kw={"Bloodhoof Village","Maur Raincaller","Mazzranache","Mulgore","vanator de preerie","inima de lup de preerie","inima de lup"},ang={["class:Hunter"]="Urmarirea unor haite de lupi pe campii dovedeste o intelegere timpurie a vanatului si a ecologiei fiarelor din Mulgore.",["race:Tauren"]="Folosirea partilor de animale recoltate pentru a prepara leacuri de supravietuire reflecta traditiile pragmatice, legate de pamant, ale taurenilor din tinuturile salbatice ale Mulgore."},sec={{t="Leac pentru o muscatura otravitoare",b="Lupii campiilor sunt pradatori feroce, rezistenti si staruitori printre pajistile intinse din Mulgore. Inimile lor sunt cautate de Maur Raincaller, un tauren din Bloodhoof Village, care a cazut victima legendarului alergator de campie cunoscut sub numele de Mazzranache. Lovit de veninul virulent al creaturii, care provoaca febra, Maur se bazeaza pe leacurile traditionale ale campiilor pentru a opri raspandirea otravii. Alaturi de alti reactivi puternici, precum os de pumac si pipota de pasare, esenta vitala a unui lup de prerie proaspat ucis ofera proprietatile purificatoare necesare pentru a prepara un leac inainte ca delirul sa-i fie fatal."}},faq={{q="La ce se foloseste Prairie Wolf Heart?",a="Este adunat pentru Maur Raincaller in Bloodhoof Village. Maur are nevoie de el, alaturi de cateva alte parti de animale, pentru a prepara un leac popular puternic impotriva muscaturii veninoase a temutului alergator Mazzranache.",al={"la ce foloseste inima de lup","de ce sa obtii o inima de lup","scopul inimii de lup de prerie"}},{q="De unde poti obtine un Prairie Wolf Heart?",a="Este luat de pe trupurile lupilor de prerie, ale masculilor alfa si ale pradatorilor de prerie care vaneaza prin campiile unduitoare din Mulgore.",al={"locatia inimii de lup","cine lasa inima de lup","cum gasesti inima lupului de prerie"}},{q="De ce are Maur Raincaller nevoie de organe de animale pentru a-si trata rana?",a="Mazzranache provoaca o muscatura groaznica, infectata, care aduce febra si delir. Maur foloseste leacuri traditionale ale taurenilor de pe campii, alcatuite din ingrediente puternice - inima de lup, femur de puma, solz de plainstrider si pipota de swoop - pentru a curata infectia inainte sa devina mortala.",al={"de ce inima de lup pentru leac","remediul lui Maur"}},{q="Se poate folosi orice inima de lup pentru leac?",a="Maur Raincaller cere pur si simplu o inima de lup. Cea stransa pentru leac este luata de la lupii preriei, masculii alfa ai lupilor preriei sau pradatorii preriei care vaneaza campiile din Mulgore.",al={"orice inima de lup","ce lupi o lasa"}}},fx={ee1c9772={q="Ce este Prairie Wolf Heart?",a="Prairie Wolf Heart este organul recoltat de la lupii rapitori care cutreiera campiile ondulate din Mulgore. Desi are putina valoare in comertul obisnuit, vitalitatea inimii unei fiare salbatice o face un ingredient pretios in medicina traditionala tauren. Este unul dintre numerosii reactivi puternici necesari pentru a prepara leacuri capabile sa elimine otravurile naturale virulente si infectiile adanci.",al={"ce este inima lupului de prerie","inima lupului de prerie","despre inima lupului de prerie"}},["1392571f"]={q="De unde provine o Prairie Wolf Heart?",a="Inima este luata direct de la lupii de preerie salbatici, lupii de preerie alfa si lupii de campie indigeni podisurilor inierbate din Mulgore. Este un organ biologic natural, recoltat de la un pradator ucis, nu un obiect mesterit de mainile muritorilor.",al={"de unde provine inima lupului de prerie","originea inimii lupului de prerie","cine a facut inima lupului de prerie"}}},fp="18,243,28.598.0,38.211.0,43.140.0,63.269.0,42.184.0"}
P.entries["item:prairie-wolf-paw"] = {n="Prairie Wolf Paw",s="Prairie Wolf Paws sunt recoltate de la pradatorii care cutreiera campiile din Mulgore. Practicantii samanici, precum Mull Thunderhorn din Bloodhoof Village, le folosesc drept componente organice pentru a lega puterea naturala a pamantului de totemuri purificatoare.",h="Prairie Wolf Paws sunt recoltate de la pradatorii care cutreiera campiile din Mulgore.",kw={"bloodhoof village","mulgore","mull thunderhorn","gheara de plainstrider","poison water","lup de prerie","labuta lupului de prerie","winterhoof water well"},ang={["class:Shaman"]="Confectionarea totemurilor purificatoare din parti de animale locale demonstreaza principiul elemental al folosirii esentei vii a pamantului pentru a alunga coruptia nefireasca.",["race:Tauren"]="Pentru tauren, recoltarea labelor de lup este o datorie solemna de gospodarire, prin care sunt chemate fiarele native ale tinutului sa vindece fantanile ancestrale de apa, otravite de lacomia goblinilor."},sec={{t="Reactivi naturali ai campiilor",b="Lupii de preerie pandesc prin ierburile ondulate din Mulgore, vanand in haite alaturi de pradatorii de preerie si conducatorii haitelor lor. Desi sunt primejdiosi pentru vanatorii tineri si vitele localnicilor, aceste fapturi sunt profund legate de echilibrul spiritual al campiilor. Samanii tauren privesc labele lupilor nu doar ca pe niste trofee, ci si ca pe niste canale esentiale ale vitalitatii innascute a pamantului."},{t="Purificarea fantanilor",b="Cand aventurile goblinilor au contaminat rezervele de apa sacra din Mulgore, samanul Mull Thunderhorn a avut nevoie de ajutorul concret al pamantului insusi pentru a contracara poluarea. Legate impreuna cu gheare de plainstrider, labele de lup ofera rezonanta spirituala bruta necesara pentru faurirea totemurilor purificatoare si inceperea lucrarii esentiale de purificare a Winterhoof Water Well."}},faq={{q="Ce creaturi lasa in urma Prairie Wolf Paw?",a="Sunt adunate de la lupii de prerie, panda de prerie si lupii alfa de prerie care vaneaza pe campiile din Mulgore, mai ales la sud-vest de Bloodhoof Village.",al={"cine lasa laba de lup de prerie","de unde obtin labe de lup de prerie","sursa labei de lup de prerie"}},{q="Cine vrea Prairie Wolf Paws?",a="Mull Thunderhorn, un shaman Tauren stationat in Bloodhoof Village, le cere sa-l ajute sa confectioneze un totem purificator care sa curete fantanile cu apa contaminata.",al={"cine are nevoie de labele lupilor de campie","labele lupilor de campie pentru Mull Thunderhorn","predarea labei de lup de campie"}},{q="De ce sunt necesare labele de lup pentru a purifica apa?",a="Samanismul tauren se bazeaza pe canalizarea vitalitatii naturale a pamantului pentru a contracara coruptia. Labele de lup, impreuna cu ghearele pasarilor, ii permit samanului sa lege spiritul viu din Mulgore de un totem elemental, capabil sa curete otrava goblinilor.",al={"de ce labele de lup","povestea labei lupului de prerie","de ce vrea mull labele"}},{q="La ce fantana ajuta aceste labe sa purifice apa?",a="Labele sunt adunate special pentru a fauri totemul de purificare al Winterhoof Water Well, care a fost otravit de intrusii goblini si agentii lor.",al={"care fantana","purificarea fantanii Winterhoof"}}},fx={["94c15e4c"]={q="Ce este o Prairie Wolf Paw?",a="Prairie Wolf Paw este o componenta ritualica naturala, recoltata de la canidele salbatice care cutreiera campiile din Mulgore. Departe de a fi simple trofee, aceste labe poarta esenta vie a pamantului, fiind pretioase pentru samanii tauren care creeaza totemuri pentru a vindeca si a ocroti pamantul.",al={"labuta de lup de prerie","ce sunt labutele de lup de prerie","labuta de lup din Mulgore"}},["7a637be5"]={q="De unde provin Prairie Wolf Paws?",a="Aceste labe sunt luate direct de la lupii de preerie, lupii panditori de preerie si masculii alfa nativi de pe platourile inierbate din Mulgore. Sunt parti firesti ale salbaticiei, luate de vanatori pentru a oferi puterea pamantului in vremuri de nevoie spirituala.",al={"de unde provin labele lupului de prerie","sursa labei lupului de prerie","cine lasa labe de lup"}}},fp="16,244,30.370.0,19.354.0,39.166.0,28.147.0,42.251.0,44.154.0"}
P.entries["item:pridewing-venom-sac"] = {n="Pridewing Venom Sac",s="Pridewing Venom Sacs sunt recoltate de la wyvernele letale care isi fac cuibul in jurul lacului Mirkfallon Lake, din Stonetalon Mountains. Elfii noptii din Astranaar cauta sa stranga si sa distruga aceste saci, dupa ce informatiile sugereaza ca agentii Horde recolteaza otrava puternica pentru asasinate secrete.",h="Pridewing Venom Sacs sunt recoltate de la wyvernele letale care isi fac cuibul in jurul lacului Mirkfallon...",kw={"astranaar","mirkfallon lake","pridewing","shindrell swiftfire","stonetalon","sac cu venin","wyvern"},ang={["faction:Alliance"]="Impotrivirea accesului Horde la veninul de pridewing este vitala pentru protejarea patrulelor de frontiera de asasinii nevazuti de-a lungul hotarelor disputate din Stonetalon si Ashenvale.",["race:NightElf"]="Desi conducerea Sentinels regreta ca trebuie sa elimine fiare salbatice nevinovate, protejarea vietilor elfilor de lamele otravite primeaza asupra armoniei naturale."},sec={{t="O amenintare in stanci",b="Pridewings din Stonetalon sunt pradatori zburatori periculosi, originari de pe piscurile de la sud de Ashenvale, mai ales din jurul Mirkfallon Lake. Desi wyvernele salbatice sunt veninoase din fire, informatiile Alliance venite din Theramore sugereaza ca asasinii Horde au inceput sa le mulga veninul pentru a unge lamele folosite in raiduri ascunse asupra asezarilor night elf. Pentru a-si proteja neamul si a perturba aprovizionarea inamicului, Sentinels din Astranaar angajeaza cercetasi care sa vaneze fiarele si sa adune glandele de venin inainte ca Horde sa puna mana pe ele."}},faq={{q="Ce creaturi lasa in urma un Pridewing Venom Sac?",a="Aceste saci cu venin sunt luati de la diversele wyverne care locuiesc printre stancile de langa Mirkfallon Lake, in Stonetalon Mountains, inclusiv pui de pridewing, vanatori ai cerului, patriarhi si consoarte.",al={"de unde obtii Pridewing Venom Sac","cine lasa Pridewing Venom Sac","surse de venin Pridewing"}},{q="De ce vrea Astranaar Pridewing Venom Sacs?",a="Shindrell Swiftfire a primit rapoarte potrivit carora agenti ai Horde recolteaza venin de pridewing pentru a acoperi arme folosite in asasinatele tacute impotriva Alliance. Distrugerea sau confiscarea glandelor impiedica aceste atacuri.",al={"de ce se aduna sacii cu venin","veninul lui Shindrell Swiftfire"}},{q="Cine primeste aceste saci cu venin in Ashenvale?",a="Shindrell Swiftfire, stationata in orasul elfilor noptii Astranaar, din Ashenvale, le aduna pentru a-si proteja poporul de atacurile pe furis.",al={"cine ia veninul Pridewing","predarea misiunii Pridewing"}},{q="Sunt pridewingii aliati in mod firesc cu Horde?",a="Nu. Pridewing-urile salbatice din jurul Mirkfallon Lake sunt fiare care nu ajuta de bunavoie Horde, desi agentii orci le exploateaza biologia veninoasa in propriile lor razboaie.",al={"sunt Pridewing de partea Horde","lucreaza Pridewing pentru Orc"}}},fx={e2bba8d5={q="Ce este un Pridewing Venom Sac?",a="Pridewing Venom Sac este un organ recoltat de la wyvernii pridewing care isi fac cuibul in Stonetalon Mountains. Contine toxinele naturale puternice pe care acesti pradatori inaripati le produc pentru a-si imobiliza prada. In fragila confruntare dintre elfii noptii si Horde, o astfel de otrava a devenit o arma ravnita pentru atacuri clandestine, atragand atentia aparatorilor din Astranaar.",al={"ce este Pridewing Venom Sac","obiect Pridewing Venom Sac","ce sunt obiectele Pridewing Venom Sac"}},["816b56c2"]={q="De unde provine Pridewing Venom Sac?",a="Aceste glande sunt recoltate direct din trupurile pridewingilor - wyvern salbatici si feroce care isi fac cuiburi langa Mirkfallon Lake, in Stonetalon Mountains. Fiind organe naturale ale creaturilor, nu bunuri fabricate, obtinerea lor presupune vanarea wyvernilor printre stanci si colectarea veninului inainte ca agentii Horde sa-l poata lua.",al={"pridewing venom sac sursa","de unde provin pridewing venom sacs","cine lasa pridewing venom sac"}}},fp="19,286,21.530.0,43.192.0,45.209.0,42.140.0,51.166.0"}
P.entries["item:prismatic-punch-card"] = {n="Prismatic Punch Card"}
P.entries["item:pristine-spider-silk"] = {n="Pristine Spider Silk",s="Magii din Stormwind cauta Pristine Spider Silk pentru vesminte tesute sa reziste la vraji. Firul fin provine de la paianjenii veninosi din Duskwood.",h="Magii din Stormwind cauta Pristine Spider Silk pentru vesminte tesute sa reziste la vraji.",kw={"pui de vaduva neagra","pustnic hoitar","Duskwood","roba de mag","matase de paianjen neprihanita","Wizard's Sanctum","Wynne Larson"},ang={["class:Mage"]="Ca mage din Stormwind, esti trimis in Duskwood sa aduni aceasta ata fina si sa castigi o roba potrivita statutului tau arcane in crestere.",["profession:Tailoring"]="Ca croitor, lucrezi cu fire delicate si rezistente adunate de la paianjeni mortali, un material textil natural de calitate pentru vesminte magice."},sec={{t="Tesand arcana",b="Vrajitorii din Stormwind au nevoie de matase suficient de rezistenta ca sa suporte vrajile si uzura la care este supusa de catre un adept. Croitorii folosesc matasea obisnuita de paianjen, dar firele adunate de la paianjenii hoitari si puii de vaduva neagra din Duskwood sunt mai rezistente. Vrajitorii din Wizard's Sanctum trimit adepti in devenire in acele paduri sa adune matasea. Apoi, maestrul croitor Wynne Larson o tese intr-o roba pentru un adept."}},faq={{q="De unde provine Pristine Spider Silk?",a="Pristine Spider Silk provine de la paianjenii carrion recluse si puii de vaduva neagra din Duskwood.",al={"unde gasesc matase de paianjen imaculata","cine lasa matase de paianjen imaculata","locatia matasii de paianjen imaculate"}},{q="Cine confectioneaza haine din aceasta matase?",a="Wynne Larson, o croitoreasa din Mage Quarter al Stormwind, tese matasea adunata intr-o roba pentru Wizard's Sanctum.",al={"cine foloseste matasea de paianjen pura","cine transforma matasea in robe","roba lui Wynne Larson"}},{q="De ce au nevoie magii de aceasta matase anume?",a="Mage au nevoie de matase suficient de rezistenta pentru ca roba unui novice sa poata purta descantece si sa reziste uzurii. Matasea paianjenilor din Duskwood are rezistenta si calitatea necesare.",al={"de ce matase nepatata","la ce foloseste matasea magica de paianjen"}}},fx={dfaa8e27={q="Ce este Pristine Spider Silk?",a="Pristine Spider Silk este o panza de paianjen deosebit de fina si imaculata, tesuta de arahnidele care bantuie Duskwood. Spre deosebire de panzele obisnuite, zdrentuite, care atarna de copaci prin padurea umbrita, doar firele cele mai pure si fara cusur se pot numi impecabile. Tesatorii si vrajitorii o pretuiesc foarte mult pentru calitatea si textura superioare, folosind-o ca material de baza pentru vesminte deosebite, potrivite magilor.",al={"matase de paianjen impecabila","ce este matasea impecabila","obiect din matase impecabila"}}},fp="20,138,18.381.0,42.88.0,35.117.0,44.157.0"}
P.entries["item:prowler-claws"] = {n="Prowler Claws"}
P.entries["item:pure-hearts"] = {n="Pure Hearts",s="Pure Hearts sunt reactivi ritualici oferiti vrajitorilor Forsaken de catre Carendin Halgar in Undercity. Sunt folositi pentru a atrage si manifesta o succubus prin Twisting Nether, astfel incat practicantul sa poata invinge demonul si sa-l lege.",h="Pure Hearts sunt reactivi ritualici oferiti vrajitorilor Forsaken de catre Carendin Halgar in Undercity.",kw={"Carendin Halgar","Magic Quarter","inimi pure","succubus","invocare","Legarea","Undercity"},ang={["class:Warlock"]="Pentru vrajitorii Forsaken, obtinerea si folosirea acestor inimi reprezinta o etapa de cotitura in demonologie: dovada tariei mentale in fata ispitelor seducatoare din Twisting Nether.",["race:Undead"]="In mijlocul putreziciunii si al molimei din Undercity, folosirea unor inimi cu totul nealterate pentru a manipula poftele demonice intruchipeaza vrajitoria rece si pragmatica practicata de Forsaken."},sec={{t="Momeala pentru Nether",b="Demonologia se bazeaza pe exploatarea dorintelor josnice si a vulnerabilitatilor spirituale. Pentru a invoca o succubus in Magic Quarter of the Undercity, Carendin Halgar le ofera warlockilor Pure Hearts. Asezate pe cercul de invocare, aceste esente spirituale nepatate servesc drept momeala puternica, atragand demonul seducator prin Twisting Nether si pana in taramul muritorilor. Dupa ce demonul se infatiseaza, warlockul trebuie sa-i reziste farmecelor mentale seducatoare si sa-l doboare in lupta. Infrangerea succubusului ii impune dominatia mistica, izgonind-o inapoi in Twisting Nether pana cand Carendin il invata vraja prin care o poate invoca dupa voie."}},faq={{q="La ce se folosesc Pure Hearts?",a="Ele servesc drept catalizator mistic, folosit in cercul de invocare din Magic Quarter, in Undercity, pentru a atrage si a materializa o succuba dincolo de vid, permitandu-i unui warlock sa lupte cu ea si sa o lege.",al={"utilizarea inimilor pure","de ce sunt necesare inimile pure","la ce folosesc inimile pure"}},{q="Cine furnizeaza Pure Hearts?",a="Carendin Halgar, antrenorul warlockilor Forsaken aflat in Magic Quarter, sub ruinele Lordaeron, le ofera acestea aspirantilor gata sa stapaneasca invocarea unei succubus.",al={"cine ofera inimi pure","cel care da misiunea Pure Hearts"}},{q="De ce reactioneaza o sucubus la Pure Hearts?",a="Succubii prospera prin coruptie, seductie si pangarirea inocentei. Stralucirea inimilor neprihanite si pure este o ispita irezistibila in tot Twisting Nether, atragandu-le direct in cercul de invocare pregatit de warlock.",al={"de ce vrea succuba inimile pure","povestea din spatele inimilor pure"}},{q="Pastrezi Pure Hearts dupa ritual?",a="Nu. Dupa ce succuba este invocata si supusa, ramasitele Pure Hearts ii sunt returnate lui Carendin Halgar drept dovada ca proba de legare a fost indeplinita.",al={"pastrez inimile pure","ce se intampla cu inimile pure"}}},fx={["105bfa16"]={q="Ce sunt Pure Hearts?",a="Pure Hearts sunt componente ritualice puternice, folosite de warlockii Forsaken din Undercity. Atunci cand sunt puse intr-un cerc de invocare, esenta lor neintinata serveste drept momeala peste Twisting Nether, deschizand o ruptura menita anume sa atraga si sa invoce un succubus primejdios in prezenta ta.",al={"ce sunt inimile pure","obiect: inimi pure","inimile pure ale Warlock"}},["3abadf0f"]={q="De ce ar vrea cineva Pure Hearts?",a="Un warlock aspirant are nevoie de Pure Hearts pentru a indeplini ritualul periculos de legare a unui succubus. Fara sa oferi o astfel de momeala nepangarita pentru a face legatura peste vid, nu poti atrage demonul in lumea muritorilor ca sa-l supui si sa stapanesti arta invocarii sale in slujba ta.",al={"de ce vor inimi pure","scopul inimilor pure","de ce sunt cautate inimile pure"}}},fp="11,222,19.638.0,34.185.0,29.188.0,43.227.0,52.152.0"}
P.entries["item:purified-kor-gem"] = {n="Purified Kor Gem"}
P.entries["item:putrid-claw"] = {n="Putrid Claw",s="Putrid Claws sunt mainile putrezite retezate de la strigoii fara minte care cutreiera padurile de la vest de Brill. Deathguard Dillinger le strange ca dovada categorica faptului ca amenintarea tot mai mare reprezentata de Scourge, langa podul vechi, este tinuta sub control.",h="Putrid Claws sunt mainile putrezite retezate de la strigoii fara minte care cutreiera padurile de la vest de...",kw={"o sarcina putreda","brill","deathguard dillinger","gheara putreda","cadavru mutilat","mortii in descompunere","flagel","tirisfal glades"},ang={["race:Undead"]="Pentru noii initiati Forsaken care parasesc Deathknell, nimicirea acestor creaturi fara minte din Scourge le aminteste de la inceput ca eliberarea vine la pachet cu lupta neincetata impotriva hoiturilor fara minte care le-au semanat candva."},sec={{t="Trofeul celor lipsiti de minte",b="Nici macar pe meleagurile lor, Forsaken nu sunt cu totul feriti de puterea Lich King. Cete de Scourge lipsite de minte - morti in putrefactie si cadavre mutilate - ratacesc in mod regulat peste granita estica, in Tirisfal Glades, adunandu-se de-a lungul drumurilor si in apropierea podului vechi de la vest de Brill. Pentru a garanta siguranta calatorilor si a rutelor de aprovizionare ale garnizoanei, Deathguards pun recompense pe capetele acestor orori ratacitoare. O gheara putreda, retezata, este dovada fizica de netagaduit ca inca un cadavru clatinandu-se a fost doborat pentru totdeauna."}},faq={{q="La ce sunt folosite ghearele putrezite?",a="Deathguard Dillinger, aflat in Brill, le colecteaza drept recompense, pentru a confirma ca recrutilor locali Forsaken le raresc randurile Scourge-ului care cutreiera Tirisfal Glades.",al={"la ce foloseste gheara putrezita","de ce se aduna gheare putrezite","cine vrea gheare putrezite"}},{q="De unde provin ghearele putrezite?",a="Sunt recoltate de la mortii in putrefactie si cadavrele schilodite care bantuie padurile bantuite de la vest de Brill, mai ales in apropierea vechiului pod peste rau.",al={"de unde iei gheare putrede","ce lasa gheara putreda","prada mortilor in descompunere"}},{q="De ce se afla Scourge in Tirisfal Glades?",a="Dupa devastarea Lordaeronului, ramasitele Scourge-ului lipsit de minte al Lich King-ului se strecoara necontenit spre vest, trecand granitele in Tirisfal si amenintand drumurile si asezarile daca nu sunt starpite.",al={"de ce sunt zombi langa Brill","Scourge in Tirisfal"}},{q="De ce nu-i lasa Forsaken pe mortii vii fara minte sa rataceasca?",a="Spre deosebire de Forsaken, care s-au eliberat sub conducerea reginei Sylvanas si si-au recapatat vointa, Scourge lipsit de minte asculta doar de instinctele intunecate sau de porunca persistenta a Lich King, atacand pe loc orice fiinta vie sau strigoi liber.",al={"Forsaken contra zombi fara minte","de ce sa omori alti strigoi"}}},fx={["37750c4d"]={q="Ce este o Putrid Claw?",a="Un Putrid Claw este mana taiata si putrezita a unui zombi fara minte, apartinand Scourge. Aceste membre in descompunere sunt luate de la cadavrele umblatoare care bantuie Tirisfal Glades, ca dovada a nimicirii lor.",al={"ce este gheara putreda","informatii despre ghearele putrede","povestea ghearei putrede"}}},fp="11,231,22.526.0,31.161.0,32.141.0,38.203.0,59.211.0"}
P.entries["item:pyrewood-shackle"] = {n="Pyrewood Shackle",s="Pyrewood Shackle sunt niste legaturi vrajite purtate de locuitorii napastuiti din Pyrewood Village, in sudul Silverpine Forest. Insufletite de magia stranie a lui Archmage Arugal, aceste benzi misterioase par sa joace un rol in soarta intunecata care se abate asupra localnicilor cand se lasa noaptea peste asezare.",h="Pyrewood Shackle sunt niste legaturi vrajite purtate de locuitorii napastuiti din Pyrewood Village, in sudul...",kw={"Arugal","Dawnweaver","Moonrage","Pyrewood","Sepulcher","catuse","Silverpine","worgen"},ang={["class:Mage"]="Magii care studiaza opera lui Arugal vor recunoaste aplicarea imprudenta a magiei de transmutare si legare tesute in otel obisnuit.",["race:Undead"]="Carturarii Forsaken de la Sepulcher considera ca vrajitoria nestavilita a lui Arugal reprezinta o amenintare majora pentru granitele lor, ceea ce face ca strangerea acestor legaturi vrajite sa fie esentiala pentru neutralizarea influentei Shadowfang Keep."},sec={{t="Magia Binding a lui Arugal",b="Satul blestemat Pyrewood ascunde un secret nelinistitor: ziua, locuitorii isi duc viata obisnuita si par oameni de rand, dar la apus sunt preschimbati in worgen Moonrage salbatici. Archmage Arugal i-a legat pe acesti sateni cu catuse vrajite, ca parte a experimentelor sale perverse cu vrajitoria worgen. Dalar Dawnweaver, cercetator arcane aflat la Sepulcher in slujba Forsaken, studiaza aceste catuse pentru a descifra vrajile care le provoaca existenta dubla. Adunand si analizand energia latenta de pe bratari, Dawnweaver cauta sa inteleaga mai bine magia lui Arugal, in speranta ca va putea destrama controlul arhimage-ului nebun asupra regiunii."}},faq={{q="La ce folosesc Pyrewood Shackles?",a="Dalar Dawnweaver de la Sepulcher cere aceste catuse pentru a le studia vrajile. Absorbindu-le magia, spera sa dezlege vrajile lui Archmage Arugal si sa gaseasca o cale de a inlatura influenta arhimagului din Silverpine Forest.",al={"pyrewood shackles folosire","de ce sa aduni catuse","dalar dawnweaver shackles"}},{q="Cine poarta aceste catuse?",a="Catusele sunt purtate de locuitorii blestemati din Pyrewood Village, in sudul Silverpine Forest; le poarta atat in timpul infatisarii lor umane diurne, cat si dupa transformarea nocturna in worgen Moonrage.",al={"cine lasa Pyrewood Shackles","sursa catusei","unde gasesc Pyrewood Shackles"}},{q="De ce se transforma satenii noaptea?",a="Archmage Arugal a supus populatia din Pyrewood unor experimente si descantece magice nechibzuite. Catusele mentin un descantec care le permite sa para oameni obisnuiti in timpul zilei, doar pentru a-si dezvalui infatisarea feroce de worgen dupa lasarea intunericului.",al={"de ce se transforma Pyrewood in worgen","blestemul din Pyrewood Village","secretul varcolacilor din Pyrewood"}},{q="Cine este Dalar Dawnweaver?",a="Dalar Dawnweaver este un mag Forsaken care locuieste la Sepulcher, in Silverpine Forest. Studiaza activ anomaliile arcane lasate in urma de Archmage Arugal, concentrandu-se asupra deslusirii si destramarii blestemelor sucite ale arhimagului.",al={"dalar dawnweaver","cine este dalar"}}},fx={b92f5faa={q="Ce este un Pyrewood Shackle?",a="Pyrewood Shackle este o catusa fermecata, legata de nefericitii locuitori ai Pyrewood Village din sudul Silverpine Forest. Incatusarile, impregnate cu vrajitoria stranie si nesabuita a magului nebun Archmage Arugal, au un rol direct in supunerea orasenilor vointei sale si in ascunderea blestemului intunecat care ii afecteaza.",al={"pyrewood shackle","ce sunt pyrewood shackles","pyrewood shackles"}},f6bcbb50={q="De unde provine un Pyrewood Shackle si cine l-a facut?",a="Aceste catuse fermecate au fost faurite si puse asupra satenilor de Archmage Arugal, vrajitorul renegat din Dalaran care s-a stabilit in Shadowfang Keep. Arugal a aruncat vraja catuse asupra taranilor din Pyrewood, ca parte a descantecelor sale pervertite, tinandu-i sub stapanirea sa si ascunzandu-le transformarea lupina sub o iluzie diurna a unei vieti omenesti obisnuite.",al={"cine a creat pyrewood shackles","originea pyrewood shackle","de unde provin catusele"}},["98d012f7"]={q="De ce si-ar dori cineva Pyrewood Shackles?",a="Dalar Dawnweaver, un mag Forsaken ambitios, care face cercetari la Sepulcher, cauta aceste catuse fermecate pentru a studia magia lui Arugal. Drenandu-le energia reziduala, Dalar spera sa dezlege vraja bizara care-i face pe satenii de aici sa para oameni ziua, iar dupa lasarea serii sa se transforme in worgen Moonrage insetati de sange, urmarind in cele din urma sa desfaca vrajile lui Arugal.",al={"de ce sa aduni Pyrewood Shackle","cine are nevoie de Pyrewood Shackle","la ce foloseste Pyrewood Shackle"}}},fp="16,302,22.656.1,36.232.0,27.194.1,40.256.1,24.223.0"}
P.entries["item:quinn-s-potion"] = {n="Quinn's Potion",s="Quinn's Potion este o licoare tamaduitoare preparata de Apothecary Renferrel in Sepulcher. Este facuta pentru a-l stabiliza si inviora pe Deathstalker Quinn Yorick, ranit in urma unei patrule de cercetare dezastruoase in Silverpine Forest.",h="Quinn's Potion este o licoare tamaduitoare preparata de Apothecary Renferrel in Sepulcher.",kw={"apothecary renferrel","deathstalker","ivar patch","quinn yorick","quinn's potion","sepulcher","silverpine"},ang={["race:Undead"]="Royal Apothecary Society rareori isi iroseste eforturile cu remedii simple de teren, daca acestea nu ajuta direct la pastrarea in viata a cercetasilor Forsaken, esentiali pentru apararea granitelor Silverpine."},sec={{t="Leacul lui Renferrel",b="Dupa ce Deathstalker Quinn Yorick a fost grav ranit si a ramas fara putere in apropiere de Ivar Patch, vestea a ajuns la Royal Apothecary Society din Sepulcher. Apothecary Renferrel a preparat in graba aceasta potiune speciala pentru a-i inlesni recuperarea lui Quinn. Desi Renferrel nu lasa de obicei ranile usoare suferite pe teren sa-i abata atentia de la cercetarile sale mai ample si mai sinistre pentru Lady Sylvanas, i-a oferit remediul ca sa-l puna pe cercetasul ranit pe picioare si in stare sa calatoreasca."}},faq={{q="La ce se foloseste Quinn's Potion?",a="Potiunea este menita sa-l ajute pe Deathstalker Quinn Yorick sa-si revina. Acesta zace ranit in padurile nordice din Silverpine Forest. Daca o bea, isi recapata destula vigoare ca sa poata calatori din nou.",al={"scopul potiuni lui Quinn","ce face potiunea lui Quinn","de ce prepara Quinn potiunea"}},{q="Cine a preparat aceasta potiune?",a="Apothecary Renferrel, un alchimist al Royal Apothecary Society aflat in criptele din Sepulcher, a preparat potiunea.",al={"cine a facut potiunea lui Quinn","cine a preparat-o","potiunea lui Renferrel"}},{q="Unde trebuie livrata potiunea?",a="Trebuie dusa la nord de Sepulcher, la Quinn Yorick, care se adaposteste langa ferma numita Ivar Patch.",al={"unde duc potiunea","locatia lui quinn","locul lui quinn yorick"}},{q="De ce a avut Quinn Yorick nevoie de o potiune?",a="Quinn facea parte dintr-o patrula Deathstalker care cerceta nordul tinutului Silverpine. La Ivar Patch, cercetasii au fost atacati de ghoul-ul Ivar the Foul, iar Quinn a ramas acolo, grav ranit si izolat.",al={"de ce este ranit Quinn","ce i s-a intamplat lui Quinn Yorick","Quinn ranit"}}},fx={["52098f03"]={q="Ce este Quinn's Potion?",a="Este o potiune cu efect reparator, preparata de Apothecary Renferrel la Sepulcher. Formulata special pentru a-l ajuta pe cercetasul ranit Quinn Yorick, bautura ii ofera puterea necesara pentru a-si vindeca ranile si a-si recapata mobilitatea indeajuns cat sa poata calatori.",al={"potiunea lui Quinn","ce este potiunea aceasta","ce este licoarea lui Quinn"}}},fp="14,231,16.466.0,32.212.0,23.131.0,43.120.0,41.190.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Ran Bloodtooth's Skull",s="Ran Bloodtooth's Skull este un trofeu macabru luat de la capetenia furbolgilor corupti din Ashenvale. Dus inapoi la elfii noptii din Astranaar, serveste drept dovada palpabila ca o amenintare feroce la adresa tinutului impadurit a fost nimicita.",h="Ran Bloodtooth's Skull este un trofeu macabru luat de la capetenia furbolgilor corupti din Ashenvale.",kw={"ashenvale","astranaar","bloodtooth skull","bloodtooth","furbolg","raene wolfrunner","raene's cleansing","ran bloodtooth"},ang={["faction:Alliance"]="Predarea acestui trofeu sumbru dovedeste vitejia campionilor Alliance in apararea granitelor fragile din Ashenvale alaturi de Sentinels.",["race:NightElf"]="Pentru elfii noptii, luarea craniului este o victorie apasatoare. Desi onoreaza sarcina neterminata a lui Teronis, este si o amintire a ravagiilor profunde pe care coruptia demonica le-a facut printre fostii lor aliati furbolgi."},sec={{t="Un trofeu al apararii Ashenvale",b="Padurile din Ashenvale au suferit enorm din cauza pingaririi demonice si a coruptiei tinuturilor salbatice, care au impins triburile pasnice de furbolgi spre o nebunie ucigasa. Printre cei mai inversunati conducatori ostili s-a numarat Ran Bloodtooth. Recuperarea craniului sau le ofera Sentinels din rindul elfilor Night Elf dovada certa ca bruta a fost invinsa, rupindu-i stapinirea asupra furbolgilor din zona si aducind un ragaz, fie el si mic, orasului Astranaar, aflat la ananghie."},{t="Cinstirea celor cazuti",b="Cand este prezentat santinelei Raene Wolfrunner in Astranaar, craniul marcheaza incheierea unei anchete pornite de la cercetasul cazut Teronis. Alaturi de Toiagul lui Dartol - toiagul refacut pe care Teronis plecase sa-l gaseasca - craniul lui Ran Bloodtooth este pastrat la vedere, ca marturie a curajului celor care au luptat pentru a ocroti padurea sacra."}},faq={{q="Cine a fost Ran Bloodtooth?",a="Ran Bloodtooth a fost un sef al furbolgilor corupti din Ashenvale, considerat de Sentinels din randul night elf una dintre cele mai mari amenintari regionale.",al={"cine este Ran Bloodtooth","povestea lui Ran Bloodtooth","cine a fost Bloodtooth"}},{q="De ce vor Sentinels craniul lui?",a="Raene Wolfrunner din Astranaar primeste craniul drept dovada a infrangerii lui Ran Bloodtooth. Craniul este asezat langa Dartol's Rod ca simbol al victoriei si in amintirea celor cazuti aparand Ashenvale.",al={"de ce am nevoie de craniu","craniul lui Raene Wolfrunner","la ce foloseste craniul"}},{q="Cine a fost Teronis?",a="Teronis a fost prieten de-o viata cu Raene Wolfrunner si i-a ajutat pe Sentinels in Ashenvale. A pornit in cautarea unei nestemate pentru un toiag facut de vrajitorul raposat Dartol, sperand ca aceasta va incetini atacurile furbolgilor, dar a fost ucis de murloci la Lake Falathim. Raene Wolfrunner si aventurierii aflati in trecere i-au preluat misiunea.",al={"lore despre Teronis","cine este Teronis","Teronis din Astranaar"}}},fx={["4d0a3ce4"]={q="Ce este Ran Bloodtooth's Skull?",a="Acesta este craniul retezat al lui Ran Bloodtooth, una dintre cele mai feroce si periculoase amenintari dintre furbolgii corupti care bantuie prin Ashenvale. Luat ca dovada a infrangerii sale, acesta pune capat terorii pe care a abatut-o asupra Sentinels si a padurii.",al={"craniul lui Ran Bloodtooth","ce este craniul lui Ran","capul lui Ran Bloodtooth"}},f5c7858d={q="De unde provine Ran Bloodtooth's Skull?",a="Craniul este luat chiar de la Ran Bloodtooth dupa ce acesta este ucis in Ashenvale. Nu este un artefact faurit sau creat de maini muritoare, ci trofeul sumbru luat de pe trupul insusi al capeteniei.",al={"de unde provine craniul lui Ran","cine a facut craniul lui Ran Bloodtooth","sursa craniului lui Ran Bloodtooth"}}},fp="22,242,31.443.0,19.339.1,23.147.0,36.203.0,16.304.0"}
