P.entries["item:red-burlap-bandana"] = {n="Red Burlap Bandana",s="In Northshire Valley, Deputy Willem aduna bandane rosii de la hotii Defias ucisi langa viile abatiei. Tesatura ii identifica pe talharii de drumul mare si hotii de buzunare de rang inferior din Brotherhood.",h="In Northshire Valley, Deputy Willem aduna bandane rosii de la hotii Defias ucisi langa viile abatiei.",kw={"bandana","Brotherhood of Thieves","Defias","masca","Northshire","bandana rosie din panza de sac","Willem"},ang={["class:Rogue"]="Ca Rogue in formare, poti invata de la hotii de buzunare nepriceputi din Northshire cat de repede devin proscrisii nedisciplinati tinte usoare pentru fortele de ordine locale.",["faction:Alliance"]="Ca membru al Alliance, poti vedea cum bandanele rosii ajung pana la pragul Northshire Abbey, semn ca Stormwind pierde controlul asupra granitelor rurale ale regatului."},sec={{t="Un insemn al Fratiei",b="Mastile din panza rosie de sac marcheaza soldatii de rand ai Defias Brotherhood. Panza ieftina si aspra, vopsita in rosu, ascunde chipul hotului si ii arata loialitatea fata de rebeliunea in crestere. In Northshire, tinerii recruti si batausii de rand poarta aceste fulare in livezile din est. Garzile locale recunosc panza rosie si izbitoare ca dovada ca hotii au fost ucisi in apropiere."}},faq={{q="De ce vrea Deputy Willem aceste bandane?",a="Deputy Willem aduna bandanele drept dovada ca un aventurier a ucis batausii Defias de langa Northshire Abbey. Hotii poarta la vedere panza rosie, confirmand ca recompensa a fost revendicata.",al={"de ce sa colectez bandane","bandanele lui Willem","predare pentru Brotherhood of Thieves"}},{q="Cine poarta bandanele rosii din panza de sac?",a="Haiducii si batausii din Defias Brotherhood poarta bandanele rosii din panza de sac. Tesatura aspra le ascunde chipurile si le arata loialitatea fata de proscrisi.",al={"cine poarta bandana rosie","povestea mastii Defias","cine lasa bandane rosii"}},{q="De ce opereaza hotii Defias in Northshire?",a="Cercetasi si talhari Defias si-au instalat tabara dincolo de paraul de la est de Northshire Abbey, ca sa scotoceasca si sa fure provizii. Garnizoana abatiei este suprasolicitata, lasand livezile din apropiere la cheremul talharilor de drum.",al={"de ce sunt Defias in Northshire","hotii de langa abatie"}},{q="Ce face bandanele rosii?",a="Panza de sac ieftina, tratata cu vopsea stacojie, da bandanelor culoarea rosie. Aceasta nuanta este stindardul si uniforma Defias Brotherhood, permitandu-le membrilor sa se recunoasca pe campul de lupta.",al={"de ce sunt rosii mastile Defias","semnificatia panzei rosii"}}},fx={c4ebebb0={q="Ce este Red Burlap Bandana?",a="O Red Burlap Bandana este masca distinctiva din panza purtata de membrii Defias Brotherhood. Confectionata ieftin din panza de sac aspra si vopsita in rosu, aceasta ascunde chipul purtatorului si ii arata loialitatea fata de breasla de proscrisi. In Northshire, este o dovada directa a prezentei si activitatii unui bandit la est de rau.",al={"identitatea bandanei rosii din panza de sac","ce sunt bandanele rosii","povestea bandanei Defias"}}},fp="18,181,25.342.0,43.189.0,34.152.0,47.192.0,28.180.0"}
P.entries["item:red-leather-bandana"] = {n="Red Leather Bandana",s="In Westfall, Red Leather Bandanas ii marcheaza pe cei care sfideaza Coroana din Stormwind. Defias Brotherhood le poarta pentru a-si acoperi fetele si ca semn al cauzei lor.",h="In Westfall, Red Leather Bandanas ii marcheaza pe cei care sfideaza Coroana din Stormwind.",kw={"fratia","Defias","Galiaan","masca","bandana rosie din piele","Sentinel Hill","Westfall"},ang={["class:Rogue"]="Ca rogue, recunosti masca stacojie drept semn al banditismului subteran de pe meleagurile Human, purtata de hoti organizati cu precizie militara.",["faction:Alliance"]="Pentru Alliance, fiecare bandana rosie luata de la un proscris cazut inseamna un bandit in minus care sa-i ameninte pe fermierii infometati din Westfall si militia lor aflata la ananghie."},sec={{t="Semnul Fratiei",b="De-a lungul ogoarelor din Westfall si al fermelor abandonate, talharii, jefuitorii si muncitorii razvratiti poarta bandane purpurii ca sa-si ascunda fetele. Pentru People's Militia din Sentinel Hill, fiecare dintre ei este dovada loialitatii fata de gruparea rebela a lui Edwin VanCleef. Cercetasul Galiaan strange bandanele de la calatori pentru a urmari miscarile si imputinarea membrilor Brotherhood in regiune."}},faq={{q="De ce poarta Defias bandane din piele rosie?",a="Defias poarta bandane rosii pentru a-si ascunde chipurile in timpul raidurilor asupra fermelor si drumurilor si pentru a-si arata loialitatea fata de rascoala lui Edwin VanCleef impotriva Stormwindului.",al={"masca Defias","de ce bandana rosie","semnificatia bandanei Defias"}},{q="Cine vrea sa fie adunate aceste bandane in Westfall?",a="Cercetasul Galiaan din People's Militia de la Sentinel Hill le cere calatorilor sa adune bandanele. Le foloseste pentru a urmari miscarile bandei si a confirma moartea banditilor care dau tarcoale.",al={"cine preia bandanele rosii","misiunea cu bandana a lui Galiaan","predarea bandanei la Sentinel Hill"}},{q="Unde pot fi gasite aceste bandane?",a="Rogue, talhari de drumul mare si contrabandisti Defias poarta aceste bandane prin tabere, campuri si mine din Westfall.",al={"prada bandanei rosii","fa rost de bandane rosii","cine lasa bandana rosie de piele"}}},fp="19,153,23.377.1,44.150.1,47.180.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="Red Linen Bandana",s="Prin padurea Elwynn Forest, Red Linen Bandana ii identifica pe cei din Defias Brotherhood. Panza ascunde fata celui care o poarta si poate fi folosita de colonistii din zona.",h="Prin padurea Elwynn Forest, Red Linen Bandana ii identifica pe cei din Defias Brotherhood.",kw={"masca Defias","Eastvale","Elwynn Forest","in","bandana rosie din in","Sara Timberlain"},ang={["class:Rogue"]="Ca rogue, recunosti panza stacojie legata peste partea de jos a fetei drept insemnul talharilor si al hotilor de buzunare din padurile din jurul capitalei.",["profession:Tailoring"]="In Elwynn rural, tesatorii pot folosi panza de in in mastile banditilor, ca imbracaminte de lucru."},sec={{t="Semnul Defias",b="In tot Elwynn Forest, agentii Defias cu rang inalt poarta bandane tesute din in rosu. In Northshire Valley, initiatii de rang inferior si golanii de rand folosesc in schimb masti din panza aspra de sac. Tesatura caramizie ascunde chipul si arata apartenenta la confreria razvratita a lui Edwin VanCleef. E si un semn al razmeritei lor impotriva coroanei Stormwind."},{t="Panza refolosita",b="Sara Timberlain de la Eastvale Logging Camp le cere calatorilor sa adune bandane din taberele proscrisilor. Desi sunt legate de banditi, mastile sunt facute din in de buna calitate. Dupa spalare si cusut, colonistii pot transforma materialul in haine rezistente si bandaje pentru oamenii care muncesc in padure."}},faq={{q="De ce poarta Defias bandane din in rosu?",a="Agentii Defias poarta bandane rosii de in pentru a-si ascunde chipul si a-si arata loialitatea fata de fratia lui Edwin VanCleef si sfidarea fata de Stormwind.",al={"semnificatia mastii Defias","de ce masti rosii","batic rosu Defias"}},{q="Prin ce se deosebesc acestea de mastile purtate in Northshire?",a="Batausii din Northshire Valley poarta masti aspre de panza de sac, pe cand agentii Defias cu vechime din Elwynn Forest poarta in schimb in rosu mai fin.",al={"panza de sac sau in","mastile din Northshire","bandana din panza de sac"}},{q="Cine vrea sa colecteze aceste bandane?",a="Sara Timberlain de la Eastvale Logging Camp vrea bandanele. Le spala si le desira ca sa teasa haine practice.",al={"cine preia bandanele rosii din in","bandana lui Sara Timberlain","predarea misiunii cu bandana"}},{q="Ce dusmani poarta bandane rosii din in?",a="Agentii Defias din Elwynn Forest poarta bandane rosii din in, inclusiv Defias Bandits, Ambushers, Rogue Wizards, docheri si capetenii precum Morgan the Collector.",al={"cine lasa bandana rosie de in","unde gasesti bandane","bandane lasate de Defias"}}},fp="17,144,18.320.0,16.293.0,42.140.0,54.128.0,36.127.0,39.175.0"}
P.entries["item:red-wool-bandana"] = {n="Red Wool Bandana",s="Red Wool Bandanas sunt simboluri improvizate faurite de talharii Defias intemnitati in Stormwind Stockade. Rupte din paturile de lana ale inchisorii, ele servesc drept embleme sfidatoare ale fraternitatii, chiar si dupa gratii.",h="Red Wool Bandanas sunt simboluri improvizate faurite de talharii Defias intemnitati in Stormwind Stockade.",kw={"Defias","Mac Raskol","Nikova Raskol","bandana rosie din lana","Stormwind","Color of Blood","The Stockade"},ang={["faction:Alliance"]="Pentru aparatorii Alliance, recuperarea acestor bandane este un act sumbru de dreptate pentru tanarul Mac Raskol si o lovitura data razvratitilor care tin inchisoarea orasului.",["profession:Tailoring"]="Aceste bandane aspre, croite rudimentar, arata cum chiar si paturile din lana grosolana pot fi destramate si refolosite de maini disperate aflate in captivitate."},sec={{t="Cusut in semn de sfidare",b="Chiar si inchisi in spatele zidurilor inalte de piatra ale Stormwind Stockade, membrii Defias Brotherhood refuza sa renunte la identitatea lor. Folosind bucati rupte din paturile de lana ale inchisorii, detinutii confectioneaza pe ascuns bandane rosii, pe care le poarta ca semn distinctiv. Pentru gardieni, aceste esarfe sunt obiecte de contrabanda care starnesc revolte mortale; pentru prizonieri, ele dovedesc ca fratia si rascoala lor dainuie, chiar si in lanturi."},{t="Razbunarea unei bunici",b="Baticurile au capatat o reputatie amara dupa ce Mac Raskol, un gardian al inchisorii in varsta de paisprezece ani, i-a surprins pe detinuti sfasiind paturi pentru a le confectiona. Cand a incercat sa-i disciplineze, condamnatii Defias l-au injunghiat pe la spate. Dupa moartea lui, bunica sa indurerata, Nikova, cauta aventurieri dispusi sa intre in temnita rasculata, sa-i infrunte pe razvratiti si sa aduca inapoi panza stacojie drept dovada a razbunarii."}},faq={{q="De unde iau prizonierii aceste bandane din Stockade?",a="Detinutii Defias le confectioneaza sfasiindu-si paturile de lana primite in inchisoare. Desi dezarmati si inchisi, ei isi transforma putinele asternuturi in simboluri ale nesupunerii, purtate in celule.",al={"de unde provin bandanele","sursa bandanei Stockade","cum se fac bandanele rosii"}},{q="Cine doreste sa fie adunate aceste bandane?",a="Nikova Raskol, o bunica indurerata din Stormwind, le cere aventurierilor sa le stranga. Nepotul ei de paisprezece ani, Mac, era strajer la Stockade si a fost ucis de prizonieri dupa ce i-a prins confectionand bandanele.",al={"cine are nevoie de bandane rosii de lana","cine ofera misiunea Color of Blood","bandana pentru Nikova Raskol"}},{q="De ce le pasa atat de mult prizonierilor sa poarte esarfe rosii?",a="Defias Brotherhood poarta masti si bandane rosii, culorile si uniforma principala a bandei. In spatele gratiilor, confectionarea si purtarea acestor zdrente le permit detinutilor sa-si pastreze rangul, moralul si unitatea.",al={"de ce bandane rosii","simbolul rosu al Defias","semnificatia bandanei rosii"}},{q="Ce detinuti le poarta?",a="Aproape orice membru Defias care provoaca revolte in Stockade poarta asa ceva, inclusiv Defias Captives, Inmates, Prisoners, Insurgents si Convicts.",al={"cine lasa bandanele rosii de lana","de unde se obtin bandanele din stockade"}}},fx={["7f0c1a2a"]={q="Ce este o Red Wool Bandana?",a="Red Wool Bandana este o esarfa stacojie improvizata de membrii incarcerati ai Defias Brotherhood, in Stormwind Stockade. Destramand si vopsind paturile de lana primite de la inchisoare, detinutii confectioneaza aceste insemne de panza pentru a-si arata deschis loialitatea fata de Brotherhood si a-si pastra identitatea de banda chiar si dupa gratii.",al={"ce este bandana rosie de lana","obiectul bandana rosie de lana","bandana rosie de la Stockade"}}},fp="16,210,20.424.0,25.415.0,54.196.0,35.205.0,60.197.0,25.142.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Remaining Drops of Purest Water"}
P.entries["item:remedy-of-arugal"] = {n="Remedy of Arugal",s="Remedy of Arugal este o incantatie scrisa de magul Arugal in timpul primelor sale experimente cu magia worgenilor. Lasata intr-o ferma darapanata din Silverpine Forest, vraja este cautata de Dalar Dawnweaver pentru a descalci lucrarea intunecata a vrajitorului.",h="Remedy of Arugal este o incantatie scrisa de magul Arugal in timpul primelor sale experimente cu magia...",kw={"arugal","nebunia lui arugal","dalar dawnweaver","carti de vraji prafuite","moonrage","remedy of arugal","sepulcher","silverpine forest"},ang={["class:Mage"]="Magii Forsaken vor impartasi dispretul profesional al lui Dalar Dawnweaver fata de experimentele stangace si nechibzuite ale lui Arugal, dar vor recunoaste primejdia inerenta invocarilor arcane necontrolate.",["race:Undead"]="Pentru Forsaken, obtinerea acestei vraji este un pas timpuriu, dar esential, in respingerea worgenilor salbatici care ameninta granitele Silverpine Forest."},sec={{t="Resturile unui Mage",b="Inainte sa puna stapanire pe Shadowfang Keep, Archmage Arugal s-a adapostit la o ferma de grau abandonata, la nord de podul peste rau din Silverpine Forest. Acolo, printre unelte agricole uitate si podele putrezite, si-a consemnat artele neobisnuite intr-un set de carti de vraji prafuite. Pergamentul intitulat Remedy of Arugal se numara printre aceste insemnari si descrie metode timpurii si formule magice pe care le-a conceput in timp ce experimenta cu transmutatiile primejdioase ce au blestemat populatia locala."},{t="Cercetarea Forsaken",b="Dalar Dawnweaver, un vrajitor Forsaken desavarsit care isi desfasoara activitatea din Sepulcher, nu are prea mare respect pentru obarsia lui Arugal, considerand intelectul fostului vrajitor din Dalaran fragil si usor de patruns. Chiar si asa, Dawnweaver intelege ca este urgent sa afle mecanismele exacte ale blestemului worgen. Recuperand Remedy of Arugal, agentii Forsaken ii ofera lui Dawnweaver cunostintele arcane fundamentale de care are nevoie pentru a contracara amenintarea tot mai mare a lui Arugal si a asigura Silverpine pentru Lady Sylvanas."}},faq={{q="Ce este Remedy of Arugal?",a="Este o formula magica scrisa de magul renegat Arugal. Nu este o potiune vindecatoare, ci o vraja scrisa care contine tehnicile arcane folosite de el cand a inceput sa experimenteze cu magia worgen in Silverpine Forest.",al={"ce este Remedy of Arugal","obiectul Remedy of Arugal","vraja Remedy"}},{q="Unde a fost lasat Remediul?",a="Arugal l-a lasat printre carti de vraji prafuite, la etajul superior al unei ferme de grau abandonate, aflata chiar la nord de podul care traverseaza raul din Silverpine Forest.",al={"unde gasesti Remedy of Arugal","locatia lui Remedy of Arugal","farmeaza cartea de vraji"}},{q="De ce vrea Dalar Dawnweaver aceasta vraja?",a="Dalar Dawnweaver vrea sa analizeze magia anume folosita de Arugal, astfel incat Forsaken sa poata dezvolta mijloace de contracarare, sperand sa intoarca impotriva vrajitorului propriile sale metode si sa asigure regiunea.",al={"de ce vrea Dalar leacul","leacul lui Dalar Dawnweaver"}},{q="Cine pazeste cartile de vraji de la ferma?",a="Ferma este napadita de slugile lupine ale lui Arugal. Cand cineva incearca sa tulbure cartile de vraji prafuite de la etajul al doilea, un alergator intunecat Moonrage sare din umbra pentru a apara lucrurile stapanului sau.",al={"ce ataca la ferma","ambuscada cartii de vraji"}}},fx={["157696b2"]={q="De unde provine Remedy of Arugal si cine a facut-o?",a="Remedy of Arugal este o incantatie scrisa chiar de Archmage Arugal in primele sale zile petrecute in Silverpine Forest. Dupa ce planurile sale au inceput sa se desfasoare, a locuit pentru scurt timp la o ferma de grau de la nord de podul principal peste rau, lasand in urma carti de vraji prafuite, care contineau cercetarile sale.",al={"cine a facut Remedy of Arugal","originea Remedy of Arugal","de unde provine Remedy of Arugal"}}},fp="16,250,18.455.0,17.498.0,29.235.0,33.172.0,42.198.0,38.205.0"}
P.entries["item:rendered-spores"] = {n="Rendered Spores",s="Rendered Spores sunt o emulsie volatila preparata din mostre de ciuperci adunate prin Barrens. Creata de Apothecary Helbrim la Crossroads, compozitia se descompune rapid daca nu este dusa fara intarziere la Apothecary Zamah, sub Thunder Bluff, pentru stabilizare.",h="Rendered Spores sunt o emulsie volatila preparata din mostre de ciuperci adunate prin Barrens.",kw={"apothecary helbrim","apothecary zamah","barrens","crossroads","emulsie","pools of vision","spori preluati","thunder bluff"},ang={["race:Tauren"]="Prezenta apotecarilor Forsaken care experimenteaza pe flora neobisnuita din Barrens, in interiorul sacrelor Pools of Vision, reflecta alianta dificila, dar practica, faurita in Thunder Bluff.",["race:Undead"]="Royal Apothecary Society cauta necontenit noi compusi biologici prin Kalimdor, pentru a-i ajuta pe cei din Forsaken, si se bazeaza pe curieri rapizi care sa tina legatura dintre cercetatorii de teren precum Helbrim si specialistii de laborator precum Zamah."},sec={{t="Un amestec volatil",b="Dupa ce obtine spori fungici ciudati de la ciupercile din apropierea oazelor umede din Barrens, Apothecary Helbrim ii prelucreaza intr-o emulsie chimica activa, numita Rendered Spores. Extractia delicata suspenda compusii puternici ai ciupercilor intr-un mediu lichid, insa solutia este instabila din punct de vedere chimic. Isi pastreaza eficienta doar patruzeci si cinci de minute, apoi se descompune si devine complet inutila pentru studiu stiintific."},{t="Livrare la Pools of Vision",b="Deoarece Helbrim nu dispune la avanpostul sau indepartat nici de instalatiile, nici de timpul necesar pentru a termina rafinarea, emulsia trebuie dusa in graba direct la colega sa Forsaken, Apothecary Zamah. Ascunsa in subteran, in Pools of Vision, sub Spirit Rise din Thunder Bluff, Zamah are echipamentele si reactivii speciali necesari pentru a sigila din nou sporii si a incheia prelucrarea lor pentru Royal Apothecary Society."}},faq={{q="La ce folosesc Rendered Spores?",a="Sunt materii fungice extrase de Apothecary Helbrim si transformate intr-o emulsie pentru cercetarile Royal Apothecary Society. Apothecary Zamah foloseste acest amestec puternic in Thunder Bluff pentru a-si continua investigatia asupra cresterilor stranii care se raspandesc prin Barrens.",al={"scopul sporilor procesati","ce face Zamah cu sporii","de ce sunt procesati sporii"}},{q="De ce are emulsia o limita de timp?",a="Emulsia chimica creata de Helbrim este foarte volatila si incepe sa se degradeze de indata ce este amestecata. Isi pastreaza eficienta doar patruzeci si cinci de minute, asa ca un curier trebuie sa o transporte repede peste campii pana la Thunder Bluff, inainte sa devina inerta.",al={"de ce sunt sporii prelucrati temporizati","de ce expira sporii","durata sporilor prelucrati"}},{q="Cine a creat acesti spori?",a="Apothecary Helbrim, un cercetator Forsaken stationat la Crossroads, in regiunea Barrens, a transformat sporii fungici cruzi, adunati de la ciupercile din apropierea oazelor, in acest compus lichid instabil.",al={"cine a preparat sporii","cine prelucreaza sporii","sporii lui helbrim"}},{q="Unde trebuie dusa mixtura?",a="Sporii trebuie dusi la Apothecary Zamah. Ea locuieste in adancul Pools of Vision, un sistem de pesteri ascuns sub Spirit Rise, in capitala taurenilor, Thunder Bluff.",al={"unde duc sporii prelucrati","locatia lui Zamah","locatia Pools of Vision"}}},fx={["7897c588"]={q="Ce sunt Rendered Spores?",a="Rendered Spores sunt extractul prelucrat al ciupercilor ciudate culese din Barrens. Apothecary Helbrim a fiert si a prelucrat sporii cruzi pana i-a transformat intr-o emulsie lichida, volatila si instabila, pregatind cu grija amestecul pentru studii alchimice ulterioare ale Royal Apothecary Society.",al={"ce sunt sporii prelucrati","informatii despre sporii prelucrati"}}},fp="15,257,18.452.0,31.417.0,34.273.0,40.261.0,25.187.0,34.177.0"}
P.entries["item:renferrel-s-findings"] = {n="Renferrel's Findings",s="Renferrel's Findings este o colectie de note de cercetare adunate de Apothecary Renferrel in Silverpine Forest. Incredintate curierilor Horde, aceste documente transporta date esentiale spre sud, la Apothecary Lydon din Tarren Mill, pentru a-i ajuta pe Forsaken sa prepare New Plague.",h="Renferrel's Findings este o colectie de note de cercetare adunate de Apothecary Renferrel in Silverpine...",kw={"descoperiri","Lydon","molima noua","Renferrel","Royal Apothecary Society","Sepulcher","Tarren Mill"},ang={["faction:Horde"]="Curierii care transporta documentele lui Renferrel contribuie la consolidarea pozitiei Horde pe tot cuprinsul Lordaeron, legand avanposturi izolate precum Sepulcher si Tarren Mill.",["race:Undead"]="Cercetarile din aceste documente slujesc ambitia suprema a Sylvanas Windrunner: desavarsirea unei New Plague, menita sa nimiceasca atat Scourge, cat si dusmanii in viata care patrund pe pamanturile Forsaken."},sec={{t="O molima in dezvoltare",b="Royal Apothecary Society lucreaza fara incetare, la ordinele directe ale Dark Lady, Lady Sylvanas Windrunner, pentru a crea o New Plague. Aceasta descoperire necesita o colaborare permanenta intre cercetatorii raspanditi prin Lordaeron. Aflat la Sepulcher, in Silverpine Forest, Apothecary Renferrel aduna rezultatele pentru a-si consemna progresul si experimentele, trimitand informatiile stranse spre sud, la Tarren Mill, pentru ca ceilalti cercetatori sa-si poata cladi munca pe baza rezultatelor sale."},{t="Spre Tarren Mill",b="Ducerea acestor hartii peste granita, din Silverpine in Hillsbrad Foothills, este o veriga vitala in reteaua alchimica a celor din Forsaken. In Tarren Mill, Apothecary Lydon asteapta cu nerabdare insemnarile lui Renferrel, ca sa le compare cu propriile retete si sa le imbunatateasca impotriva celor vii si a Scourge. Fara curieri de incredere care sa strabata drumurile disputate din Hillsbrad, cercetarea descentralizata a Societatii s-ar opri repede."}},faq={{q="Ce contine Renferrel's Findings?",a="Pachetul contine cele mai recente date experimentale si notite de cercetare adunate de Apothecary Renferrel in timpul activitatii sale din Silverpine Forest, in special despre sinteza unei New Plague pentru Forsaken.",al={"care sunt descoperirile","cercetarile lui Renferrel","ce contin notitele"}},{q="Cine ar trebui sa primeasca aceasta cercetare?",a="Apothecary Lydon primeste documentele. El cerceteaza molima in Tarren Mill, o asezare Forsaken din Hillsbrad Foothills.",al={"cine primeste descoperirile lui Renferrel","unde ajung descoperirile","destinatia livrarii"}},{q="De ce impart alchimistii notite?",a="Lady Sylvanas Windrunner exercita o presiune enorma asupra Royal Apothecary Society pentru a inventa New Plague. Alchimistii cred ca vor obtine mult mai repede descoperirea dorita daca se coordoneaza si isi compara rezultatele, in loc sa lucreze izolat.",al={"de ce sa impartasim descoperirile","de ce sa le trimitem lui Lydon","comunicarea dintre apotecari"}},{q="Unde isi desfasoara Apothecary Renferrel experimentele?",a="Apothecary Renferrel este stationat la Sepulcher, principalul avanpost Forsaken, aflat in inima regiunii Silverpine Forest.",al={"unde este Renferrel","locatia lui Apothecary Renferrel","cine a scris descoperirile lui Renferrel"}}},fx={f680c460={q="Ce sunt Renferrel's Findings?",a="Renferrel's Findings sunt o colectie de insemnari alchimice si documente de cercetare adunate de Apothecary Renferrel. Ele descriu experimentele sale in curs, desfasurate in numele Royal Apothecary Society, si sunt menite sa fie impartasite direct colegilor sai din Lordaeron.",al={"ce sunt descoperirile lui Renferrel","obiectul descoperirile lui Renferrel","ce sunt aceste descoperiri"}},bf8d559a={q="De unde provin Renferrel's Findings si cine le-a facut?",a="Aceste documente au fost scrise de Apothecary Renferrel, un cercetator ambitios stationat la Sepulcher, in Silverpine Forest. Lucrand cu sarguinta sub autoritatea Forsaken, el a redactat aceste insemnari pentru a-si consemna progresul si descoperirile in prepararea unor potiuni experimentale.",al={"cine a scris descoperirile lui renferrel","de unde provin descoperirile lui renferrel","creatorul descoperirilor lui renferrel"}},["21b2c0f4"]={q="De ce ar vrea cineva Renferrel's Findings?",a="Royal Apothecary Society se afla sub o presiune uriasa din partea lui Lady Sylvanas Windrunner, care le cere sa creeze New Plague. Crezand ca o colaborare le va grabi munca sumbra, Renferrel si-a trimis cercetarile la Apothecary Lydon din Tarren Mill, dornic sa studieze metodele colegului sau si sa le integreze in propriile eforturi.",al={"de ce trebuie livrate descoperirile lui renferrel","cine vrea descoperirile lui renferrel","de ce vrea lydon descoperirile lui renferrel"}}},fp="20,264,23.486.0,14.425.0,36.213.0,41.143.0,39.254.0,56.123.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Report on the Defias Brotherhood",s="La Stormwind Keep, un raport despre Defias Brotherhood prezinta curtii regale concluziile unei anchete indelungate. City Architect Baros Alexston il incredinteaza aventurierului care a descoperit conspiratia.",h="La Stormwind Keep, un raport despre Defias Brotherhood prezinta curtii regale concluziile unei anchete...",kw={"audienta cu regele","Baros Alexston","Defias","raport","Stormwind Keep","VanCleef","Westfall"},ang={["faction:Alliance"]="Predarea raportului aduce la curtea regala indelungata lupta pentru asigurarea securitatii in Westfall si avertizarea liderilor din Stormwind cu privire la revolta de la granite.",["race:Human"]="Ca Human al regatului, duci un raport care reflecta conflictul nerezolvat dintre casa nobiliara din Stormwind si pietrarii care au reconstruit orasul."},sec={{t="O solie pentru Tron",b="City Architect Baros Alexston a pregatit un raport pentru conducatorii din Stormwind, dupa o lunga investigatie asupra tulburarilor din Westfall si tinuturile invecinate. El a incredintat documentul aventurierului care a demascat conspiratia. Raportul este dus la Stormwind Keep, unde urmeaza sa insoteasca o audienta privata despre planurile conspiratorilor si pericolul pe care il reprezinta pentru regat."},{t="Primire la fortareata",b="Regele Varian Wrynn este plecat intr-o misiune diplomatica atunci cand curierul ajunge in sala tronului. Consilierii regali si regenta care guverneaza in numele baiatului-rege Anduin primesc raportul in locul sau. Ei il felicita pe curier pentru ca a oprit planurile lui VanCleef. Lady Katrana Prestor se numara printre personajele curtii prezente cand avertismentele ajung la regenta."}},faq={{q="Ce este Report on the Defias Brotherhood?",a="Report on the Defias Brotherhood este un raport oficial intocmit de Baros Alexston, care aduna informatii despre Edwin VanCleef, armata sa subterana si conspiratia mai ampla a Defias impotriva Stormwind.",al={"ce este acest raport","obiectul raport Defias","raportul lui Baros Alexston"}},{q="Cine a scris acest raport?",a="Baros Alexston, City Architect din Stormwind, a pregatit raportul. A lucrat candva alaturi de pietrari, inainte ca acestia sa se desprinda si sa formeze Defias Brotherhood.",al={"cine a scris raportul Defias","autorul raportului"}},{q="De ce livrez asta la Stormwind Keep?",a="Baros Alexston crede ca aventurierul care a descoperit conspiratia merita sa prezinte dovezile suveranului si sa primeasca recunoasterea regala pentru ca a aparat regatul.",al={"de ce livrez asta","audienta cu regele pentru livrare"}},{q="Citeste regele Varian raportul?",a="Nu. King Varian Wrynn este plecat intr-o calatorie diplomatica atunci cand ajungi la Stormwind Keep. Curtea si regenta lui primesc raportul in locul sau.",al={"citeste regele scrisoarea","audienta cu Varian Wrynn"}}},fp="32,208,25.379.0,21.336.1,45.195.1,22.160.1,43.167.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="Resonite Crystal",s="Resonite Crystals sunt mostre minerale rare, extrase de kobolzi din Boulderslide Cavern, in Stonetalon Mountains. Sapatul lor frenetic a atras atentia lui Mor'rogal din Sun Rock Retreat.",h="Resonite Crystals sunt mostre minerale rare, extrase de kobolzi din Boulderslide Cavern, in Stonetalon...",kw={"Boulderslide","cristal","fiinte de piatra","kobold","Mor'rogal","Resonite","Stonetalon","titani"},ang={["class:Shaman"]="Resonite Crystals au o rezonanta tulburatoare pentru shaman, care pot recunoaste magia pamantului latenta si primordiala, lasata in urma de creatiile Titan, ingropate de mult sub munti.",["profession:Mining"]="Spre deosebire de filoanele obisnuite de cupru sau staniu, Resonite este o formatiune minerala extrem de concentrata, a carei extragere impune patrunderea dincolo de kobolzii agresivi, pana in cele mai adanci straturi subterane."},sec={{t="Rezonanta straveche",b="Ascunse in adancurile Boulderslide Ravine, Resonite Crystals au devenit tinta sapaturilor bruste si febrile ale koboldilor. Minerii obisnuiti din pesteri cauta de regula minereuri banale sau maruntisuri stralucitoare, dar obsesia koboldilor pentru aceste formatiuni anume i-a alarmat imediat pe samanilor din Sun Rock Retreat. Cercetate indeaproape, pietrele vibreaza cu o rezonanta magica subtila, legata de modelarea primordiala a lumii. Mor'rogal a identificat aceste energii slabe drept urme ale magiei Earthen, semn ca fapturile sapatoare au dat peste un strat stravechi creat de Titani."},{t="Atingerea pamantului",b="Descoperirea Resonite confirma o veste ingrijoratoare pentru prezenta Horde in Stonetalon: sapatorii kobold au sapat suficient de adanc incat sa-i tulbure pe Earthen cei stravechi. Intrucat Earthen au fost modelati direct de Titani pentru a sculpta si plamadi temeliile lumii, magia reziduala ramane cu indaratnicie in roca din jur. Adunand aceste cristale, agentii Horde spera sa descifreze intentiile febrile ale koboldilor si sa intoarca puterea pietrei fermecate impotriva fortelor adormite care au fost trezite in adancuri."}},faq={{q="Unde se gasesc Resonite Crystals?",a="Resonite Crystals se gasesc in Boulderslide Cavern, o pestera adanca aflata in Boulderslide Ravine, in partea de sud-est a Stonetalon Mountains.",al={"locatia resonite","de unde obtin resonite","unde farmez cristalul resonite"}},{q="De ce mineaza kobolzii Resonite Crystals?",a="Kobolzii extrag frenetic cristalele rare, dar Mor'rogal nu stie inca de ce. El cere mostre si o cercetare a adancurilor pesterii pentru a le intelege activitatea.",al={"de ce mineaza koboldii","planul cristalului kobold","koboldii Boulderslide"}},{q="Ce fel de putere se afla intr-un Resonite Crystal?",a="Mor'rogal banuieste ca cristalele au legatura cu ceva ingrijorator de sub munti. Natura lor magica este identificata dupa ce ajung la el mostre si vesti din pestera.",al={"magia cristalului de resonit","ce este resonitul","este resonitul magic"}},{q="Cine studiaza aceste cristale?",a="Mor'rogal, un tauren aflat la Sun Rock Retreat in Stonetalon Mountains, cerceteaza cristalele pentru a intelege cresterea brusca a activitatii koboldilor si a gasi o modalitate de a combate raul care a fost descoperit.",al={"cine vrea resonita","cristalele din Mor'rogal","resonita din Sun Rock Retreat"}},{q="Cine sunt Earthen, mentionati in legatura cu cristalul?",a="Earthen sunt creaturi despre care se spune ca au fost create de Titani pentru a modela pamantul. Posibila lor legatura cu Resonite este investigata in timpul misiunii lui Mor'rogal.",al={"ce sunt earthen","legatura dintre earthen si titani"}}},fx={c14b6c8c={q="Ce este Resonite Crystal?",a="Resonite este un cristal mineral rar, gasit in Boulderslide Cavern din Stonetalon Mountains. Mineritul frenetic al koboldilor l-a alarmat pe Mor'rogal, care cere mostre si vesti din pestera pentru a o cerceta.",al={"ce este resonite","povestea cristalului resonite","minereu de resonite"}},af246400={q="De ce ar vrea cineva Resonite Crystal?",a="Mor'rogal vrea mostre de minereu pentru a intelege mineritul frenetic al kobolzilor si a afla ce se ascunde sub Boulderslide Ravine. Ii cere unui aventurier sa exploreze pestera si sa adune cristalele.",al={"de ce sa aduni cristale Resonite","cine vrea cristalul Resonite","scopul cristalului Resonite"}}},fp="16,193,17.587.1,17.518.1,34.159.0,45.182.0,44.176.0,31.214.0,60.164.0"}
P.entries["item:restabilization-cog"] = {n="Restabilization Cog"}
P.entries["item:ring-of-zoram"] = {n="Ring of Zoram",s="Ring of Zoram este o mostenire straveche Kaldorei, datand din zilele de glorie ale orasului scufundat Zoram, de dinainte de Great Sundering. Purtat odinioara de conducatorii orasului si fiind cheia vechii incuietori a unei statuete scufundate, a ajuns recent in mainile nagelor care inainteaza de-a lungul coastei.",h="Ring of Zoram este o mostenire straveche Kaldorei, datand din zilele de glorie ale orasului scufundat Zoram...",kw={"statueta antica","Ashenvale","Lady Vespia","Ring of Zoram","Ruuzel","Talen","Zoram Strand"},ang={["faction:Alliance"]="Recuperarea inelului de la naga il ajuta pe savantul Night Elf Talen sa recupereze istoria kaldorei furata de-a lungul granitelor disputate din Ashenvale.",["race:NightElf"]="Inelul reprezinta o dovada palpabila a mostenirii de dinaintea Scindarii, dintr-o epoca in care imperiul Kaldorei nu fusese inca sfasiat de trufia arcana si de marile care l-au inghitit."},sec={{t="Inelul orasului scufundat",b="Inainte ca Well of Eternity sa se prabuseasca, iar oceanele sa inghita tinuturile vestice ale Kalimdorului, Zoram era o nestemata de coasta a imperiului elfilor noptii. Ring of Zoram apartinea conducatorilor orasului, iar pe banda interioara era inscris un cod straniu, in limba elfilor noptii. Cand Great Sundering a sfaramat continentul acum zece mii de ani, inelul s-a scufundat odata cu orasul, pierzandu-se sub valurile care izbesc astazi tarmurile Zoram Strand."},{t="Recucerirea de catre Naga",b="Timp de milenii, inelul a ramas ingropat sub namol si ruine, pana cand naga au inceput sa scotoceasca tarmul Ashenvale. Ruuzel, o conducatoare naga care locuieste pe o insulita de langa tarmul nordic, a descoperit artefactul printre ramasitele scufundate. Scolari precum elf-ul noptii Talen cauta inelul nu doar pentru vechimea sa, ci si pentru ca este singura cheie capabila sa descuie alte relicve recuperate din adancuri, inclusiv statuete antice sigilate, scoase de pe fundul marii."}},faq={{q="La ce foloseste Ring of Zoram?",a="Inelul le-a apartinut conducatorilor din Zoram inainte ca Scindarea sa scufunde orasul si este cheia unei incuietori antice. In prezent, Talen il cauta anume pentru a deschide o statueta antica incuiata, recuperata din ruinele subacvatice.",al={"scopul lui Ring of Zoram","ce face inelul","povestea lui Ring of Zoram"}},{q="Cine detine Ring of Zoram?",a="Inelul a fost scos din ruine de nagi de coasta care au invadat Zoram Strand. Este pastrat mai ales de conducatoarea lor, Ruuzel, pe o insula din largul coastei nordice, desi se stie ca si o alta naga de seama, Lady Vespia, il poarta uneori.",al={"cine are inelul","prada Ring of Zoram","de unde iei Ring of Zoram"}},{q="De ce vrea Talen inelul?",a="Talen vrea sa descopere secretele statuetei antice recuperate de pe Zoram Strand. Fara Ring of Zoram, care ii serveste drept cheie, mecanismul antic al statuetei nu poate fi deschis.",al={"de ce vrea talen inelul","misiunea inelului lui talen"}},{q="Unde a disparut orasul Zoram?",a="Zoram a fost un oras stravechi al Night Elf, aflat pe marginea vestica a Kalimdorului inainte de Great Sundering, acum zece mii de ani. Cand Well of Eternity s-a prabusit, orasul a fost distrus si inghitit de ape, lasand in urma doar Zoram Strand.",al={"ce s-a intamplat cu Zoram","povestea orasului Zoram"}}},fx={["7e40c0d5"]={q="Ce este Ring of Zoram?",a="Ring of Zoram este o relicva straveche purtata candva de conducatorii orasului scufundat Zoram, inainte ca valurile din Great Sundering sa-l inghita. Un cod ciudat este inscris pe interiorul verighetei, in limba elfilor noptii, iar inelul este cheia incuietorii stravechi a unei statuete recuperate din ruine.",al={"ce este Ring of Zoram","povestea lui Ring of Zoram","obiectul Ring of Zoram"}},["770adfa7"]={q="De unde provine Ring of Zoram si cine l-a creat?",a="Inelul provine din orasul elfilor noptii Zoram, de dinainte de Sundering, aflat pe coasta stravechiului Kalimdor. A apartinut conducatorilor orasului inainte ca valurile catastrofale sa-l inece pe Zoram, acum zece mii de ani, pierzand relicva in mare pana cand naga au scos-o recent la iveala dintre ruine.",al={"originea Ring of Zoram","cine a creat Ring of Zoram","de unde provine Ring of Zoram"}}},fp="13,286,23.461.0,23.481.0,35.236.0,32.242.0,29.189.0,31.264.0"}
P.entries["item:robo-mechanical-guts"] = {n="Robo-Mechanical Guts"}
P.entries["item:rocket-car-parts"] = {n="Rocket Car Parts",s="Rocket Car Parts sunt ramasitele imprastiate de metal rasucit, provenite din coliziuni de mare viteza in Shimmering Flats, in Thousand Needles. Generate constant de pilotii gnomi si goblini imprudenti, care-si imping vehiculele experimentale dincolo de limite, aceste resturi recuperabile sunt adunate de profitori ce vor sa transforme accidentele de pe pista in bani castigati usor.",h="Rocket Car Parts sunt ramasitele imprastiate de metal rasucit, provenite din coliziuni de mare viteza in...",kw={"inginerie","gnome","goblin","kravel koalbeard","mirage raceway","rocket car parts","recuperare","shimmering flats","thousand needles"},ang={["profession:Engineering"]="Mormanul de angrenaje arse si ansambluri de evacuare zdrobite, raspandite pe campurile sarate, sta marturie a extremelor haotice ale filozofiei ingineresti a gnomilor si goblinilor.",["race:Dwarf"]="In vreme ce gnomes si goblins nu se intereseaza decat de cursa, Dwarves intreprinzatori precum Kravel Koalbeard dovedesc ca adevaratul profit se afla in scotocirea epavelor ramase in urma lor."},sec={{t="Viteza, epave si comert iscusit",b="Mirage Raceway din Shimmering Flats este locul de pornire al unei rivalitati nesfarsite si explozive intre ingineria practicata de goblin si cea practicata de gnome. In goana dupa o viteza terestra fara egal, pilotii sufera adesea avarii catastrofale, rateuri explozive si ciocniri la viteza mare, care imprastie metalul pe intinderile sarate. Resturile abandonate - de la cilindri indoiti si roti dintate arse la foi de tabla strivite - nu raman multa vreme fara stapan. Scormonitorii si negustorii, mai ales dwarf-ul oportunist Kravel Koalbeard, platesc aventurieri aflati in trecere sa scotoceasca intinderea alba orbitoare si sa adune ramasitele. Pentru ca ambele echipe de curse au mereu nevoie disperata de piese de schimb cu care sa-si peticeasca urmatorul prototip, resturile recuperate pot fi revandute cu usurinta chiar echipelor care le-au facut praf."}},faq={{q="De unde provin toate aceste piese de masina-racheta?",a="Acestea sunt urmele nenumaratelor accidente, explozii si defectiuni mecanice de la Mirage Raceway. Pilotii gnomi si goblini isi distrug in mod regulat vehiculele experimentale, instabile si propulsate de rachete, pe intinsele saline din Thousand Needles.",al={"de ce sunt piese pe saline","originea resturilor de masina-racheta","de unde provin piesele"}},{q="Cine cumpara aceste deseuri recuperate?",a="Negustori precum dwarf-ul Kravel Koalbeard aduna epavele lasate de calatori si revand mecanismele, blindajul si dispozitivele recuperate gnomilor si goblinilor, care au mereu nevoie de materiale de rezerva pentru a-si repara si imbunatati masinile de curse.",al={"cine vrea piesele masinii-racheta","piesele de racheta ale lui Kravel Koalbeard","cine cumpara epava"}},{q="Sunt periculoase de recuperat aceste parti?",a="Epava in sine este inerta, desi uneori poarta semne sumbre ale unor ciocniri violente, precum membre sectionate prinse in metal. Principalul pericol vine de la vietuitoarele ostile de pe campurile de sare, inclusiv basilici, scorpizi arsi si vulturi pradatori de sare, care dau tarcoale campurilor de resturi.",al={"este sigur sa ridici piesele","pericolele intampinate cand aduni piese"}},{q="Le pasa gnomilor si goblinilor ca piesele provin din masini prabusite?",a="Nicidecum. Nici concurentii gnomi, nici cei goblini nu se formalizeaza din cauza materialelor reciclate. Singura lor prioritate este sa obtina mecanisme, roti dintate si blindaj metalic utilizabil, pe care sa-l asambleze suficient de repede pentru a se depasi unii pe altii pe pista.",al={"le pasa pilotilor de resturi","de ce refolosesc goblinii vechiturile"}}},fx={["9a01e74a"]={q="Ce sunt Rocket Car Parts?",a="Sunt resturile imprastiate in urma accidentelor de mare viteza de pe Shimmering Flats. Alcatuite din roti dintate, cilindri, placi de metal indoite si mecanisme recuperate, aceste fiare au fost candva prinse cu suruburi de masinariile experimentale si zgomotoase construite de goblini si gnomi vitezomani, aflati in competitie la Mirage Raceway.",al={"ce sunt piesele masinii cu racheta","povestea pieselor masinii cu racheta","ce sunt piesele acestea"}}},fp="16,342,34.812.0,46.251.0,31.246.0,36.309.0,68.237.0"}
P.entries["item:rod-of-channeling"] = {n="Rod of Channeling"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Rolf and Malakai's Medallions",s="Rolf and Malakai's Medallions poarta insemnul regatului, dar proprietarii lor au disparut in timpul unei patrule in estul Elwynn Forest. Guard Thomas cauta aceste obiecte pentru a afla ce s-a intamplat cu oamenii sai.",h="Rolf and Malakai's Medallions poarta insemnul regatului, dar proprietarii lor au disparut in timpul unei...",kw={"Eastvale","Elwynn","Guard Thomas","Malakai","medalioane","murloc","Rolf","garzile din Stormwind"},ang={["faction:Alliance"]="Chiar si in inima Alliance, gardienii locali se confrunta cu primejdii mortale in timp ce pazesc rutele comerciale rurale.",["race:Human"]="Pentru oamenii din Elwynn, aceste insemne marcheaza pierderea fiilor si aparatorilor lor. Moartea lor arata vulnerabilitatea regatului, in timp ce armata sa este ocupata in alta parte."},sec={{t="O confirmare sumbra",b="Guard Thomas, comandantul postului din estul Elwynn, se astepta la ce era mai rau cand Rolf si Malakai au disparut de-a lungul malurilor raului. Medalioanele lor confirma ca gardienii au murit de mana murlocilor care inainteaza. Pentru garnizoana Stormwind, aceste insemne marcheaza pierderea soldatilor care au tinut piept amenintarilor din salbaticie, in timp ce armata regatului era raspandita si slabita."},{t="Semne ale slujirii",b="Garzile Human care patruleaza orasele si tinuturile rurale poarta medalioane de identificare ce le atesta loialitatea si autoritatea sub coroana. Returnarea insemnelor lui Rolf si Malakai catre Guard Thomas ii permite sa tina socoteala oamenilor disparuti, sa le consemneze sacrificiul in raportul de teren si sa avertizeze asupra triburilor de murloc agresive care se stabilesc in apropierea drumurilor comerciale."}},faq={{q="Ce sunt Rolf and Malakai's Medallions?",a="Sunt jetoanele de identificare pentru serviciu purtate de Rolf si Malakai, gardieni din Stormwind, care au fost atacati prin surprindere si ucisi de murloci in timp ce erau de serviciu in estul Elwynn Forest.",al={"ce sunt medalioanele","medalionul lui Rolf","medalionul lui Malakai"}},{q="Cui apartin aceste medalioane?",a="Ii apartineau garzilor Rolf si Malakai, aflati sub comanda lui Guard Thomas pentru a supraveghea raul si drumurile dintre Goldshire si Eastvale Logging Camp.",al={"cine au fost Rolf si Malakai","ai cui sunt medalioanele"}},{q="Cui ar trebui sa-i duc aceste medalioane?",a="Du-le la Guard Thomas, care sta de paza la podul estic de pe drumul dintre Goldshire si Eastvale Logging Camp.",al={"cine vrea medaliile","unde le predau","predarea medalionului"}},{q="De ce sunt aceste medalioane importante pentru Guard Thomas?",a="Guard Thomas a trimis ambii gardieni in patrulare si se temea ca avusesera un sfarsit groaznic. Medalioanele lor le confirma moartea, permitandu-i sa le consemneze sacrificiul si sa avertizeze Stormwind despre amenintarea tot mai mare a murlocilor.",al={"de ce ii vrea thomas","reactia lui guard thomas"}}},fp="29,181,19.359.0,17.336.0,39.158.1,34.148.0,39.126.0,51.197.1"}
P.entries["item:rot-blossom"] = {n="Rot Blossom",s="Rot Blossoms sunt plante putrede, necrotice, care cresc printre mormintele pangarite din Duskwood. Hranite de solul napadit de blestem si de ramasitele celor undead, sunt cautate pentru proprietatile lor alchimice puternice si nesanatoase.",h="Rot Blossoms sunt plante putrede, necrotice, care cresc printre mormintele pangarite din Duskwood.",kw={"althea ebonlocke","Darkshire","Duskwood","floare putrezita","demon scheletic","oroare scheletica","cimitirul din Tranquil Gardens","suc de zombie"},ang={["faction:Alliance"]="Sa te aventurezi pe pamantul blestemat pentru a culege aceste flori lugubre inseamna si sa-i slujesti pe Night Watch, ajutand la mentinerea granitelor din Darkshire libere de scheletele lacome.",["profession:Herbalism"]="Spre deosebire de ierburile obisnuite, hranite de lumina si ploaie, Rot Blossoms sunt anomalii botanice respingatoare, hranite doar de putregaiul necrotic si pamantul cimitirelor, oferind un sumbru studiu al florei corupte."},sec={{t="Flora criptelor",b="Coruptia nefireasca din Duskwood da nastere unei flore bizare si tulburatoare, iar nimic nu este mai nelinistitor decat Rot Blossom. Inradacinate in pamantul profanat al cimitirelor precum Tranquil Gardens Cemetery, aceste flori morbide infloresc in apropierea mortii. Zvonurile localnicilor spun ca pot prinde radacini chiar si in craniile crapate ale mortilor umblatori, mai ales ale Skeletal Horrors si Skeletal Fiends care bantuie mormintele. Pentru localnicii din Darkshire, recoltarea lor este deopotriva o corvoada lugubra si o necesitate primejdioasa, caci tulburarea pamantului inseamna infruntarea mortilor nelinistiti."},{t="Un ingredient macabru",b="In pofida naturii lor respingatoare, Rot Blossoms au un scop special in amestecurile locale. Florile contin esente intunecate necesare pentru a prepara Zombie Juice, o potiune scarboasa legata de eforturile macabre de supravietuire din Duskwood. Cei trimisi sa adune florile ajung adesea, fara sa-si dea seama, sa-i ajute pe cei din Night Watch, starpind totodata scheletele nelinistite care ratacesc prin cimitirele bantuite."}},faq={{q="Unde se gasesc Rot Blossoms?",a="Rot Blossoms cresc in solul corupt al cimitirelor din Duskwood, mai ales in Tranquil Gardens Cemetery, si se stie ca rasar din ramasitele diavolilor scheletici undead.",al={"unde cresc florile putrezite","locatia florii putrezite","gaseste flori putrezite"}},{q="La ce sunt folosite Rot Blossoms?",a="Sunt un ingredient-cheie folosit de berarii si alchimistii locali pentru a distila un amestec puternic si respingator, cunoscut drept Zombie Juice.",al={"la ce folosesc rot blossom","de ce gather rot blossoms","ce le face utile pe rot blossoms"}},{q="De ce cresc aceste flori in schelete?",a="Magia intunecata persistenta din Duskwood infecteaza atat pamantul, cat si mortii nelinistiti. Rot Blossoms se hranesc direct cu putrezirea si coruptia necrotica, reusind astfel sa creasca in craniile si cutiile toracice ale scheletelor ratacitoare.",al={"flori putrezite in cranii","floarea dintr-un schelet monstruos","floare putreda pe schelete"}},{q="Cum ajuta culegerea Rot Blossoms Darkshire?",a="Oricine se aventureaza in locuri precum Tranquil Gardens pentru a culege flori trebuie negresit sa-i doboare pe Skeletal Horrors si Fiends care bantuie tinutul, aducand o alinare binemeritata pentru Althea Ebonlocke si Night Watch, greu incercata.",al={"floarea de putregai pentru Althea Ebonlocke","floarea de putregai pentru Night Watch","ajutor pentru Darkshire"}}},fx={["93f3afdd"]={q="Ce este o Rot Blossom?",a="Rot Blossom este o ciudatenie botanica morbida, care prinde radacini prin cimitirele pustiite din Duskwood. In loc sa rasara in sol sanatos, aceste flori sinistre infloresc in mijlocul putreziciunii, germinand, dupa cum se stie, in craniile goale ale undead Skeletal Horrors si Skeletal Fiends. Imbibate de energii malefice, sunt cautate de localnici excentrici, care prepara din putreziciune licori puternice.",al={"ce sunt florile putreziciunii","obiectul floare putrezita","ce este floarea putrezita"}}},fp="11,212,19.561.0,21.398.0,32.201.0,31.119.0,40.215.0,47.242.0"}
P.entries["item:rot-hide-ichor"] = {n="Rot Hide Ichor",s="Rot Hide Ichor este un fluid corporal respingator, recoltat de la gnolii Rot Hide, strigoii care au impanzit Fenris Isle din Lordamere Lake. Apothecary Renferrel aduna mostre din aceasta substanta la Sepulcher, pentru a descoperi originea coruperii gnollilor si a concepe o strategie impotriva lor.",h="Rot Hide Ichor este un fluid corporal respingator, recoltat de la gnolii Rot Hide, strigoii care au impanzit...",kw={"Apothecary Renferrel","Fenris Isle","Lordamere Lake","gnolli Rot Hide","ichor Rot Hide","Sepulcher","padurea Silverpine"},ang={["race:Undead"]="Pentru Forsaken, studierea ichorului ofera informatii militare vitale pentru securizarea flancului estic al Silverpine si extinderea cunostintelor Royal Apothecary Society in domeniul stiintei plagilor."},sec={{t="O plaga in sange",b="Gnollii Rot Hide din Fenris Isle nu sunt niste bestii salbatice obisnuite; sunt vizibil descompusi si schimonositi de o molima supranaturala. In loc de sange obisnuit, prin vene le curge o umoare nociva, care le mentine trupurile animate. Royal Apothecary Society banuieste ca acest lichid ascunde secretul coruperii haitei si al celui care o conduce din interiorul fortaretei ruinate din Fenris Isle."},{t="Cercetarea alchimistului",b="Apothecary Renferrel strange fiole cu acest ichor pentru a-i analiza proprietatile la Sepulcher. Izoland componentele chimice si magice care ii alimenteaza pe gnolls, Forsaken spera sa le descopere punctele slabe inainte de a trimite trupe intr-un asalt total dincolo de Lordamere Lake."}},faq={{q="De unde provine Rot Hide Ichor?",a="Se aduna de pe trupurile gnolilor Rot Hide care salasluiesc pe toata insula Fenris Isle, situata in Lordamere Lake, la est de partea continentala a Silverpine Forest.",al={"unde gasesti ichor de piele putreda","cum gasesti ichor de piele putreda","locatia ichorului de gnoll"}},{q="De ce doreste Apothecary Renferrel aceasta ichor?",a="Renferrel vrea sa discece lichidul ciudat pentru a descoperi ce a corupt gnolii si a identifica orice slabiciune fizica sau alchimica de care Forsaken s-ar putea folosi inainte de a ataca insula.",al={"de ce are Renferrel nevoie de ichor","motivul misiunii lui Renferrel","scopul ichorului din pielea putreda"}},{q="Gnollii Rot Hide fac parte din Scourge?",a="Sunt gnolli strigoi deformati de molima, insa Forsaken cerceteaza in mod activ cine sau ce i-a creat si le coordoneaza prezenta pe Fenris Isle.",al={"sunt pielile putrede din Scourge","cine controleaza pielile putrede","ce sunt gnollii Rot Hide"}},{q="Au toti gnoll-ii aceasta limfa?",a="Nu. Lichidul este specific haitei Rot Hide, a carei carne si al carei sange au fost corupte de molime necromantice malefice.",al={"lasa toti gnollii ichor","sange de gnoll obisnuit"}}},fx={c332bd61={q="Ce este Rot Hide Ichor?",a="Rot Hide Ichor este un fluid straniu si nefiresc, care curge prin trupurile hienoizilor Rot Hide de pe Fenris Isle. Nu este sange obisnuit; Royal Apothecary Society crede ca aceasta substanta corupta este direct responsabila de natura rasucita, asemanatoare cu cea a mortilor vii, a hienoizilor si de rezistenta lor sporita.",al={"ce este ichorul Rot Hide","lichidul Rot Hide","ce este ichorul"}}},fp="14,276,21.387.0,19.279.0,36.146.0,46.187.0,32.161.0,30.116.0"}
