P.entries["item:rune-inscribed-pendant"] = {n="Rune-Inscribed Pendant",s="Rune-Inscribed Pendant este un talisman magic recuperat din transporturile de provizii Dalaran destinate localitatii Ambermill. Pretuite de Kirin Tor, aceste pandantive servesc drept canale pentru dirijarea unor energii arcane puternice.",h="Rune-Inscribed Pendant este un talisman magic recuperat din transporturile de provizii Dalaran destinate...",kw={"allister","ambermill","dalar dawnweaver","dalaran","kirin tor","pandantiv","pandantiv cu rune","sepulcher"},ang={["class:Mage"]="Magii recunosc cu usurinta maiestria Kirin Tor; runele gravate pe pandantiv sunt concepute pentru a stabiliza curentii instabili in timpul canalizarii vrajilor de nivel inalt.",["race:Undead"]="Pentru Forsaken care pazesc Silverpine Forest, concentratoarele de magie din Dalaran interceptate, precum acest pandantiv, ofera informatii vitale despre rezistenta umana care se aduna in spatele zidurilor din Ambermill."},sec={{t="Relicva Kirin Tor",b="Descoperit printre lazile cu materiale cartografice destinate enclavei Dalaran din Ambermill, acest pandantiv poarta inscriptii arcane complicate. Vrajitorii de rang inalt ai Kirin Tor folosesc adesea asemenea artefacte pentru a-si concentra si amplifica vrajile. Prezenta numeroaselor pandantive cu incantatii, transportate in regiune, trezeste imediat suspiciunea celor din Forsaken aflati la Sepulcher, semnaland un proiect iminent de o putere magica uriasa."},{t="Un indiciu despre planurile Ambermill",b="Cand ajunge la Sepulcher, Shadow Priest Allister recunoaste amenintarea reprezentata de pozitia fortificata a vrajitorilor din Dalaran, dar ii incredinteaza relicva lui Dalar Dawnweaver pentru cercetari amanuntite. Dawnweaver identifica pandantivul drept o componenta esentiala a operatiunilor magilor si deduce ca Kirin Tor strange unelte de concentrare arcana pentru a alimenta lucrari defensive sau ofensive de anvergura, protejate in spatele granitelor Ambermill."}},faq={{q="La ce foloseste Rune-Inscribed Pendant?",a="Vrajitorii din Kirin Tor folosesc pandantivul pentru a canaliza si directiona fluxuri importante de energie magica. Acesta serveste drept punct de focalizare arcana pentru vrajitorii complexe, nu drept simplu ornament.",al={"ce face pandantivul","scopul pandantivului","la ce foloseste pandantivul cu rune"}},{q="De unde provine acest pandantiv?",a="Este interceptata din transporturile de provizii destinate Ambermill din Silverpine Forest, unde ramasitele Kirin Tor s-au fortificat temeinic.",al={"unde gasesc pandantivul","originea pandantivului","unde a fost gasit"}},{q="Cine analizeaza pandantivul la Sepulcher?",a="Dupa ce Shadow Priest Allister il examineaza pe scurt alaturi de hartile capturate, il trimite la Dalar Dawnweaver, un specialist in arcane de la Sepulcher, care recunoaste mana de lucru a Kirin Tor.",al={"cine studiaza pandantivul","cine vrea pandantivul","pandantivul lui dalar"}},{q="De ce sunt Forsaken ingrijorati din cauza ei?",a="Transportul unor cantitati mari de pandantive de canalizare sugereaza ca Kirin Tor din Ambermill pregateste o ampla lucrare magica, care ameninta controlul Forsaken asupra Silverpine Forest.",al={"de ce le pasa Forsaken","amenintarea din Ambermill","de ce este pandantivul periculos"}}},fx={bf28d080={q="Ce este Rune-Inscribed Pendant?",a="Este un artefact arcan, creat si folosit de magii puternici din Dalaran. Folosite frecvent de Kirin Tor pentru a concentra si canaliza energii magice extraordinare, astfel de pandantive sunt conducte de putere arcana intensa, nu simple podoabe.",al={"ce este pandantivul cu rune","identitatea pandantivului cu rune","ce este acest Dalaran Pendant"}}},fp="22,208,15.444.0,27.417.1,44.182.0,33.141.0,42.180.0,40.188.0"}
