P.entries["item:serpentbloom"] = {n="Serpentbloom",s="Serpentbloom este o planta rara, subterana, care creste numai in adancurile intunecate din Wailing Caverns. Proprietatile sale naturale puternice au atras interesul deosebit al Royal Apothecary Society a Forsaken.",h="Serpentbloom este o planta rara, subterana, care creste numai in adancurile intunecate din Wailing Caverns.",kw={"apothecary zamah","barrens","planta","royal apothecary society","serpentbloom","thunder bluff","wailing caverns"},ang={["profession:Herbalism"]="Herbalistii cu experienta au ochiul ager necesar pentru a gasi aceste flori rare din pesteri, acolo unde altii vad doar piatra umeda.",["race:Undead"]="Obtinerea de Serpentbloom ii ajuta direct pe Apothecary Zamah si Royal Apothecary Society in cautarea lor de resurse botanice din tinuturi straine, menite sa intareasca Forsaken."},sec={{t="O flora subterana rara",b="Serpentbloom creste numai in tunelurile umede si intunecate ale Wailing Caverns, sub Barrens. Inradacinata intr-un ecosistem deformat de energiile nestavilite ale Emerald Dream, planta se dezvolta departe de lumina soarelui si adaposteste adesea serpi veninosi printre tulpini. Cum pesterile sunt napadite de bestii ostile si druizi corupti, putini dintre cei care intra se intorc cu exemplare viabile."},{t="Interesul apotecarilor",b="Din Pools of Vision, aflate sub Thunder Bluff, Apothecary Zamah culege Serpentbloom in numele Royal Apothecary Society din Undercity. Forsaken cauta neincetat vegetatie virulenta, stranie si bogata in substante chimice, prin toata Kalimdor, pentru cercetarile Dark Lady. Zamah crede ca recoltarea unor cantitati insemnate de Serpentbloom ar putea aduce descoperiri valoroase in alchimia Forsaken."}},faq={{q="Unde creste Serpentbloom?",a="Serpentbloom se gaseste doar in adancurile din Wailing Caverns, o retea labirintica de pesteri aflata la sud-vest de Crossroads, in Barrens. Se agata de pamant in cotloanele intunecate si umede ale pesterii.",al={"unde gasesc Serpentbloom","locatia Serpentbloom","planta din Wailing Caverns"}},{q="De ce vrea Royal Apothecary Society Serpentbloom?",a="Apothecary Zamah, o agenta a Royal Apothecary Society stabilita in Thunder Bluff, cauta planta pentru cercetare. Forsaken studiaza flora neobisnuita si periculoasa din Kalimdor pentru a crea noi amestecuri chimice si a sustine obiectivele mai largi ale lui Sylvanas Windrunner.",al={"cine vrea Serpentbloom","planta lui Apothecary Zamah","de ce trebuie cules Serpentbloom"}},{q="De ce este periculoasa recoltarea Serpentbloom?",a="Pe langa pericolele obisnuite din Wailing Caverns, pline de rapitori, crocodili si druizi corupti, planta insasi adaposteste adesea serpi veninosi. Deranjarea plantei ii face deseori pe acesti serpi ascunsi sa atace.",al={"pericolele serpentbloom","sarpele serpentbloom"}},{q="Pot herbalistii sa gaseasca Serpentbloom mai usor?",a="Da. Cei pregatiti in plante medicinale sunt in mod firesc priceputi la depistarea vegetatiei si pot gasi petice de Serpentbloom in colturile intunecate ale podelei pesterii.",al={"gaseste Serpentbloom cu ierbarism","urmarirea Serpentbloom"}}},fx={bee22cd2={q="Ce este Serpentbloom?",a="Serpentbloom este o planta extrem de rara, originara din cele mai intunecate cotloane ale Wailing Caverns, in Barrens. Inradacinata in adancurile subterane si umede, aceasta planta neobisnuita se remarca prin insusirile sale serpentine - daca este deranjata, atrage adesea serpi agresivi, cuibariti in jurul radacinilor.",al={"ce este Serpentbloom","planta Serpentbloom","informatii despre Serpentbloom"}}},fp="12,206,25.409.0,19.424.0,29.205.0,56.276.0,41.232.0,45.164.0"}
