P.entries["item:shindrell-s-note"] = {n="Shindrell's Note",s="Shindrell's Note este un mesaj scris, care descrie observatiile recente privind coruptia din jurul Astranaar si de pe coasta din Ashenvale. Redactat de Sentinel-ul night elf Shindrell Swiftfire, serveste drept raport informativ trimis spre est, prin padure, dru idului Kayneth Stillwind.",h="Shindrell's Note este un mesaj scris, care descrie observatiile recente privind coruptia din jurul Astranaar...",kw={"ashenvale","astranaar","forest song","kayneth stillwind","nightsong woods","shindrell swiftfire","shindrell's note"},ang={["class:Druid"]="Ducerea observatiilor lui Shindrell la Kayneth Stillwind ii ajuta pe druizii aliati sa descopere radacinile molimei nefiresti care afecteaza padurea.",["race:NightElf"]="Misiva ilustreaza cooperarea continua dintre Sentinels, care apara asezarile din Ashenvale, si druizii Cenarion, care studiaza boala ecologica a regiunii."},sec={{t="O scrisoare prin paduri",b="Pe masura ce tulburarile se raspandesc in Ashenvale, sentinelele night elf si druizii isi coordoneaza eforturile pentru a supraveghea hotarele padurii. Scris de Sentinel Shindrell Swiftfire in Astranaar, acest raport descrie tulburari ingrijoratoare observate de-a lungul coastei vestice si prin coronamentul central al padurii. Este adresat lui Kayneth Stillwind, un druid stationat la altarul Forest Song din Nightsong Woods, la est. Trimitandu-i observatiile sale directe prin curieri, Shindrell il ajuta pe Kayneth sa cerceteze coruptia subtila care se strecoara prin crangurile sacre."}},faq={{q="Ce este Shindrell's Note?",a="Este un raport de teren scris de santinela Shindrell Swiftfire, care detaliaza tulburari si cazuri suspecte de coruptie observate in apropiere de Astranaar si de-a lungul coastei Ashenvale.",al={"ce este nota aceasta","nota lui shindrell","ce scrie in nota"}},{q="Cine trebuie sa primeasca biletul?",a="Biletul este adresat lui Kayneth Stillwind, un druid night elf aflat la Forest Song, in tinuturile estice din Ashenvale cunoscute drept Nightsong Woods.",al={"cui trebuie sa-i dau asta","unde trebuie dus","pentru cine este biletul"}},{q="De ce a fost scrisa aceasta nota?",a="Kayneth Stillwind a cerut informatii despre evenimente neobisnuite din padurile vestice, temandu-se ca o corupere insidioasa prinde radacini in padure. Shindrell si-a adunat observatiile pentru a-l ajuta sa evalueze amenintarea.",al={"de ce sa scriu biletul","despre ce coruptie vorbeste Shindrell","scopul raportului"}},{q="Unde locuieste Shindrell Swiftfire?",a="Shindrell Swiftfire este o sentinel Night Elf stationata in asezarea Astranaar, situata in centrul Ashenvale.",al={"unde este Shindrell","locatia lui Shindrell Swiftfire","cine a trimis asta"}}},fx={ed6c40b2={q="De unde provine Shindrell's Note si cine l-a creat?",a="Nota a fost scrisa de sentinelul Shindrell Swiftfire in Astranaar. Redactata ca raport oficial de teren, descrie evenimentele tulburatoare pe care le-a observat de-a lungul coastei Ashenvale si prin padurile din imprejurimi.",al={"cine a scris Shindrell's Note","cine a facut biletul lui Shindrell","originea biletului lui Shindrell"}}},fp="16,283,26.562.0,25.166.0,33.150.0,25.226.0,38.115.0"}
