P.entries["item:skeleton-finger"] = {n="Skeleton Finger",s="Un deget osos, retezat, adunat de la mortii umblatori care bantuie prin crangurile si cimitirele blestemate din Duskwood. Madame Eva din Darkshire colectioneaza aceste ramasite macabre, alaturi de colti de ghoul si venin de paianjen, pentru a fauri talismane de protectie.",h="Un deget osos, retezat, adunat de la mortii umblatori care bantuie prin crangurile si cimitirele blestemate...",kw={"darkshire","duskwood","colt de ghoul","madame eva","jefuitor scheletic","deget de schelet","totem of infliction"},ang={["class:Mage"]="Magii care studiaza divinatia populara vor gasi neobisnuita metoda lui Madame Eva de a transforma falangele scheletice si veninurile naturale intr-o vraja de riposta, un amestec de vrajitorie rustica si magie simpatica.",["class:Paladin"]="Paladin-ii pot tresari la gandul ca pangaresc ramasite scheletice si le poarta partile retezate, dar in bezna cumplita din Duskwood, refolosirea oaselor celor nelegiuiti pentru a-i ocroti pe cei vii este o necesitate sumbra."},sec={{t="Oasele celor nelinistiti",b="Padurile blestemate din Duskwood sunt napadite de ramasitele nelinistite ale mortilor, de la jefuitori si razboinici scheletici pana la magi si demoni necrotici. In timp ce calatorii obisnuiti evita sa atinga ramasitele infecte ale mortilor inviati, ghicitorii si misticii le pretuiesc esenta rece. Madame Eva, clarvazatoarea din Darkshire, strange aceste degete osoase pentru a le lega energiile necrotice persistente intr-un talisman al magiei de riposta, cunoscut drept Totem of Infliction."}},faq={{q="Ce creaturi lasa Skeleton Finger?",a="Skeleton Fingers sunt recoltate de la diferitii strigoi scheletici intalniti in Duskwood, inclusiv Skeletal Raiders, Healers, Warders, Warriors, Horrors, Fiends si Skeletal Mages.",al={"de unde cad degete de schelet","ce lasa degete de schelet","sursa degetelor de schelet"}},{q="Cine vrea Skeleton Fingers in Duskwood?",a="Madame Eva, prezicatoarea care locuieste in Darkshire, are nevoie de ele ca parte a ingredientelor ritualice necesare pentru a vraji un talisman protector.",al={"cine are nevoie de degete de schelet","cine ofera misiunea pentru degete de schelet","la ce folosesc degetele de schelet"}},{q="Ce este Totem of Infliction?",a="Este o bariera fermecata creata de Madame Eva folosind degete de schelet, colti de ghoul si venin de paianjen. Ea impleteste energiile lor intunecate intr-o aura menita sa-i raneasca drept raspuns pe toti cei care incearca sa-i faca rau purtatorului.",al={"scopul Totem of Infliction","ce creeaza Madame Eva"}},{q="De ce are Madame Eva nevoie de ramasite de strigoi pentru un talisman protector?",a="Ritualurile lui Madame Eva canalizeaza pata si agresivitatea latenta din monstrii locali. Unind esentele violente ale scheletelor, ghulilor si fiarelor veninoase din Duskwood, ea le transforma rautatea persistenta intr-o pavaza care pedepseste atacatorii ostili.",al={"de ce magie osoasa","de ce degete de schelet pentru totem"}}},fx={["7c732e26"]={q="Ce este un Skeleton Finger?",a="Un Skeleton Finger este un fragment osos deshidratat si desprins dintr-una dintre ororile scheletice animate care bantuie padurile si criptele pustiite din Duskwood. Conservate de miasma necromantica ce a cuprins regiunea, aceste falange pastreaza urme ale magiei intunecate care ii tine pe mortii vii nelinistiti si in miscare.",al={"deget de schelet, ce este","ce sunt degetele de schelet","identifica degetul de schelet"}},a7de6990={q="De unde provine Skeleton Finger?",a="Aceste degete provin din ramasitele scheletice ridicate din cimitirele bantuite si ruinele din Duskwood. Nu sunt faurite sau fabricate, ci recoltate direct de pe cadavrele insufletite - precum razboinici scheletici, demoni, strajeri si jefuitori - care se tarasc prin intuneric, insufletite de intinaciunea misterioasa si insidioasa ce corupe padurea.",al={"originea degetului de schelet","de unde provin degetele de schelet","cine a creat degetul de schelet"}}},fp="15,234,21.460.0,38.179.0,39.130.0,32.235.0,63.269.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Skin of Sweet Rum",s="Skin of Sweet Rum este o bautura alcoolica speciala, procurata de la Lion's Pride Inn din Goldshire. Barkeep Daniels din Lakeshire o cauta cu disperare pentru a-si aproviziona hanul, in timp ce orcii Blackrock le taie celor din Redridge caile obisnuite de comert.",h="Skin of Sweet Rum este o bautura alcoolica speciala, procurata de la Lion's Pride Inn din Goldshire.",kw={"barkeep daniels","vremuri grele","goldshire","lakeshire","lion's pride inn","burduf cu rom dulce","rom dulce"},ang={["faction:Alliance"]="Procurarea acestui rom scoate in evidenta presiunea logistica pe care invazia orcilor Blackrock o exercita asupra micilor asezari ce apara granitele estice ale regatului Stormwind."},sec={{t="O alinare rara pentru Lakeshire",b="In oraselul Lakeshire, istovit de razboi, proviziile tavernelor sunt periculos de putine. Invazia orcilor Blackrock a blocat drumurile de aprovizionare care duc spre Redridge Mountains, lasandu-l pe Barkeep Daniels sa se straduiasca sa potoleasca setea garzilor si refugiatilor istoviti. Pentru a-si reface stocurile epuizate, Daniels trimite calatori prin regat sa adune specialitati locale, printre care o burdufa plina cu romul dulce si distinctiv produs si servit la Lion's Pride Inn din Goldshire."}},faq={{q="Unde pot gasi Skin of Sweet Rum?",a="Un burduf de Skin of Sweet Rum poate fi cumparat direct de la hangiu sau barmanul din Lion's Pride Inn, in Goldshire, in Elwynn Forest.",al={"unde se gaseste romul dulce","de unde pot cumpara rom dulce","cine vinde rom dulce"}},{q="Cine vrea romul asta?",a="Barkeep Daniels, proprietarul tavernei din Lakeshire, solicita un burduf de rom dulce, alaturi de cateva alte bauturi regionale, pentru a-si reface stocurile epuizate in timpul misiunii Dry Times.",al={"cine are nevoie de rom dulce","predarea romului dulce","misiunea cu rom dulce"}},{q="De ce ramane Lakeshire fara bautura?",a="Escaladarea brusca a invaziei orcilor Blackrock din Redridge a intrerupt rutele comerciale si a intarziat livrarile catre oras. Cum carele negustorilor nu mai pot strabate drumurile in siguranta, stocurile locale sunt aproape epuizate.",al={"de ce au ramas fara bautura","de ce Lakeshire a ramas fara bautura","motivul perioadelor de seceta"}},{q="Ce alte spirite sunt necesare alaturi de rom?",a="Pe langa Skin of Sweet Rum din Goldshire, Barkeep Daniels mai are nevoie de un butoi de Thunderbrew Lager din Westfall, un butoi de Merlot din Stormwind City si o sticla de Moonshine din Darkshire.",al={"bauturi pentru vremuri grele","lista de bauturi a lui daniels","alte bauturi necesare"}}},fx={efbd5e13={q="Ce este un Skin of Sweet Rum?",a="Skin of Sweet Rum este o plosca de piele plina cu lichior dulce, vanduta in Goldshire, in Elwynn Forest. Este una dintre numeroasele bauturi spirtoase de specialitate ale regiunii, apreciate in regatele oamenilor din sudul Azerothului.",al={"ce este romul dulce","informatii despre butoiul cu rom dulce","rom dulce"}}},fp="17,252,28.488.0,37.140.0,19.186.0,39.216.0,48.196.0"}
P.entries["item:skittering-blood"] = {n="Skittering Blood",s="Skittering Blood este un reactiv alchimic recoltat de la arahnidele care salasluiesc in Skittering Dark, din Silverpine Forest. Este un ingredient toxic esential pentru cercetarile Royal Apothecary Society asupra unei New Plague menite sa-i nimiceasca atat pe Scourge, cat si omenirea.",h="Skittering Blood este un reactiv alchimic recoltat de la arahnidele care salasluiesc in Skittering Dark, din...",kw={"faranell","ciuma noua","renferrel","royal apothecary society","silverpine forest","skittering blood","skittering dark","skitterweb"},ang={["faction:Horde"]="Alchimistii Forsaken primesc cu bratele deschise materiile prime care le vor permite sa asigure apararea Lordaeronului, ducandu-si razboiul impotriva Scourge cu arme faurite de ei insisi.",["race:Undead"]="Contributia cu Skittering Blood ii ajuta direct pe regina Sylvanas si pe Royal Apothecary Society sa creeze arma biologica suprema impotriva lui Arthas si a oamenilor vii."},sec={{t="Un distilat toxic",b="Recoltata de la paianjenii Skitterweb panditori si atacatori, precum si de la mama lor, Krethis the Shadowspinner, aceasta hemolimfa veninoasa are proprietati virulente, foarte apreciate de alchimistii Forsaken. Apothecary Renferrel a descoperit ca, atunci cand este rafinat impreuna cu toxine extrase din inimile ursilor batrani, sangele formeaza baza unui elixir deosebit de letal. Compusii din acest fluid contin agenti contaminanti puternici, ceea ce il face un catalizator biologic ideal pentru experimentele chimice ale Apothecarium."},{t="Alimentarea New Plague",b="Sub indrumarea lui Master Apothecary Faranell in Undercity, Royal Apothecary Society aduna reactivi precum Skittering Blood pentru a crea o New Plague devastatoare. In fata hoardelor coplesitoare de Scourge si a ramasitelor ostile ale oamenilor, Forsaken recurg la razboiul biologic pentru a-si echilibra sansele. Faranell analizeaza potentialul toxic al sangelui pentru a concepe o molima suficient de puternica incat sa stinga deopotriva neviata si carnea vie."}},faq={{q="La ce se foloseste Skittering Blood?",a="Royal Apothecary Society foloseste Skittering Blood pentru a dezvolta New Plague a celor Forsaken. Amestecat cu toxine obtinute din inimile ursilor, acesta produce un amestec instabil, pe care Master Apothecary Faranell il studiaza pentru a-i eradica atat pe strigoii Scourge, cat si pe oamenii vii.",al={"utilizarea Skittering Blood","de ce sa adun sange de paianjen","ce face Faranell cu Skittering Blood"}},{q="Unde poate fi gasit Skittering Blood?",a="Este adunat de pe trupurile paianjenilor Skitterweb - inclusiv ale celor care pandesc, ataca si ale lui Krethis the Shadowspinner - ce se ascund in Skittering Dark si in imprejurimi, o padure intunecata si napadita de panze, din nord-vestul regiunii Silverpine Forest.",al={"unde gasesc Skittering Blood","locatia lui Skittering Blood","cine lasa Skittering Blood"}},{q="Cine cere aceste mostre?",a="Apothecary Renferrel, de la Sepulcher din Silverpine Forest, dispune strangerea sangelui si le cere aventurierilor sa duca lichidul recoltat direct la Master Apothecary Faranell, in Apothecarium of the Undercity.",al={"cine vrea Skittering Blood","cel care da misiunea pentru Skittering Blood"}},{q="De ce au Forsaken nevoie de venin de la animalele din zona?",a="Royal Apothecary Society izoleaza in permanenta toxine naturale din fauna corupta din Lordaeron. Veninul propriu al paianjenilor uriasi din Silverpine constituie agenti patogeni biologici bruti, care pot fi concentrati si transformati in molime sintetice.",al={"de ce venin de paianjen","cercetarea fiarelor de catre apotecari"}}},fx={["8eea8a63"]={q="Ce este Skittering Blood?",a="Skittering Blood este ichorul virulent recoltat de la paianjenii uriasi care salasluiesc in Skittering Dark din Silverpine Forest. Are proprietati veninoase si contaminante naturale, ceea ce il face un reactiv biologic nepretuit pentru experimentele alchimice.",al={"ce este Skittering Blood","obiectul Skittering Blood","despre Skittering Blood"}},f7d32240={q="De unde provine Skittering Blood si cine l-a facut?",a="Nu este fabricat, ci extras in mod natural de la arahnidele pradatoare care salasluiesc in nord-vestul Silverpine Forest, inclusiv Skitterweb Lurkers, Skitterweb Strikers si matca Krethis the Shadowspinner. Vanatorii care aduna materiale pentru Forsaken extrag sangele direct din lesurile acestora.",al={"de unde provine Skittering Blood","cine a facut Skittering Blood","originea lui Skittering Blood"}}},fp="16,277,18.498.0,22.420.0,34.266.0,32.226.0,27.229.0,49.251.0"}
P.entries["item:sleepers-key"] = {n="Sleepers' Key",s="Sleepers' Key este una dintre cele trei chei fermecate faurite de druizii Night Elf pentru a pecetlui seiful lor sacru din Talon Den, pe varful Stonetalon Peak. Pastrata in siguranta intr-un ascunzis secret, deschis cu Gatekeeper's Key, este una dintre cele trei chei necesare pentru a deschide vistieria druidilor.",h="Sleepers' Key este una dintre cele trei chei fermecate faurite de druizii Night Elf pentru a pecetlui seiful...",kw={"gatekeeper's key","sleepers cache","sleepers key","sleepers' key","stonetalon peak","talon den","talon den hoard","vizuina"},ang={["class:Druid"]="Cheile si ascunzatorile din Talon Den dezvaluie apararea stratificata a druidilor Night Elf, care folosesc ascunzatori tainice si incuietori cu chei pentru a sigila relicvele puterii.",["faction:Horde"]="Obtinerea Sleepers' Key face parte dintr-un raid orchestrat in inima Stonetalon Peak, care inlatura protectiile defensive ale elfilor noptii pentru a pune mana pe relicvele pecetluite in vistieria lor."},sec={{t="O masura de protectie druidica",b="Sapat in inaltimile din Stonetalon Peak, Talon Den este o reduta si un sanctuar pentru druizii din Kalimdor. Stiind ca relicvele sacre si comorile puternice ar putea atrage atentia nedorita, paznicii elfi ai noptii au creat un sistem complicat de incuietori si ascunzatori pentru a-si proteja tezaurul. Sleepers' Key este o treime din acest sistem de protectie. Ascunsa intr-un loc tainic din adancurile vizuinii, cheia poate fi recuperata numai folosind Gatekeeper's Key, ascunsa langa intrare. Alaturi de Claw Key si Barrow Key, Sleepers' Key trebuie introdusa in incuietorile de piatra ale Talon Den Hoard pentru a destrama protectia si a dezvalui obiectele stravechi pastrate inauntru."}},faq={{q="La ce foloseste Sleepers' Key?",a="Cheia Sleepers' Key este folosita alaturi de cheile Barrow Key si Claw Key pentru a deschide Talon Den Hoard, o bolta de piatra aparata de vraji, ascunsa adanc in vizuina din tumul de la Stonetalon Peak.",al={"la ce foloseste sleepers key","scopul sleepers key","talon den hoard keys"}},{q="Cum a fost zavorata Sleepers' Key?",a="Druizii au pus-o in Sleepers' Cache, in tunelurile din nord-vestul Talon Den. Pentru a deschide ascunzatoarea este nevoie de Gatekeeper's Key, pe care druizii au tainuit-o intr-un felinar banal, langa intrarea in vizuina.",al={"unde este cheia lui Sleeper","deschiderea ascunzatorii lui Sleeper","cerinte pentru cheia Gatekeeper"}},{q="De ce si-au ascuns druizii relicvele cu mai multe chei?",a="Druizii night elf au creat masuri de protectie complexe, astfel incat obiectele lor puternice si relicvele sacre sa nu cada niciodata in mainile dusmanilor, daca salasul ar fi atacat. Ascunderea cheilor in depozite tainice a impiedicat intrusii sa le jefuiasca prada cu usurinta.",al={"de ce atatea chei","apararea din Talon Den","enigma comorii druidului"}},{q="De ce se numeste Sleepers' Key?",a="Druizii nu explica niciodata numele. Cheia poarta pur si simplu acelasi nume ca Sleepers' Cache, cufarul ascuns din Talon Den in care este pastrata.",al={"cine sunt cei adormiti","numele Sleeperilor si semnificatia lui"}}},fx={["0a862a33"]={q="Ce este Sleepers' Key?",a="Sleepers' Key este una dintre cele trei chei speciale faurite de druizii Night Elf din Stonetalon Peak. Ascunsa intr-un depozit incuiat, in adancul Talon Den, este o parte esentiala a sistemului de protectie care pazeste tezaurul central al druizilor, plin de relicve sacre.",al={"ce este cheia adormitilor","istoria cheii adormitilor","despre cheia adormitilor"}},["8275ad63"]={q="De unde provine Sleepers' Key si cine a creat-o?",a="Cheia a fost faurita de druizii care au intemeiat Talon Den pe Stonetalon Peak. Pentru a-si proteja artefactele puternice de intrusi, au conceput un sistem de securitate complex si au pus cheia intr-un cufar special numit Sleepers' Cache.",al={"cine a facut cheia sleepers","originea cheii sleepers","de unde provine cheia sleepers"}},["3884172c"]={q="De ce si-ar dori cineva Sleepers' Key?",a="Horde cauta cheia care sa ocoleasca apararile stratificate ale druidilor si sa descuie Talon Den Hoard. Impreuna cu Claw Key si Barrow Key, aceasta deschide bolta de piatra in care druizii au ascuns relicvele puternice de pe Stonetalon Peak.",al={"de ce sa gasesc cheia lui Sleeper","de ce e nevoie de cheia lui Sleeper","cine vrea cheia lui Sleeper"}}},fp="13,274,19.668.0,35.167.0,38.224.0,56.258.0,35.137.0"}
P.entries["item:smoky-iron-ingot"] = {n="Smoky Iron Ingot"}
P.entries["item:smoldering-embers"] = {n="Smoldering Embers",s="Smoldering Embers sunt resturile incinse si stralucitoare recuperate de la elementalii furiosi ai focului din Charred Vale. Sentinelele elfe ale noptii urmaresc aceste taciuni ca dovada materiala ca grozaviile in flacari care au napadit padurea devastata sunt infrante.",h="Smoldering Embers sunt resturile incinse si stralucitoare recuperate de la elementalii furiosi ai focului din...",kw={"distrugator arzator","devastator arzator","charred vale","spirite furioase","kaela shadowspear","spirit de flacara razlet","smoldering embers","stonetalon","venture co"},ang={["class:Druid"]="Druizii vad jarul drept dovada tragica a naturii dezechilibrate de lacomia industriala, unde furia elementala nestapanita impiedica solul acoperit de cenusa sa se regenereze vreodata.",["race:NightElf"]="Pentru elfii noptii, sa vada Charred Vale in flacari este o rana sfasietoare adusa lui Kalimdor. Adunarea acestor taciuni este o indatorire solemna, menita sa curete pangarirea straina si sa readuca pacea sub privirea lui Elune."},sec={{t="Ramasitele Charred Vale",b="Defrisarea necrutatoare si devastarea industriala provocate de Venture Company au sfasiat Charred Vale, incendiind padurea si dezlantuind furia distrugatoare din adancurile pamantului. In urma lor, elementalii de foc viu - Burning Ravagers, Burning Destroyers si ratacitorii Rogue Flame Spirits - au navalit prin bazinul parjolit. Acesti Smoldering Embers sunt nucleele persistente, acoperite de cenusa, ramase dupa stingerea unui elemental, dovada ca incendiile necrutatoare din vale sunt inabusite sistematic."}},faq={{q="De unde provin Smoldering Embers?",a="Smoldering Embers sunt adunate de la elementalii de foc care bantuie Charred Vale, in sudul Stonetalon Mountains, inclusiv de la Burning Ravagers, Burning Destroyers si Rogue Flame Spirits.",al={"unde gasesc Smoldering Embers","cine lasa Smoldering Embers","sursa jarului mocnit"}},{q="De ce vrea Kaela Shadowspear aceste jaruri?",a="Kaela Shadowspear ii vrea drept dovada de netagaduit ca elementalii de foc dezlantuiti din Charred Vale sunt starpiti. Ea crede ca tinutul cicatrizat nu se va putea vindeca niciodata sub gratia lui Elune cat timp aceste spirite violente umbla nestingherite.",al={"de ce sa colectezi Smoldering Embers","taciunii lui Kaela Shadowspear","scopul spiritelor infuriate"}},{q="Ce a facut sa apara elementalii de foc in Charred Vale?",a="Venture Company a folosit utilaje agresive si incendieri fara discernamant pentru a curata padurea straveche. Exploatarea lor nesabuita a destabilizat tinutul, dezgropand si eliberand elementali ostili ai focului si pietrei, care i-au alungat in cele din urma pe goblini.",al={"ce s-a intamplat cu charred vale","de ce sunt elementali ai focului in stonetalon","spirite ale focului ale Venture Co."}}},fx={["4d13fc7e"]={q="Ce sunt Smoldering Embers?",a="Smoldering Embers sunt ramasitele materiale arzande lasate in urma de elementalii distructivi ai focului care infesteaza Charred Vale. Aceste resturi stralucitoare persista dupa ce sunt ucise creaturi precum Burning Ravagers, Rogue Flame Spirits si Burning Destroyers, fiind dovada palpabila ca furia lor mistuitoare a fost potolita prin padurea in ruina.",al={"ce sunt Smoldering Embers","povestea Smoldering Embers","ce este un jar mocnit"}}},fp="17,253,28.538.0,37.189.0,45.228.0,62.255.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Snellig's Snuffbox",s="Snellig's Snuffbox este un suvenir personal recuperat de la strigoiul nelinistit First Mate Snellig, printre ramasitele Lost Fleet. Ducerea acestui fleac inapoi la First Mate Fitzsimmons, in Menethil Harbor, dovedeste ca fostul sau camarad blestemat a fost in sfarsit trimis la odihna.",h="Snellig's Snuffbox este un suvenir personal recuperat de la strigoiul nelinistit First Mate Snellig, printre...",kw={"echipajul blestemat","Fitzsimmons","Kul Tiras","Lost Fleet","Snellig","tabachera","Third Fleet","Wetlands"},ang={["faction:Alliance"]="Recuperarea bunurilor marinarilor Kul Tiran cazuti si alinarea spiritelor lor blestemate sunt o datorie sumbra, indeplinita in slujba unui vechi aliat naval al Alliance."},sec={{t="O amintire din Third Fleet",b="Cand Third Fleet of Kul Tiras a esuat pe tarmurile nordice ale Wetlands, marinarii si ofiterii sai nu au avut parte de o moarte linistita. Legat de o putere misterioasa si intunecata, care avea legatura cu o comoara ascunsa la bordul corabiilor, echipajul inecat s-a ridicat din nou sub forma unor spirite chinuite si a unor strigoi scheletici. Printre ei se afla First Mate Snellig, care bantuie si acum cala putrezita a epavei celei mai apropiate de coasta. Chiar si dupa moarte, s-a agatat de tabachera sa - o amintire marunta si neinsemnata a vietii sale muritoare pe mare. Pentru singurul supravietuitor in viata al dezastrului, First Mate Fitzsimmons, recuperarea acestui mic obiect este o dovada concreta ca macar unul dintre tovarasii sai de echipaj pierduti a fost eliberat de o eternitate de chin."}},faq={{q="Ce este Snellig's Snuffbox?",a="Este un mic recipient personal, candva in proprietatea lui First Mate Snellig, ofiter al nefericitei Third Fleet din Kul Tiras. Este purtat de ramasitele sale strigoi la bordul epavelor de langa coasta nordica a tinutului Wetlands.",al={"ce este acest obiect","cutia de tutun a lui snellig","cutie de tutun"}},{q="Unde gasesc Snellig's Snuffbox?",a="Tabachera este luata de la First Mate Snellig, care bantuie cala epavei celei mai apropiate de tarm, din Lost Fleet, in nord-vestul Wetlands.",al={"cand lasa Snellig tabachera","gaseste-l pe Snellig","locatia lui First Mate Snellig"}},{q="Cine vrea aceasta tabachera?",a="First Mate Fitzsimmons, singurul supravietuitor in viata al Third Fleet, le cere aventurierilor sa-i aduca tabachera la Menethil Harbor, drept dovada ca Snellig si-a gasit odihna.",al={"cine ia tabachera","cui predau acest obiect","misiunea lui Fitzsimmons"}},{q="De ce este First Mate Snellig blestemat?",a="Potrivit lui Fitzsimmons, o comoara intunecata si cumplita, ascunsa la bordul uneia dintre navele Third Fleet, a condamnat echipajele cand acestea au naufragiat, prinzandu-le sufletele in grinzile putrezite si lipsindu-le de odihna.",al={"de ce e snellig mort viu","blestemul Lost Fleet","blestemul Third Fleet"}}},fp="18,283,29.710.0,27.215.0,35.148.0,24.174.0,33.204.0"}
P.entries["item:snufflenose-command-stick"] = {n="Snufflenose Command Stick",s="Snufflenose Command Stick este un toiag de dresaj oferit de antreprenorul goblin Mebok Mizzyrix din Ratchet. Este folosit pentru a indruma popandaii snufflenose dresati sa gaseasca si sa dezgroape tuberculi blueleaf valorosi, ingropati adanc in Razorfen Kraul.",h="Snufflenose Command Stick este un toiag de dresaj oferit de antreprenorul goblin Mebok Mizzyrix din Ratchet.",kw={"tubercul blueleaf","baston de comanda","popandau","mebok mizzyrix","ratchet","razorfen kraul","snufflenose","barrens"},ang={["profession:Cooking"]="Desi tuberculii de frunza albastra sunt considerati o delicatesa culinara rafinata pretutindeni in lume, pentru a-i scoate din pamant ai nevoie de un animal dresat si de un bat de mana, nu de ustensile obisnuite de bucatarie."},sec={{t="Un toiag pentru rozatoare",b="Tuberculii blueleaf sunt delicatese ravnite in tot Azeroth, dar e aproape imposibil sa-i gasesti fara ajutor specializat. Ascunsi adanc sub pamantul spinos din Razorfen Kraul, bulbii sunt cu totul nevazuti. Pentru a profita de aceasta piata manoasa fara a risca sa patrunda el insusi in vizuinile quilboarilor, negustorul Mebok Mizzyrix din Ratchet a invatat popandaii snufflenose cu miros fin sa dezgroape tuberculii. Snufflenose Command Stick este unealta cu care aventurierii indruma aceste vietati dresate, impingandu-le sa adulmece si sa scoata la iveala radacini de la o distanta de pana la cincizeci de pasi."}},faq={{q="La ce foloseste Snufflenose Command Stick?",a="Bastonul de comanda este folosit pentru a ordona unei cartite antrenate sa caute tuberculi blueleaf ascunsi in tunelurile spinoase din Razorfen Kraul. Indreptat spre o cartita invocata, bastonul indeamna creatura sa urmeze mirosurile si sa sape dupa radacini.",al={"cum se foloseste batul de comanda","ce face batul de comanda","scopul batului de comanda"}},{q="De unde se obtine Snufflenose Command Stick?",a="O ridici din Ratchet, in Barrens, chiar in fata atelierului lui Mebok Mizzyrix, langa o lada care contine un popandau dresat si un manual de instructiuni.",al={"unde gasesc toiagul de comanda","locatia toiagului de comanda","cine da toiagul de comanda"}},{q="De ce vrea Mebok Mizzyrix tuberculii blueleaf?",a="Tuberculii Blueleaf sunt delicatese rare care se vand pe bani frumosi cunostintelor instarite din lumea culinara de pretutindeni. Pentru ca cresc doar in adancurile Barrens, pe teritoriul quilboarilor, Mebok angajeaza aventurieri sa-i culeaga.",al={"de ce tuberculi","la ce foloseste tuberculul Blueleaf","de ce vrea Mebok tuberculi"}},{q="Pastrezi batul dupa ce gasesti tuberculii?",a="Nu. Dupa ce aduni tuberculii ceruti, Mebok iti cere sa-i aduci inapoi in Ratchet atat bastonul de comanda, cat si lada de transport, impreuna cu recolta.",al={"pot pastra bastonul de comanda","returnarea bastonului de comanda"}}},fx={["8cc828c2"]={q="Ce este Snufflenose Command Stick?",a="Snufflenose Command Stick este unealta brevetata de dresaj a companiei Snuff Inc., furnizata impreuna cu popandaii dresati ai goblinului intreprinzator Mebok Mizzyrix, din Ratchet. Este conceputa special pentru a indruma popandaii snufflenose dresati, semnalandu-le sa scormoneasca dupa delicatese ingropate si greu de gasit, pe care un cercetas obisnuit nu le-ar observa deloc.",al={"ce este bastonul de comanda","bastonul Snufflenose","ce este Snufflenose Command Stick"}},["9fdd5faa"]={q="De unde provine Snufflenose Command Stick si cine l-a confectionat?",a="Batul de comanda este un produs brevetat de Snuff Inc., a carui intrebuintare este explicata de proprietarul Marwig Rustbolt in Snufflenose Owner's Manual. Mebok Mizzyrix din Ratchet si-a dresat cartitele snufflenose sa adune delicatese rare si pastreaza laolalta betele de comanda, lazile si manualele, pentru ca angajatii sa poata tine cum trebuie creaturile sub control.",al={"cine a creat bastonul de comanda","originea bastonului de comanda","de unde provine bastonul de comanda"}},fb1cfa60={q="De ce ar vrea cineva Snufflenose Command Stick?",a="Tuberculii rari de blueleaf sunt imposibil de gasit fara ajutor printre maracinii din Razorfen Kraul. Betele de comanda sunt esentiale, fiindca il obliga pe un gopher snufflenose dresat sa adulmece pana la cincizeci de pasi si sa dezgroape tuberculii, care pot fi apoi dusi inapoi la Mebok Mizzyrix in schimbul unei sume frumusele.",al={"de ce ai nevoie de bat","de ce se doreste Snufflenose Command Stick","de ce sa obtin Snufflenose Command Stick"}}},fp="25,241,17.568.0,47.250.0,50.159.0,45.230.0,54.165.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Snufflenose Owner's Manual",s="Snufflenose Owner's Manual este o brosura instructiva de la Marwig Rustbolt, din Snuff Inc., pastrata langa antreprenorul goblin Mebok Mizzyrix in Ratchet. Explica modul in care trebuie trimis si indrumat un popandau Snufflenose dresat pentru a gasi Blueleaf Tubers rare, ingropate in Razorfen Kraul.",h="Snufflenose Owner's Manual este o brosura instructiva de la Marwig Rustbolt, din Snuff Inc., pastrata langa...",kw={"tubercul Blueleaf","popandau","manual","Mebok Mizzyrix","Ratchet","Razorfen Kraul","Snufflenose"},ang={["profession:Cooking"]="Manualul descrie procesul de recoltare a Blueleaf Tubers, o radacina subterana considerata o delicatesa rara de gurmanzii si negustorii din Azeroth."},sec={{t="Ghidul de functionare al unui Goblin",b="Scris de Marwig Rustbolt, proprietarul Snuff Inc., acest scurt ghid explica modul de lucru cu popandaii snufflenose dresati ai companiei. Aceste bestii au un miros ascutit, capabil sa detecteze Blueleaf Tubers sub pamant de la cincizeci de pasi. Manualul ii indeamna pe cautatorii de zacamant sa elibereze un popandau folosind o cusca ventilata si sa-i ghideze instinctul de a scurma cu ajutorul unui toiag de comanda, indrumand creatura prin maracinii primejdiosi si tunelurile quilboar din Razorfen Kraul, pentru a pune mana pe pretioasele delicatese culinare."}},faq={{q="La ce foloseste Snufflenose Owner's Manual?",a="Serveste drept instructiuni pentru folosirea popandailor dresati cu bot adulmecator ai lui Mebok Mizzyrix. Aventurierii o citesc ca sa afle cum sa scoata animalul din cusca si sa-l indrume cu un bat de comanda pentru a gasi Blueleaf Tubers ingropate in Razorfen Kraul.",al={"ce face manualul","de ce sa citesti manualul","scopul manualului"}},{q="Unde pot gasi manualul?",a="Manualul se afla in Ratchet, in tinutul Barrens, chiar langa Mebok Mizzyrix, alaturi de lazile speciale si betele de comanda necesare pentru strangerea tuberculilor.",al={"locatia manualului","unde este cartea","cum obtii manualul"}},{q="De ce sunt necesari popandaii snufflenose pentru a gasi Blueleaf Tubers?",a="Tuberculii Blueleaf cresc ascunsi adanc in pamant, in Razorfen Kraul, si sunt practic imposibil de zarit de catre umanoizi. Popandaii dresati au mirosul ascutit si pot detecta mirosul unui tubercul ingropat de la cincizeci de pasi.",al={"de ce sa folosesti cartite","pot gasi tuberculi fara cartite"}},{q="Cine a scris manualul?",a="Este semnata de Marwig Rustbolt, proprietarul Snuff Inc., care a scris-o pentru a-i invata pe noii stapani sa-si hraneasca, plimbe si comande cartitele cu ajutorul bastonului de comanda patentat.",al={"autorul manualului","cine l-a facut"}}},fx={["1c231f00"]={q="Ce este Snufflenose Owner's Manual?",a="Este un manual de instructiuni oferit impreuna cu o cartita bot-ascutita dresata si cu un bat de comanda. Manualul ii arata aventurierului cum sa manevreze creatura in tunelurile subterane din Razorfen Kraul si explica felul in care poate fi pusa s-adulmeca dupa Blueleaf Tubers ascunse sub pamant.",al={"ce este manualul proprietarului Snufflenose","identitatea manualului Snufflenose","ce este manualul"}}},fp="26,280,26.512.0,54.249.0,28.152.0,59.233.0,21.163.0"}
P.entries["item:sodium-nitrate"] = {n="Sodium Nitrate"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Solomon's Plea to Darkshire",s="Solomon's Plea to Darkshire este o scrisoare urgenta, redactata de Magistrate Solomon din Lakeshire si adresata lui Lord Ello Ebonlocke. In fata amenintarii tot mai mari reprezentate de orcii Blackrock si gnolli, scrisoarea implora conducerea din Darkshire sa trimita militia de elita, Night Watch, pentru a intari apararea slabita a orasului Lakeshire.",h="Solomon's Plea to Darkshire este o scrisoare urgenta, redactata de Magistrate Solomon din Lakeshire si...",kw={"darkshire","duskwood","lakeshire","lord ello ebonlocke","magistrate solomon","messenger to darkshire","night watch","redridge","solomon's plea"},ang={["faction:Alliance"]="Mesajul ilustreaza faramitarea tinuturilor sudice ale Grand Alliance, unde asezarile indepartate trebuie sa-si ceara ajutor unele altora pentru a supravietui, in timp ce Stormwind ramane indiferent.",["race:Human"]="Pentru calatorii human, purtarea acestei scrisori evidentiaza primejdia comuna care ameninta atat tinuturile de granita din Redridge, cat si padurile umbrite din Duskwood."},sec={{t="Un apel disperat dupa ajutor",b="Lakeshire se afla in pragul de a fi coplesit de orcii Blackrock, gnolli si murloci invadatori, in timp ce din Stormwind nu sosesc practic deloc intariri oficiale. Cuprins de disperare, Magistrate Solomon a redactat aceasta cerere oficiala adresata primarului Ello Ebonlocke din Darkshire, solicitandu-i sa trimita membri ai Night Watch spre nord, in Redridge. Documentul reflecta prabusirea grava a sprijinului militar central in sudul Azeroth, care obliga asezarile individuale ale oamenilor sa se bazeze unele pe altele pentru a supravietui."},{t="Situatia sumbra din Darkshire",b="Desi cererea lui Solomon este urgenta, ea scoate in evidenta izolarea Lakeshire fata de adevaratele orori care-i napastuiesc vecinii. Duskwood este asediata de strigoi, fiare vorace si intuneric omniprezent, iar Night Watch abia mai face fata incercand sa tina in frau hotarele satului. In loc sa gaseasca o rezerva nefolosita de soldati proaspeti, curierii care aduc rugamintea descopera un oras la fel de greu incercat, incapabil sa trimita aparatori spre Redridge."}},faq={{q="Ce este Solomon's Plea to Darkshire?",a="Este o scrisoare oficiala trimisa de Magistrate Solomon din Lakeshire lui Lord Ello Ebonlocke, primarul din Darkshire. Mesajul ii cere cu urgenta orasului Darkshire sa trimita ajutorul militiei sale, Night Watch, pentru a apara Redridge de orcs Blackrock si gnolls.",al={"scrisoarea lui Solomon catre Darkshire","ce contine rugamintea lui Solomon","scrisoarea din Lakeshire catre Duskwood"}},{q="De ce cere Lakeshire ajutor militar din partea Darkshire, in loc sa-l ceara de la Stormwind?",a="Guvernul central din Stormwind nu a reusit in mare masura sa asigure suficiente trupe de garnizoana pentru teritoriile indepartate, din cauza inertiei politice si a conflictelor interne. Lasat sa apere singur Lakeshire impotriva incursiunilor tot mai numeroase, Magistrate Solomon s-a indreptat catre localitatile umane invecinate, in speranta ca va obtine forte aliate.",al={"de ce sa intrebe in Darkshire","de ce nu in Stormwind","de ce are nevoie Solomon de Night Watch"}},{q="Cine este Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke este primarul si principalul conducator civil al orasului Darkshire din Duskwood. El supravegheaza orasul si coordoneaza Night Watch, forta de aparare civila care lupta sa tina piept ororilor ascunse in padure.",al={"cine este ebonlocke","primarul din darkshire","lord ello"}},{q="Poate Darkshire sa-si lipseasca de Night Watch pentru a ajuta Lakeshire?",a="Nu. Duskwood este prins in propriul cosmar, inconjurat de strigoi, worgen salbatici si magie neagra. Night Watch abia are suficienti oameni pentru a apara perimetrul Darkshire si nu poate trimite niciun luptator pana in Redridge.",al={"ajuta Darkshire","va veni Night Watch","a trimis Ebonlocke garzi"}}},fx={a3b7e1d6={q="De unde provine Solomon's Plea to Darkshire si cine a facut-o?",a="Scrisoarea a fost redactata chiar de Magistrate Solomon, conducatorul orasului Lakeshire din Redridge. In timp ce orcii Blackrock apasau greu asupra orasului, iar Stormwind nu putea trimite intariri regale, Solomon a scris personal apelul urgent din primaria orasului Lakeshire, in speranta ca asezarile invecinate ii vor veni in ajutor.",al={"cine a scris rugamintea lui Solomon","originea lui Solomon's Plea to Darkshire","cine a creat rugamintea lui Solomon"}},["5061acb5"]={q="De ce vrea Lord Ello Ebonlocke Solomon's Plea to Darkshire?",a="Lord Ello Ebonlocke are nevoie de scrisoare pentru ca aceasta descrie oficial apararea disperata a Lakeshire si cererea directa de ajutor militar a lui Magistrate Solomon. Ca primar al Darkshire si comandant al Night Watch, Ebonlocke se bazeaza pe asemenea depese oficiale pentru a intelege amenintarile cu care se confrunta vecinii lor din Alliance si pentru a evalua daca orasul sau isi poate permite sa trimita garzi.",al={"de ce sa predai Solomon's Plea","de ce are nevoie Ebonlocke de scrisoare","scopul Solomon's Plea to Darkshire"}}},fp="27,313,24.521.0,23.468.1,36.274.0,73.318.0,27.226.0,63.228.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Solomon's Plea to Westfall",s="Solomon's Plea to Westfall este un apel urgent, in scris, redactat de Magistrate Solomon din Lakeshire. Disperat sa obtina intariri impotriva orcilor Blackrock si a gnollilor, Solomon ii trimite misiva lui Gryan Stoutmantle, in Westfall, in speranta ca People's Militia, abia infiintata, ii va veni in ajutor, cat timp armata regala din Stormwind nu raspunde.",h="Solomon's Plea to Westfall este un apel urgent, in scris, redactat de Magistrate Solomon din Lakeshire.",kw={"Gryan Stoutmantle","Lakeshire","Magistrate Solomon","People's Militia","Redridge","cererea lui Solomon","armata Stormwind","Westfall"},ang={["faction:Alliance"]="Documentul scoate in evidenta paralizia administrativa tot mai accentuata din inima Alliance, unde orasele indepartate trebuie sa se bazeze pe voluntari locali, nu pe trupele regale.",["race:Human"]="Pentru Human din provinciile sudice, acest apel dezvaluie cat de greu o duc asezarile rurale, in timp ce disparitia regelui si neglijarea politica lasa tinuturile de frontiera vulnerabile."},sec={{t="Un apel disperat dupa ajutor",b="In timp ce amenintarea reprezentata de Blackrock clan si gnollii ostili apasa greu asupra Redridge, Magistrate Solomon se afla intr-o izolare primejdioasa in Lakeshire. Armata regala din Stormwind nu a venit, in mod inexplicabil, in numar mare sa apere hotarele regiunii. Neputand astepta ajutor oficial din capitala regatului, Solomon scrie aceasta rugaminte, intr-o incercare disperata de a obtine sprijin din afara structurilor militare regulate. Auzind ca in vest, prin Elwynn, se formeaza o forta de aparare voluntara, apeleaza direct la People's Militia."},{t="Ajungand dincolo de granita",b="Mesajul ii este adresat direct lui Gryan Stoutmantle, un razboinic veteran care organizeaza apararea frontierei din Westfall. Solomon spera ca Stoutmantle ii va putea trimite luptatori sa intareasca Lakeshire pana cand coroana din Stormwind va trimite in sfarsit intariri regulate. Incredintat unui aventurier care joaca rolul de curier, documentul reflecta dezbinarea coordonarii administrative in teritoriile indepartate ale Stormwindului, unde magistratii locali sunt nevoiti sa negocieze din proprie initiativa acorduri de ajutor reciproc."}},faq={{q="Ce este Solomon's Plea to Westfall?",a="Este o petitie oficiala scrisa de Magistrate Solomon din Lakeshire, prin care le cere lui Gryan Stoutmantle si People's Militia din Westfall sa trimita intariri militare pentru a ajuta la apararea Redridge.",al={"ce este ruga lui Solomon","scrisoarea lui Solomon catre Westfall","scrisoarea Lakeshire-Westfall"}},{q="De ce ii cere Magistrate Solomon ajutor lui Westfall in loc sa-l ceara lui Stormwind?",a="Solomon observa ca se petrece ceva ciudat cu Stormwind Army, deoarece trupele regale nu au sosit in numar mare, desi pericolul care ameninta Lakeshire se agraveaza. Neavand timp sa astepte dupa Coroana, Solomon apeleaza la orice forta luptatoare din apropiere care este dispusa sa ajute.",al={"de ce sa ceri ajutorul Westfall","de ce sa nu intrebi Stormwind","de ce sa trimiti cererea catre Westfall"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este liderul People's Militia, o liga de aparare populara organizata de fermierii si colonistii locali pentru a proteja Westfall de Defias Brotherhood.",al={"cine este Stoutmantle","rolul lui Gryan Stoutmantle"}},{q="Ce amenintari il determina pe Solomon sa trimita aceasta scrisoare?",a="Lakeshire se confrunta cu incursiuni agresive ale orcilor din Blackrock, precum si cu raiduri ale gnollilor prin Redridge Mountains, suprasolicitand garda locala.",al={"de ce este Lakeshire in pericol","ce ameninta Redridge"}}},fx={["7804da1c"]={q="De unde provine Solomon's Plea to Westfall si cine l-a scris?",a="Scrisoarea este scrisa chiar de Magistrate Solomon, in Lakeshire, orasul greu incercat din Redridge Mountains. Disperat fiindca Stormwind Army nu trimite intaririle promise pentru apararea poporului sau, Solomon a scris el insusi acest mesaj urgent, cerandu-le ajutorul aliatilor din apropiere.",al={"cine a scris solomon's plea to westfall","de unde provine solomon's plea","creatorul lui solomon's plea"}},["6d6e291d"]={q="De ce vrea Gryan Stoutmantle Solomon's Plea to Westfall?",a="Gryan Stoutmantle conduce People's Militia in Westfall, iar acest mesaj il informeaza despre situatia cumplita din Lakeshire. Solomon spera ca militia poate trimite luptatori care sa intareasca apararea tot mai slabita din Redridge, in vreme ce orasul asteapta vesti si trupe de la curtea regelui Anduin din Stormwind.",al={"de ce sa duc rugamintea lui Solomon","de ce vrea Stoutmantle rugamintea","la ce foloseste scrisoarea"}}},fp="26,327,24.556.0,26.487.0,35.197.0,72.257.0,25.176.0,53.177.0"}
P.entries["item:soran-ruk-fragment"] = {n="Soran'ruk Fragment"}
P.entries["item:southsea-treasure"] = {n="Southsea Treasure",s="Southsea Treasure este o comoara valoroasa, pastrata adanc in cala navei Southsea Freebooter, Tide Razor. Wrenix the Wretched din Ratchet o cauta, iar recuperarea ei pune la incercare indemanarea novice a hotilor la descuiat si infiltrare.",h="Southsea Treasure este o comoara valoroasa, pastrata adanc in cala navei Southsea Freebooter, Tide Razor.",kw={"e.c.a.c.","descuiere","polly","ratchet","shattered hand","comoara Southsea","tide razor","wrenix the wretched"},ang={["class:Rogue"]="Recuperarea Southsea Treasure este un rit de initiere pentru rogues aflati in formare, oferindu-le atat exercitiu practic de spargere a incuietorilor in conditii reale, cat si o introducere in sindicatul din umbra cunoscut drept Shattered Hand.",["faction:Horde"]="Southsea Freebooters hartuie in mod regulat comertul din regiunea Barrens si din portul Ratchet, asa ca orice furt din ascunzatoarea lor centrala este o lovitura binevenita pentru autoritatile locale."},sec={{t="Un jaf mortal",b="Ancorata de-a lungul Merchant Coast, la sud de Ratchet, corabia piratilor Tide Razor serveste drept baza inaintata si teren de antrenament pentru Southsea Freebooters. Ascunsa in adancul celei mai de jos cale se afla o comoara ravnita, cunoscuta drept Southsea Treasure. Wrenix the Wretched, un ticalos goblin care isi are baza in Ratchet, o considera incercarea suprema pentru hotii de buzunare aspiranti. Potrivit lui Wrenix, ultimii cinci agenti trimisi sa fure cufarul s-au intors bucati, din cauza piratilor vigilenti de la bord si a unui paznic surprinzator de feroce, care supravegheaza cala."},{t="Amintirea lui Polly",b="Hotii care reusesc sa-i ocoleasca pe instructorii piratilor si sa descuie cufarul vizat au parte de o surpriza cumplita. Adevarata Southsea Treasure nu sta la indemana in cufar, ci este pazita de Polly, un papagal neobisnuit de ostil. Singura cale de a infrange pasarea feroce - adesea cu ajutorul ingineriei goblin, cum ar fi dispozitivul E.C.A.C. al lui Wrenix - si de a pune mana pe comoara este sa o aduci inapoi la Ratchet intreaga."}},faq={{q="Unde se afla Southsea Treasure?",a="Comoara se afla la bordul navei Tide Razor, a unui corsar Southsea ancorat de-a lungul coastei, la sud de Ratchet, in Barrens. Se gaseste in cala cea mai de jos, sub incaperile de antrenament ale piratilor.",al={"unde este comoara","locatia lui Tide Razor","cum gasesti comoara Southsea"}},{q="Cine vrea Southsea Treasure?",a="Wrenix the Wretched, un goblin lipsit de scrupule aflat in Ratchet, angajeaza agenti sub acoperire pentru a se infiltra pe nava si a-i recupera prada in numele lui.",al={"cine ofera misiunea","cine este Wrenix","cine il doreste"}},{q="De ce este cufarul gol cand il deschizi?",a="Deschiderea lacatului cufarului cu comori provoaca aparitia lui Polly, un papagal monstruos de agresiv care pazeste incinta. Infrangerea lui Polly este cea care iti aduce, de fapt, Southsea Treasure.",al={"de unde a venit Polly","de ce a aparut Polly","de ce nu se afla comoara in cutie"}},{q="Ce este un E.C.A.C. si de ce este necesar?",a="E.C.A.C. este un dispozitiv experimental goblin, oferit de Wrenix the Wretched. A fost conceput pentru a slabi amenintarile aeriene neobisnuit de feroce - mai precis, papagalul gardian letal Polly, care pandeste in cala corabiei piratilor.",al={"ce este ecac","cum sa-l invingi pe polly","papagal ostil"}},{q="La ce folosesc Southsea Freebooters corabia?",a="Tide Razor serveste drept baza de operatiuni si ascunzatoare pentru hotii din Southsea Freebooters. La al doilea nivel se afla cufere de antrenament, unde echipajul isi pregateste spargatorii de incuietori.",al={"ce este Tide Razor","barlogul piratilor din Barrens","magazia navei Southsea"}}},fx={c9f033cd={q="Ce este Southsea Treasure?",a="Southsea Treasure este prada adunata de Southsea Freebooters la bordul navei lor, Tide Razor, ancorata in largul coastei din Barrens. Ascunsa adanc in cala si pazita de Polly, un papagal pirat vestit pentru ferocitatea sa, comoara reprezinta castigurile obtinute necinstit de corsari in urma raidurilor de-a lungul Merchant Coast.",al={"ce este comoara southsea","obiectul comoara southsea","ce fel de comoara este comoara southsea"}}},fp="17,242,14.555.0,16.443.1,39.196.0,32.148.0,35.186.1,41.227.0,50.176.0"}
P.entries["item:spectral-comb"] = {n="Spectral Comb",s="Spectral Comb este o unealta eterica de ingrijire folosita pentru a interactiona cu mortii nelinistiti din Duskwood. Faurit sa treaca prin formele intangibile, este dus spiritului indurerat Blind Mary pentru a strange suvite de par fantomatic.",h="Spectral Comb este o unealta eterica de ingrijire folosita pentru a interactiona cu mortii nelinistiti din...",kw={"blind mary","pieptene","darkshire","duskwood","fantoma","fir de par de fantoma","pieptene spectral"},ang={["faction:Alliance"]="Calatoria spre sud de Darkshire cu pieptenele aminteste in mod dureros de soarta tragica a fostilor colonisti din Duskwood.",["profession:Tailoring"]="Spectral Comb arata ca, in locuri intunecate, croitoria necesita metode neobisnuite de recoltare: fibre eterice sunt obtinute de la fantome binevoitoare, nu prin tunderea traditionala."},sec={{t="O unealta pentru Restless Dead",b="Uneltele obisnuite nu pot atinge sau aranja un spirit, ceea ce face aproape imposibila strangerea materialelor eterice de catre mestesugarii muritori. Spectral Comb este special conceput pentru a interactiona cu formele fantomatice, alunecand prin plete altminteri intangibile. Este dus la sud de Darkshire, la ferma in ruine unde fantoma plangatoare Blind Mary boceste in singuratate. Gasind alinare in gestul familiar de a-si pieptana parul distrus, Mary foloseste de bunavoie pieptenele, lasand in urma fibrele spectrale necesare pentru teserea Ghost Hair Thread."}},faq={{q="La ce foloseste Spectral Comb?",a="Pieptenele ii este dat lui Blind Mary, o fantoma indurerata care salasluieste la sud de Darkshire. Cand se piaptana cu el, pieptenele aduna fire eterice care pot fi apoi toarse in ata supranaturala.",al={"scopul pieptenelui spectral","de ce am nevoie de pieptenele spectral","ce face pieptenele"}},{q="Cine este Blind Mary?",a="Blind Mary este un spirit chinuit care bantuie o casa parasita de pe dealurile de la sud de Darkshire. Innebunita de tragedie, si-a scos propriii ochi si continua sa se teama ca ceilalti o considera hidoasa chiar si dupa moarte.",al={"istoria lui Blind Mary","cine este fantoma cu pieptenele","Blind Mary"}},{q="De ce nu se poate folosi un pieptene obisnuit?",a="Spiritele nu pot fi atinse de unelte fizice obisnuite fara magie specializata sau descantece. Spectral Comb este conceput special pentru a interactiona cu parul intangibil al unei aparitii.",al={"de ce pieptenele spectral","pieptene obisnuit fantoma"}}},fx={e893aa2f={q="Ce este Spectral Comb?",a="Spectral Comb este un instrument de ingrijire eteric, fermecat special pentru a interactiona cu fiintele necorporale. In timp ce uneltele obisnuite ar trece printr-o fantoma fara sa aiba vreun efect, acest pieptene poate atinge, descurca si aduna firele spectrale din parul unei stafii.",al={"ce este pieptenele spectral","pieptene spectral","identitatea pieptenelui spectral"}}},fp="13,226,24.517.0,35.189.0,18.203.0,37.187.0"}
P.entries["item:spells-of-shadow"] = {n="Spells of Shadow"}
P.entries["item:spotted-sunfish"] = {n="Spotted Sunfish",s="Spotted Sunfish sunt pesti de apa dulce, autohtoni in Lake Everstill din Redridge Mountains. Renumiti pe plan local pentru gustul lor, sunt o marfa de baza pentru docurile din Lakeshire, desi infestarea tot mai grava cu murloci face capturarea lor periculoasa.",h="Spotted Sunfish sunt pesti de apa dulce, autohtoni in Lake Everstill din Redridge Mountains.",kw={"dockmaster baren","lake everstill","lakeshire","murloc","redridge mountains","selling fish","spotted sunfish"},ang={["profession:Cooking"]="Pestii autohtoni de apa dulce, precum pestele-soare patat, stau la baza gastronomiei din Lake Everstill si se regasesc negresit pe mesele tavernelor din Redridge."},sec={{t="O captura pretioasa",b="Lake Everstill este de multa vreme vestit pentru pestii-soare patati, care se vand la un pret sigur negustorilor locali si vizitatorilor deopotriva. Dockmaster Baren se ocupa de comertul cu acestia la pontoanele din Lakeshire, asigurand hrana si venituri unui oras aflat in dificultate. Totusi, triburile agresive de murloci care dau tarcoale apelor putin adanci au perturbat pescuitul obisnuit, adunandu-si adesea propriile capturi, pe care aventurierii trebuie sa le recupereze cu forta."}},faq={{q="Unde pot fi gasiti Spotted Sunfish?",a="Ei prospera in apele din Lake Everstill, in Redridge Mountains. Pescarii ii pot prinde direct din lac, dar si murlocii locali ii culeg intruna, asa ca taberele murlocilor de pe tarm sunt locuri ideale pentru a-i gasi.",al={"unde gasesc spotted sunfish","locatia pestelui spotted sunfish","pesti din Lake Everstill"}},{q="Cine cumpara sau are nevoie de Spotted Sunfish?",a="Dockmaster Baren, de la docurile din Lakeshire, cumpara loturi de Spotted Sunfish. Se ocupa cu acest deliciu si le ofera plata celor dispusi sa-i aduca marfa proaspata.",al={"cine vrea pesti soare patati","pestii Dockmaster Baren","misiunea Selling Fish"}},{q="De ce poarta murlocii acesti pesti?",a="Murlocii care traiesc de-a lungul lacului Lake Everstill cauta hrana si braconeaza fauna locala pentru a-si hrani triburile aflate in crestere. Scot pesti-soare din lac, la fel ca pescarii din rasa Human, si ii pastreaza in taberele lor de-a lungul apelor putin adanci.",al={"murloc care a vazut un pestisor-soare","de ce lasa murlocii pesti"}},{q="Ii poti obtine fara sa pescuiesti?",a="Da. Dockmaster Baren spune calatorii fara undita pot pur si simplu sa-i infranga pe murlocii ostili de-a lungul tarmurilor lacului Lake Everstill si sa ia pestii pe care acestia i-au prins.",al={"obtine sunfish fara undita","sunfish fara undita"}}},fx={["723094c5"]={q="Ce este un Spotted Sunfish?",a="Spotted Sunfish este un peste de apa dulce pretuit, originar din Lake Everstill, din Redridge Mountains. Renumit in intreaga regiune pentru gustul si valoarea sa comerciala, prospera in apele adanci ale lacului si este o marfa de baza pentru pescarii din Lakeshire, precum si o sursa principala de hrana pentru murlocii locali.",al={"ce este un peste-soare patat","informatii despre pestele-soare patat","povestea pestelui-soare patat"}},["1a933976"]={q="De unde provine Spotted Sunfish?",a="Spotted Sunfish traiesc in mod firesc in apele racoroase ale lacului Lake Everstill, din Redridge Mountains. Nu sunt confectionati sau crescuti, ci sunt pesti salbatici pescuiti direct din lac, fie de pe docuri si tarmuri, fie recuperati din ghearele braconierilor murloc locali.",al={"originea pestelui soare patat","de unde provin pestii soare patati","sursa pestelui soare patat"}}},fp="15,243,14.430.0,32.242.0,34.172.0,36.212.0,36.184.0"}
